-- ============================================================================
-- Banque de sujets QCM (Metre et Devis + Concours d'entree BTP)
-- 11 sujets, 360 questions au total, importes et verifies depuis :
--   - QCM_Metre_et_Devis_60_sujets.pdf (60 questions, "Fondamentaux")
--   - Banque Sujets BTP.pdf (10 sujets x 30 questions, beton arme/BAEL91,
--     RDM, planchers, topographie, VRD)
-- A executer dans l'editeur SQL de votre tableau de bord Supabase.
-- ============================================================================

-- 1. Table des sujets (epreuves)
create table public.qcm_subjects (
  id text primary key,
  title text not null,
  description text,
  "order" int not null default 0,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

alter table public.qcm_subjects enable row level security;
create policy "Lecture publique des sujets"
  on public.qcm_subjects for select
  using ( true );

-- 2. Table des questions
create table public.qcm_questions (
  id text primary key,
  subject_id text references public.qcm_subjects(id) on delete cascade not null,
  question_text text not null,
  options jsonb not null default '[]'::jsonb, -- [{ "id": "A", "text": "...", "isCorrect": true/false }]
  correct_answer text not null,               -- 'A' | 'B' | 'C' | 'D', redondant avec options[].isCorrect (lecture rapide)
  explanation text,
  "order" int not null default 0,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

alter table public.qcm_questions enable row level security;
create policy "Lecture publique des questions"
  on public.qcm_questions for select
  using ( true );

-- 3. Progression des utilisateurs connectes (un resultat par sujet passe)
create table public.qcm_results (
  id uuid default gen_random_uuid() primary key,
  user_id uuid references auth.users(id) on delete cascade not null,
  subject_id text references public.qcm_subjects(id) on delete cascade not null,
  score int not null default 0,
  total int not null default 0,
  answers jsonb not null default '{}'::jsonb, -- { question_id: option_id }
  completed_at timestamp with time zone default timezone('utc'::text, now()) not null
);

alter table public.qcm_results enable row level security;
create policy "Utilisateurs voient leurs resultats QCM"
  on public.qcm_results for select using ( auth.uid() = user_id );
create policy "Utilisateurs creent leurs resultats QCM"
  on public.qcm_results for insert with check ( auth.uid() = user_id );

