insert into public.qcm_subjects (id, title, description, "order") values ('fondamentaux', 'Fondamentaux — Métré et Devis (60 questions)', '60 questions', 1);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q1', 'fondamentaux', 'Le métré est défini comme :', '[{"id":"A","text":"La liste des ouvriers affectés à un chantier","isCorrect":false},{"id":"B","text":"La description détaillée de l''ouvrage en classant les travaux selon leur nature, leur coût, etc.","isCorrect":true},{"id":"C","text":"Le contrat signé entre le maître d''ouvrage et l''entrepreneur","isCorrect":false},{"id":"D","text":"Le plan architectural du bâtiment","isCorrect":false}]'::jsonb, 'B', 'Le métré évalue les éléments d''ouvrage à partir de leur mesure.', 1);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q2', 'fondamentaux', 'Le métré est présenté dans le cours comme étant à la fois :', '[{"id":"A","text":"Une science, une technique et un art","isCorrect":true},{"id":"B","text":"Une loi, un règlement et une norme","isCorrect":false},{"id":"C","text":"Un devis, un plan et un contrat","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 2);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q3', 'fondamentaux', 'Dans le métré, la dimension « science » renvoie à :', '[{"id":"A","text":"L''observation et la déduction dans le choix des quantités","isCorrect":false},{"id":"B","text":"L''application des connaissances mathématiques nécessaires au calcul des quantités","isCorrect":true},{"id":"C","text":"La connaissance des matériaux et de leur mise en œuvre","isCorrect":false},{"id":"D","text":"La rédaction des contrats","isCorrect":false}]'::jsonb, 'B', null, 3);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q4', 'fondamentaux', 'La dimension « art » du métré renvoie à :', '[{"id":"A","text":"Les facultés d''observation, d''adaptation et de déduction dans le choix des quantités et valeurs","isCorrect":true},{"id":"B","text":"L''application de formules mathématiques","isCorrect":false},{"id":"C","text":"La connaissance des matériaux","isCorrect":false},{"id":"D","text":"La signature des marchés","isCorrect":false}]'::jsonb, 'A', null, 4);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q5', 'fondamentaux', 'Le métré se relève des quantités :', '[{"id":"A","text":"Estimées avant travaux uniquement","isCorrect":false},{"id":"B","text":"« En œuvre », c''est-à-dire réalisées, par mesure de l''ouvrage en construction","isCorrect":true},{"id":"C","text":"Fixées par le maître d''ouvrage","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 5);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q6', 'fondamentaux', 'Il est fortement conseillé de relever au fur et à mesure :', '[{"id":"A","text":"Les parties d''ouvrage visibles uniquement","isCorrect":false},{"id":"B","text":"Les parties d''ouvrage susceptibles d''être cachées après achèvement","isCorrect":true},{"id":"C","text":"Uniquement le gros œuvre","isCorrect":false},{"id":"D","text":"Uniquement les finitions","isCorrect":false}]'::jsonb, 'B', null, 6);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q7', 'fondamentaux', 'On distingue deux sortes d''avant-métré, lesquelles ?', '[{"id":"A","text":"Avant-métré d''avant-projet et avant-métré d''exécution","isCorrect":true},{"id":"B","text":"Avant-métré public et avant-métré privé","isCorrect":false},{"id":"C","text":"Avant-métré théorique et avant-métré pratique","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 7);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q8', 'fondamentaux', 'L''avant-métré d''avant-projet est :', '[{"id":"A","text":"Établi après réception des travaux","isCorrect":false},{"id":"B","text":"Un état établi approximativement avant le dessin d''exécution","isCorrect":true},{"id":"C","text":"Identique au mémoire définitif","isCorrect":false},{"id":"D","text":"Réalisé uniquement pour les marchés publics","isCorrect":false}]'::jsonb, 'B', null, 8);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q9', 'fondamentaux', 'Un avant-projet définitif se caractérise par :', '[{"id":"A","text":"Des modifications fréquentes de quantités jusqu''à la fin des travaux","isCorrect":false},{"id":"B","text":"L''absence de toute modification des quantités ou prix initiaux jusqu''à la fin des travaux","isCorrect":true},{"id":"C","text":"L''absence de dessins","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 9);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q10', 'fondamentaux', 'L''avant-métré, par rapport au métré :', '[{"id":"A","text":"Se situe en amont du projet, alors que le métré s''exécute au fur et à mesure de la conception","isCorrect":true},{"id":"B","text":"Se réalise uniquement après la fin des travaux","isCorrect":false},{"id":"C","text":"N''a aucun lien avec le calcul des quantités","isCorrect":false},{"id":"D","text":"Est établi par le client uniquement","isCorrect":false}]'::jsonb, 'A', null, 10);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q11', 'fondamentaux', 'Les actes du métré comprennent notamment :', '[{"id":"A","text":"Les mémoires, le projet, les devis","isCorrect":true},{"id":"B","text":"Les factures, les salaires, les impôts","isCorrect":false},{"id":"C","text":"Les plans, les statuts, les procès-verbaux","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 11);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q12', 'fondamentaux', 'Les mémoires constituent :', '[{"id":"A","text":"Le plan d''exécution des travaux","isCorrect":false},{"id":"B","text":"La facture définitive des travaux, établie conformément aux prix unitaires du bordereau contractuel","isCorrect":true},{"id":"C","text":"Le devis estimatif provisoire","isCorrect":false},{"id":"D","text":"Le cahier des charges","isCorrect":false}]'::jsonb, 'B', null, 12);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q13', 'fondamentaux', 'Le projet, en tant qu''acte du métré, se compose de :', '[{"id":"A","text":"Dessins, notes de calcul, avant-métré, bordereau de prix","isCorrect":true},{"id":"B","text":"Uniquement des dessins","isCorrect":false},{"id":"C","text":"Uniquement du bordereau de prix","isCorrect":false},{"id":"D","text":"Uniquement des notes de calcul","isCorrect":false}]'::jsonb, 'A', null, 13);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q14', 'fondamentaux', 'Les notes de calcul dans le projet concernent notamment :', '[{"id":"A","text":"La résistance des constructions et les conditions d''exploitation","isCorrect":true},{"id":"B","text":"Le salaire des ouvriers","isCorrect":false},{"id":"C","text":"La durée du chantier uniquement","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 14);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q15', 'fondamentaux', 'Le bordereau de prix groupe :', '[{"id":"A","text":"Les différents prix unitaires en tenant compte des fournitures, bénéfices, taxes","isCorrect":true},{"id":"B","text":"Uniquement les salaires des ouvriers","isCorrect":false},{"id":"C","text":"Uniquement les impôts","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 15);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q16', 'fondamentaux', 'Les devis peuvent être établis :', '[{"id":"A","text":"Uniquement sur plan","isCorrect":false},{"id":"B","text":"Uniquement après repérage sur place","isCorrect":false},{"id":"C","text":"Sur plan, après repérage sur place, ou les deux à la fois selon le type de travaux","isCorrect":true},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'C', null, 16);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q17', 'fondamentaux', 'Pour des travaux neufs, le devis est établi :', '[{"id":"A","text":"Entièrement sur plan","isCorrect":true},{"id":"B","text":"Entièrement après repérage sur place","isCorrect":false},{"id":"C","text":"Toujours à la fois sur plan et sur place","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 17);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q18', 'fondamentaux', 'Pour des travaux existants, le devis est établi :', '[{"id":"A","text":"Entièrement sur plan","isCorrect":false},{"id":"B","text":"Entièrement après repérage et mesures sur les travaux existants","isCorrect":true},{"id":"C","text":"Jamais","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 18);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q19', 'fondamentaux', 'On distingue trois formes de devis, lesquelles ?', '[{"id":"A","text":"Quantitatif, descriptif, estimatif","isCorrect":true},{"id":"B","text":"Public, privé, mixte","isCorrect":false},{"id":"C","text":"Provisoire, définitif, annulé","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 19);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q20', 'fondamentaux', 'Le devis quantitatif :', '[{"id":"A","text":"Applique un prix unitaire à chaque quantité","isCorrect":false},{"id":"B","text":"Donne le détail et le résumé complet des quantités d''ouvrage, sans application de valeur","isCorrect":true},{"id":"C","text":"Décrit uniquement les matériaux utilisés","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 20);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q21', 'fondamentaux', 'Le devis descriptif :', '[{"id":"A","text":"Décrit tous les ouvrages ou parties d''ouvrages demandés aux différents corps d''état","isCorrect":true},{"id":"B","text":"Donne uniquement le prix total du projet","isCorrect":false},{"id":"C","text":"Est rédigé uniquement par le maître d''ouvrage","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 21);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q22', 'fondamentaux', 'Le devis descriptif doit être :', '[{"id":"A","text":"Approximatif et laisser place à interprétation","isCorrect":false},{"id":"B","text":"Complet, clair, sans place à l''interprétation","isCorrect":true},{"id":"C","text":"Rédigé après la fin des travaux uniquement","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 22);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q23', 'fondamentaux', 'Le devis estimatif :', '[{"id":"A","text":"Applique un prix unitaire à chaque quantité pour obtenir le prix total du projet","isCorrect":true},{"id":"B","text":"Ne contient aucune quantité","isCorrect":false},{"id":"C","text":"Est identique au devis descriptif","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 23);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q24', 'fondamentaux', 'Le devis descriptif (bordereau descriptif) est généralement rédigé par :', '[{"id":"A","text":"Les métreurs, en collaboration avec les auteurs du projet","isCorrect":true},{"id":"B","text":"Le maître d''ouvrage seul","isCorrect":false},{"id":"C","text":"L''entrepreneur seul, sans concertation","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 24);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q25', 'fondamentaux', 'Le devis descriptif sert de guide :', '[{"id":"A","text":"Uniquement avant le début des travaux","isCorrect":false},{"id":"B","text":"Pendant l''exécution des travaux","isCorrect":true},{"id":"C","text":"Uniquement après réception des travaux","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 25);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q26', 'fondamentaux', 'L''estimation sommaire d''un devis a pour objectif :', '[{"id":"A","text":"De remplacer définitivement le devis détaillé","isCorrect":false},{"id":"B","text":"De savoir si le coût final est compatible avec les possibilités financières du client avant le stade définitif","isCorrect":true},{"id":"C","text":"De fixer le prix contractuel final","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 26);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q27', 'fondamentaux', 'L''établissement d''un devis est impossible si :', '[{"id":"A","text":"On ne connaît pas exactement ce qui doit être réalisé selon le plan de l''architecte","isCorrect":true},{"id":"B","text":"On n''a pas encore choisi l''entrepreneur","isCorrect":false},{"id":"C","text":"Le chantier n''est pas encore ouvert","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 27);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q28', 'fondamentaux', 'Le devis descriptif est considéré comme :', '[{"id":"A","text":"Une pièce secondaire du marché","isCorrect":false},{"id":"B","text":"La pièce la plus importante du marché entre le maître d''ouvrage et l''entrepreneur","isCorrect":true},{"id":"C","text":"Un simple document informatif sans valeur contractuelle","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 28);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q29', 'fondamentaux', 'Le maître d''ouvrage désigne :', '[{"id":"A","text":"L''ingénieur qui conçoit les plans","isCorrect":false},{"id":"B","text":"Le propriétaire du terrain, de l''ouvrage ou du projet","isCorrect":true},{"id":"C","text":"L''entreprise qui exécute les travaux","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 29);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q30', 'fondamentaux', 'Le maître d''œuvre est :', '[{"id":"A","text":"Le propriétaire du terrain","isCorrect":false},{"id":"B","text":"Le professionnel (architecte, ingénieur, bureau d''études) chargé d''assurer tout ou partie des missions du projet","isCorrect":true},{"id":"C","text":"L''ouvrier sur le chantier","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 30);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q31', 'fondamentaux', 'Parmi les missions du maître d''œuvre, on trouve :', '[{"id":"A","text":"L''établissement des plans et devis descriptifs, les appels d''offres, le contrôle de l''exécution","isCorrect":true},{"id":"B","text":"Le paiement des impôts fonciers","isCorrect":false},{"id":"C","text":"L''octroi du permis de construire","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 31);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q32', 'fondamentaux', 'L''entrepreneur est :', '[{"id":"A","text":"La personne physique ou morale qui intervient pour exécuter les travaux","isCorrect":true},{"id":"B","text":"Le propriétaire de l''ouvrage","isCorrect":false},{"id":"C","text":"L''architecte chargé des plans","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 32);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q33', 'fondamentaux', 'Le sous-traitant est :', '[{"id":"A","text":"L''entrepreneur principal","isCorrect":false},{"id":"B","text":"L''entrepreneur qui exécute un travail sous-traité","isCorrect":true},{"id":"C","text":"Le maître d''ouvrage","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 33);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q34', 'fondamentaux', 'Le chantier est défini comme :', '[{"id":"A","text":"Une installation permanente","isCorrect":false},{"id":"B","text":"Une installation temporaire en plein air qui disparaît à l''achèvement des travaux","isCorrect":true},{"id":"C","text":"Le bureau d''études de l''entreprise","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 34);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q35', 'fondamentaux', 'Le prix « clé en main » :', '[{"id":"A","text":"Tient compte des conditions réelles d''exécution des travaux","isCorrect":false},{"id":"B","text":"Est un prix théorique correspondant à des prestations, sans tenir compte des conditions réelles","isCorrect":true},{"id":"C","text":"N''existe pas dans la pratique du BTP","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 35);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q36', 'fondamentaux', 'Le cahier des charges précède les conventions et contrats de construction sur le plan :', '[{"id":"A","text":"Administratif, juridique et technique","isCorrect":true},{"id":"B","text":"Uniquement technique","isCorrect":false},{"id":"C","text":"Uniquement financier","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 36);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q37', 'fondamentaux', 'Le sigle DAO signifie :', '[{"id":"A","text":"Document d''Appel d''Offre","isCorrect":true},{"id":"B","text":"Devis Approuvé par l''Ouvrage","isCorrect":false},{"id":"C","text":"Dossier d''Achèvement des Ouvrages","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 37);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q38', 'fondamentaux', 'Parmi les propositions suivantes, laquelle n''est PAS un corps d''état du bâtiment ?', '[{"id":"A","text":"Maçonnerie","isCorrect":false},{"id":"B","text":"Plomberie","isCorrect":false},{"id":"C","text":"Comptabilité générale de l''entreprise","isCorrect":true},{"id":"D","text":"Électricité","isCorrect":false}]'::jsonb, 'C', null, 38);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q39', 'fondamentaux', 'Un marché public peut concerner :', '[{"id":"A","text":"Uniquement les travaux","isCorrect":false},{"id":"B","text":"Les travaux, les fournitures, les services et les prestations intellectuelles","isCorrect":true},{"id":"C","text":"Uniquement les fournitures","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 39);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q40', 'fondamentaux', 'Le terme « marché » renvoie à la notion de :', '[{"id":"A","text":"Contrat / convention créant des effets en droit","isCorrect":true},{"id":"B","text":"Simple devis estimatif","isCorrect":false},{"id":"C","text":"Bordereau de prix uniquement","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', null, 40);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q41', 'fondamentaux', 'La formule générale pour calculer le nombre de sacs de ciment est :', '[{"id":"A","text":"Q.ciment = (V × Dosage) / 50","isCorrect":true},{"id":"B","text":"Q.ciment = V × 50 / Dosage","isCorrect":false},{"id":"C","text":"Q.ciment = V + Dosage","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', '50 kg correspond au poids standard d''un sac de ciment.', 41);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q42', 'fondamentaux', 'Le poids standard d''un sac de ciment utilisé dans les formules du cours est :', '[{"id":"A","text":"25 kg","isCorrect":false},{"id":"B","text":"40 kg","isCorrect":false},{"id":"C","text":"50 kg","isCorrect":true},{"id":"D","text":"100 kg","isCorrect":false}]'::jsonb, 'C', null, 42);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q43', 'fondamentaux', 'La formule usuelle pour la quantité de sable dans un béton est :', '[{"id":"A","text":"Q.sable = V × 0,4 × 1,5","isCorrect":true},{"id":"B","text":"Q.sable = V × 1,3 × 1,6","isCorrect":false},{"id":"C","text":"Q.sable = V / Dosage","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', '0,4 est le coefficient de proportionnalité du sable, 1,5 la densité du sable.', 43);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q44', 'fondamentaux', 'La densité du sable utilisée pour la conversion m³ → tonne dans le cours est :', '[{"id":"A","text":"1,2","isCorrect":false},{"id":"B","text":"1,5","isCorrect":true},{"id":"C","text":"1,6","isCorrect":false},{"id":"D","text":"2,0","isCorrect":false}]'::jsonb, 'B', null, 44);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q45', 'fondamentaux', 'La formule usuelle pour la quantité de concassés 8/15 dans un béton est :', '[{"id":"A","text":"Q.concassés = V × 0,8 × 1,6","isCorrect":true},{"id":"B","text":"Q.concassés = V × 0,4 × 1,5","isCorrect":false},{"id":"C","text":"Q.concassés = V / 50","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'A', '0,8 est le coefficient de proportionnalité des concassés, 1,6 leur densité.', 45);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q46', 'fondamentaux', 'La densité des concassés/graviers utilisée dans le cours est :', '[{"id":"A","text":"1,4","isCorrect":false},{"id":"B","text":"1,5","isCorrect":false},{"id":"C","text":"1,6","isCorrect":true},{"id":"D","text":"1,8","isCorrect":false}]'::jsonb, 'C', null, 46);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q47', 'fondamentaux', 'Pour la maçonnerie de fondation en moellons, le coefficient de proportionnalité des moellons par m³ est :', '[{"id":"A","text":"0,8","isCorrect":false},{"id":"B","text":"1,0","isCorrect":false},{"id":"C","text":"1,3","isCorrect":true},{"id":"D","text":"1,6","isCorrect":false}]'::jsonb, 'C', null, 47);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q48', 'fondamentaux', 'L''épaisseur habituelle du béton de propreté se situe entre :', '[{"id":"A","text":"2 et 5 cm","isCorrect":false},{"id":"B","text":"7 et 10 cm","isCorrect":true},{"id":"C","text":"15 et 20 cm","isCorrect":false},{"id":"D","text":"25 et 30 cm","isCorrect":false}]'::jsonb, 'B', null, 48);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q49', 'fondamentaux', 'Le dosage du béton de propreté varie généralement entre :', '[{"id":"A","text":"50 et 100 kg/m³","isCorrect":false},{"id":"B","text":"150 et 250 kg/m³","isCorrect":true},{"id":"C","text":"300 et 400 kg/m³","isCorrect":false},{"id":"D","text":"400 et 500 kg/m³","isCorrect":false}]'::jsonb, 'B', null, 49);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q50', 'fondamentaux', 'Pour l''estimation des aciers dans les poteaux en béton armé, le cours retient environ :', '[{"id":"A","text":"30 kg par m³ de béton armé","isCorrect":false},{"id":"B","text":"80 kg par m³ de béton armé","isCorrect":true},{"id":"C","text":"150 kg par m³ de béton armé","isCorrect":false},{"id":"D","text":"200 kg par m³ de béton armé","isCorrect":false}]'::jsonb, 'B', null, 50);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q51', 'fondamentaux', 'Pour l''estimation des aciers dans les poutres en béton armé, le cours retient environ :', '[{"id":"A","text":"50 kg par m³","isCorrect":false},{"id":"B","text":"80 kg par m³","isCorrect":false},{"id":"C","text":"130 kg par m³","isCorrect":true},{"id":"D","text":"200 kg par m³","isCorrect":false}]'::jsonb, 'C', null, 51);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q52', 'fondamentaux', 'Pour l''estimation des aciers dans une dalle (plancher), le cours retient environ :', '[{"id":"A","text":"10 à 15 kg par m³","isCorrect":false},{"id":"B","text":"30 à 40 kg par m³","isCorrect":true},{"id":"C","text":"80 kg par m³","isCorrect":false},{"id":"D","text":"130 kg par m³","isCorrect":false}]'::jsonb, 'B', null, 52);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q53', 'fondamentaux', 'La surface standard d''un bloc aggloméré (0,40 m × 0,20 m) est :', '[{"id":"A","text":"0,04 m²","isCorrect":false},{"id":"B","text":"0,08 m²","isCorrect":true},{"id":"C","text":"0,12 m²","isCorrect":false},{"id":"D","text":"0,20 m²","isCorrect":false}]'::jsonb, 'B', '0,40 × 0,20 = 0,08 m².', 53);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q54', 'fondamentaux', 'Pour 1 m² de maçonnerie, le nombre de blocs standards nécessaires est d''environ :', '[{"id":"A","text":"8 blocs","isCorrect":false},{"id":"B","text":"13 blocs","isCorrect":true},{"id":"C","text":"20 blocs","isCorrect":false},{"id":"D","text":"25 blocs","isCorrect":false}]'::jsonb, 'B', '1 / 0,08 = 12,5, arrondi à 13.', 54);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q55', 'fondamentaux', 'Pour le calcul du nombre de blocs, un coefficient de majoration (pertes/ajustement) est appliqué. Il est de :', '[{"id":"A","text":"1,00","isCorrect":false},{"id":"B","text":"1,05","isCorrect":true},{"id":"C","text":"1,20","isCorrect":false},{"id":"D","text":"1,50","isCorrect":false}]'::jsonb, 'B', null, 55);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q56', 'fondamentaux', 'Pour le crépissage, on ajoute à la surface utile une largeur supplémentaire par arête de :', '[{"id":"A","text":"5 cm","isCorrect":false},{"id":"B","text":"10 cm","isCorrect":false},{"id":"C","text":"15 cm","isCorrect":true},{"id":"D","text":"20 cm","isCorrect":false}]'::jsonb, 'C', null, 56);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q57', 'fondamentaux', 'Pour la peinture, contrairement au crépissage :', '[{"id":"A","text":"On ajoute 15 cm de largeur par arête également","isCorrect":false},{"id":"B","text":"On n''ajoute pas les 15 cm par arête","isCorrect":true},{"id":"C","text":"On double la surface utile","isCorrect":false},{"id":"D","text":"Aucune des réponses","isCorrect":false}]'::jsonb, 'B', null, 57);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q58', 'fondamentaux', 'Selon les abaques du cours, 1 kg de latex couvre en une couche :', '[{"id":"A","text":"3 m²","isCorrect":false},{"id":"B","text":"5 m²","isCorrect":true},{"id":"C","text":"6 m²","isCorrect":false},{"id":"D","text":"8 m²","isCorrect":false}]'::jsonb, 'B', null, 58);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q59', 'fondamentaux', 'Selon les abaques du cours, 1 kg de chaux couvre en une couche :', '[{"id":"A","text":"5 m²","isCorrect":false},{"id":"B","text":"6 m²","isCorrect":false},{"id":"C","text":"8 m²","isCorrect":true},{"id":"D","text":"10 m²","isCorrect":false}]'::jsonb, 'C', null, 59);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('f-q60', 'fondamentaux', 'Un mur intérieur a une surface totale de 180 m², dont 20 m² d''ouvertures (baies). L''épaisseur de l''enduit est de 0,02 m. Quel est le volume d''enduit nécessaire ?', '[{"id":"A","text":"3,2 m³","isCorrect":true},{"id":"B","text":"3,6 m³","isCorrect":false},{"id":"C","text":"4,0 m³","isCorrect":false},{"id":"D","text":"4,4 m³","isCorrect":false}]'::jsonb, 'A', 'Surface utile = 180 − 20 = 160 m² ; Volume = 160 × 0,02 = 3,2 m³.', 60);
insert into public.qcm_subjects (id, title, description, "order") values ('concours-sujet-1', 'Sujet 1 — Concours d''entrée BTP', '30 questions', 2);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q1', 'concours-sujet-1', 'Dans la relation f_bu = 0,85.f_c28 / (θ.γb), avec une durée d''application de la combinaison d''action considérée t = 15 min,', '[{"id":"A","text":"θ = 1,15","isCorrect":false},{"id":"B","text":"θ = 0,9","isCorrect":false},{"id":"C","text":"θ = 0,85","isCorrect":true},{"id":"D","text":"θ = 1","isCorrect":false}]'::jsonb, 'C', 'BAEL91 (A.4.3,41) : θ=1 si t>24h ; θ=0,9 si 1h<t≤24h ; θ=0,85 si t<1h. Ici t=15 min, donc θ=0,85.', 1);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q2', 'concours-sujet-1', 'Le coefficient de fissuration η pour une armature Haute Adhérence de diamètre φ=12mm est', '[{"id":"A","text":"η = 1","isCorrect":false},{"id":"B","text":"η = 1,3","isCorrect":false},{"id":"C","text":"η = 2","isCorrect":false},{"id":"D","text":"η = 1,6","isCorrect":true}]'::jsonb, 'D', 'BAEL91 (A.4.5,3) : η=1 pour les ronds lisses (RL) ; η=1,6 pour les armatures Haute Adhérence (HA).', 2);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q3', 'concours-sujet-1', 'Le retrait du béton Δl/l en climat très humide vaut, à défaut de mesures (BAEL91) :', '[{"id":"A","text":"2 × 10⁻⁴","isCorrect":false},{"id":"B","text":"1,5 × 10⁻⁴","isCorrect":true},{"id":"C","text":"4 × 10⁻⁴","isCorrect":false},{"id":"D","text":"3 × 10⁻⁴","isCorrect":false}]'::jsonb, 'B', 'BAEL91 : retrait forfaitaire = 1,5×10⁻⁴ (très humide), 2×10⁻⁴ (humide), 3×10⁻⁴ (tempéré sec), 4×10⁻⁴ (chaud et sec), 5×10⁻⁴ (très sec/désertique).', 3);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q4', 'concours-sujet-1', 'L''allongement de l''armature la plus tendue εs=10×10⁻³ (pivot correspondant) se trouve', '[{"id":"A","text":"Aucune","isCorrect":false},{"id":"B","text":"Pivot C","isCorrect":false},{"id":"C","text":"Pivot A","isCorrect":true},{"id":"D","text":"Pivot B","isCorrect":false}]'::jsonb, 'C', 'BAEL91 (A.4.3,3), règle des 3 pivots : Pivot A → allongement acier 10‰ ; Pivot B → raccourcissement béton 3,5‰ ; Pivot C → section entièrement comprimée. L''allongement unitaire de l''armature la plus tendue atteint 10 pour mille (10×10⁻³).', 4);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q5', 'concours-sujet-1', 'En fissuration peu préjudiciable, la contrainte limite de traction des aciers est :', '[{"id":"A","text":"σs ≤ min(0,5fe ; 110√(η.ftj))","isCorrect":false},{"id":"B","text":"σs = fe/γs (aucune limitation supplémentaire liée à la fissuration)","isCorrect":true},{"id":"C","text":"σs ≤ (2/3)fe","isCorrect":false},{"id":"D","text":"σs ≤ min(0,5fe ; 90√(η.ftj))","isCorrect":false}]'::jsonb, 'B', 'BAEL91 (A.4.5,3) : peu préjudiciable → pas de limite spécifique (σs=fe/γs) ; préjudiciable → min{2/3fe ; max[0,5fe;110√(η.ftj)]} ; très préjudiciable → min[0,5fe ; 90√(η.ftj)].', 5);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q6', 'concours-sujet-1', 'À l''ELU, la contrainte de dimensionnement (calcul) de l''acier est', '[{"id":"A","text":"σs = 0,85.fc28/(θ.γb)","isCorrect":false},{"id":"B","text":"σs = 0,8.fe","isCorrect":false},{"id":"C","text":"σs = fe/γs","isCorrect":true},{"id":"D","text":"σs = 0,6.fc28","isCorrect":false}]'::jsonb, 'C', 'À l''ELU, dans le domaine des pivots A et B (palier plastique), la contrainte de calcul de l''acier vaut fe/γs (γs=1,15 en combinaison fondamentale).', 6);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q7', 'concours-sujet-1', 'Dans la relation f_bu = 0,85.f_c28/(θ.γb), l''unité considérée pour f_bu est le', '[{"id":"A","text":"bar","isCorrect":false},{"id":"B","text":"kg/cm²","isCorrect":false},{"id":"C","text":"Pa (pascal)","isCorrect":false},{"id":"D","text":"MPa (mégapascal)","isCorrect":true}]'::jsonb, 'D', 'f_bu (contrainte de calcul du béton à l''ELU) et f_c28 s''expriment en MPa dans les formules du BAEL91.', 7);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q8', 'concours-sujet-1', 'Le coefficient γb pour les combinaisons fondamentales vaut', '[{"id":"A","text":"1,35","isCorrect":false},{"id":"B","text":"1,5","isCorrect":true},{"id":"C","text":"1","isCorrect":false},{"id":"D","text":"1,15","isCorrect":false}]'::jsonb, 'B', 'BAEL91 : γb = 1,5 pour les combinaisons fondamentales, γb = 1,15 pour les combinaisons accidentelles.', 8);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q9', 'concours-sujet-1', 'Un béton a une résistance en compression f_c28 = 20 MPa. Quelle est sa résistance en traction f_t28 (formule f_t28 = 0,6+0,06.f_c28) ?', '[{"id":"A","text":"1.2 MPa","isCorrect":false},{"id":"B","text":"12.6 MPa","isCorrect":false},{"id":"C","text":"1.8 MPa","isCorrect":true},{"id":"D","text":"2.3 MPa","isCorrect":false}]'::jsonb, 'C', 'f_t28 = 0,6 + 0,06 × 20 = 1.8 MPa.', 9);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q10', 'concours-sujet-1', 'On applique sur une éprouvette de béton de diamètre d=16 cm un effort de compression de 1500 N. Quelle est la valeur de la contrainte de compression (σ=F/S, S=π.d²/4) ?', '[{"id":"A","text":"64 905 Pa","isCorrect":false},{"id":"B","text":"52 223 Pa","isCorrect":false},{"id":"C","text":"85 794 Pa","isCorrect":false},{"id":"D","text":"74 604 Pa","isCorrect":true}]'::jsonb, 'D', 'S = π × (0,16)²/4 = 0.020106 m². σ = F/S = 1500/0.020106 = 74 604 Pa (arrondi).', 10);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q11', 'concours-sujet-1', 'Soit une poutre isostatique AB, reposant sur des appuis simples en A et B distants de L, supportant une charge concentrée P située à la distance a de l''appui A et b de l''appui B (a+b=L). L''expression de RA est :', '[{"id":"A","text":"R_A = P(1-a/L)","isCorrect":false},{"id":"B","text":"R_A = P.b/L","isCorrect":true},{"id":"C","text":"R_A = P.a/L","isCorrect":false},{"id":"D","text":"R_A = P.a²/L","isCorrect":false}]'::jsonb, 'B', 'Équilibre des moments : ΣM/B=0 → R_A × L = P × b → R_A=P.b/L. De même R_B=P.a/L (R_A+R_B=P).', 11);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q12', 'concours-sujet-1', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour un appui simple de poutre ?', '[{"id":"A","text":"4","isCorrect":false},{"id":"B","text":"2","isCorrect":false},{"id":"C","text":"3","isCorrect":false},{"id":"D","text":"1","isCorrect":true}]'::jsonb, 'D', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 12);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q13', 'concours-sujet-1', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour une articulation de poutre ?', '[{"id":"A","text":"4","isCorrect":false},{"id":"B","text":"3","isCorrect":false},{"id":"C","text":"2","isCorrect":true},{"id":"D","text":"1","isCorrect":false}]'::jsonb, 'C', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 13);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q14', 'concours-sujet-1', 'Les blocs creux (éléments de remplissage) des planchers à corps creux sont appelés', '[{"id":"A","text":"Agglomérés","isCorrect":false},{"id":"B","text":"Nervures","isCorrect":false},{"id":"C","text":"Hourdis (ou entrevous)","isCorrect":true},{"id":"D","text":"Poutrelles","isCorrect":false}]'::jsonb, 'C', 'Les éléments de remplissage/coffrage perdu d''un plancher à corps creux sont appelés hourdis, ou entrevous.', 14);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q15', 'concours-sujet-1', 'La dalle de béton coulée sur les hourdis d''un plancher à corps creux est appelée', '[{"id":"A","text":"Dallage","isCorrect":false},{"id":"B","text":"Semelle filante","isCorrect":false},{"id":"C","text":"Radier","isCorrect":false},{"id":"D","text":"Dalle de compression (ou table de compression)","isCorrect":true}]'::jsonb, 'D', 'La fine dalle armée (souvent 4 à 5 cm) coulée au-dessus des hourdis/nervures est la dalle (ou table) de compression.', 15);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q16', 'concours-sujet-1', 'La semelle de fondation située sous un mur (fondation continue) est appelée', '[{"id":"A","text":"Semelle filante","isCorrect":true},{"id":"B","text":"Semelle isolée","isCorrect":false},{"id":"C","text":"Semelle sur pieux","isCorrect":false},{"id":"D","text":"Radier","isCorrect":false}]'::jsonb, 'A', 'Une semelle continue sous un mur porteur est une semelle filante, par opposition à une semelle isolée sous un poteau.', 16);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q17', 'concours-sujet-1', 'Une dalle rectangulaire appuyée sur ses quatre côtés, avec lx/ly > 0,4 (lx = plus petite portée), porte suivant', '[{"id":"A","text":"Deux sens","isCorrect":true},{"id":"B","text":"Un sens","isCorrect":false},{"id":"C","text":"Aucun sens (dalle non porteuse)","isCorrect":false},{"id":"D","text":"Quatre sens","isCorrect":false}]'::jsonb, 'A', 'Règle courante (BAEL/annexe E) : si lx/ly > 0,4, la dalle porte dans les deux sens (flexion bidirectionnelle) ; en dessous, on la calcule comme portant dans un seul sens.', 17);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q18', 'concours-sujet-1', 'Une dalle située au niveau d''un étage (et non au rez-de-chaussée sur terre-plein) est appelée', '[{"id":"A","text":"Dallage","isCorrect":false},{"id":"B","text":"Plancher","isCorrect":true},{"id":"C","text":"Radier","isCorrect":false},{"id":"D","text":"Dalle sur vide sanitaire","isCorrect":false}]'::jsonb, 'B', 'Par convention, on réserve le terme « plancher » à une dalle d''étage (porteuse, en élévation), et « dallage »/« dalle sur terre-plein » à une dalle basse posée sur le sol.', 18);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q19', 'concours-sujet-1', 'L''altitude relative d''un point est', '[{"id":"A","text":"La position (en hauteur) du point par rapport à un point de référence fixe, choisi arbitrairement pour le chantier","isCorrect":true},{"id":"B","text":"La position du point par rapport au géoïde","isCorrect":false},{"id":"C","text":"La position du point par rapport au niveau de la mer","isCorrect":false},{"id":"D","text":"Une notion qui n''existe pas en topographie","isCorrect":false}]'::jsonb, 'A', 'Contrairement à l''altitude absolue (repérée au niveau de la mer/géoïde, IGN par exemple), l''altitude relative se mesure par rapport à un repère local arbitraire (souvent une borne ou un point fixe du chantier).', 19);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q20', 'concours-sujet-1', 'La visée avant, en nivellement, est', '[{"id":"A","text":"La visée faite sur le point dont on cherche à déterminer l''altitude (point inconnu)","isCorrect":true},{"id":"B","text":"La visée faite sur le premier point observé","isCorrect":false},{"id":"C","text":"La visée faite sur le point d''altitude connue","isCorrect":false},{"id":"D","text":"La visée faite dans le sens du parcours uniquement","isCorrect":false}]'::jsonb, 'A', 'Par convention : la visée arrière se fait sur un point d''altitude CONNUE (ou de référence), la visée avant sur le point dont on veut DÉTERMINER l''altitude.', 20);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q21', 'concours-sujet-1', 'La visée entre deux points A et B a donné les résultats suivants : visée arrière 2770 mm ; visée avant 3500 mm. Quelle est la valeur de la dénivelée entre les deux points ?', '[{"id":"A","text":"-730 mm","isCorrect":true},{"id":"B","text":"6270 mm","isCorrect":false},{"id":"C","text":"730 mm","isCorrect":false},{"id":"D","text":"-6270 mm","isCorrect":false}]'::jsonb, 'A', 'Dénivelée = Visée arrière − Visée avant = 2770 − 3500 = -730 mm.', 21);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q22', 'concours-sujet-1', 'La mesure directe des distances peut se faire :', '[{"id":"A","text":"À l''aide du cercle optique","isCorrect":false},{"id":"B","text":"À l''aide d''un théodolite","isCorrect":false},{"id":"C","text":"À l''aide d''une mire seule","isCorrect":false},{"id":"D","text":"Au ruban (ou au décamètre/chaîne d''arpenteur)","isCorrect":true}]'::jsonb, 'D', 'Une mesure DIRECTE consiste à appliquer physiquement un instrument gradué (ruban, décamètre) le long de la distance à mesurer. Le théodolite et la mire, eux, servent à des mesures INDIRECTES (angles, nivellement optique).', 22);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q23', 'concours-sujet-1', 'À quoi sert l''armature dans le béton armé ?', '[{"id":"A","text":"Empêcher le béton de rompre au flambement","isCorrect":false},{"id":"B","text":"Reprendre les efforts de traction du béton","isCorrect":true},{"id":"C","text":"Reprendre les efforts de compression du béton","isCorrect":false},{"id":"D","text":"Augmenter la résistance du béton en compression","isCorrect":false}]'::jsonb, 'B', 'Le béton résiste bien en compression mais très mal en traction : l''acier, qui résiste bien en traction, est associé au béton pour reprendre ces efforts (principe fondateur du béton armé).', 23);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q24', 'concours-sujet-1', 'Le système qui sépare la collecte des eaux usées/vannes et celle des eaux pluviales, dans deux réseaux distincts, est appelé', '[{"id":"A","text":"Le système mixte","isCorrect":false},{"id":"B","text":"Le système combiné","isCorrect":false},{"id":"C","text":"Le système unitaire","isCorrect":false},{"id":"D","text":"Le système séparatif","isCorrect":true}]'::jsonb, 'D', 'Le système séparatif utilise 2 réseaux distincts (eaux usées/vannes d''un côté, eaux pluviales de l''autre) ; le système unitaire les collecte ensemble dans un seul réseau.', 24);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q25', 'concours-sujet-1', 'Le traitement des eaux usées permet avant tout de', '[{"id":"A","text":"Polluer volontairement les cultures en aval","isCorrect":false},{"id":"B","text":"N''a aucune utilité réelle","isCorrect":false},{"id":"C","text":"Uniquement embellir le paysage","isCorrect":false},{"id":"D","text":"Protéger l''environnement (et la santé publique) en évitant le rejet de pollution dans le milieu naturel","isCorrect":true}]'::jsonb, 'D', 'Le traitement des eaux usées vise à réduire la charge polluante avant rejet dans le milieu naturel, protégeant ainsi l''environnement et la santé publique.', 25);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q26', 'concours-sujet-1', 'À quoi sert la vibration du béton lors de sa mise en œuvre ?', '[{"id":"A","text":"Augmenter la résistance du béton au feu","isCorrect":false},{"id":"B","text":"Augmenter la résistance mécanique finale du béton au-delà de sa formulation","isCorrect":false},{"id":"C","text":"Accélérer la prise du ciment","isCorrect":false},{"id":"D","text":"Empêcher la ségrégation des granulats et chasser les bulles d''air (nids de cailloux)","isCorrect":true}]'::jsonb, 'D', 'La vibration remplit correctement le coffrage, chasse l''air emprisonné et évite la ségrégation (séparation gravier/mortier), améliorant la compacité réelle du béton en place.', 26);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q27', 'concours-sujet-1', 'À quoi servent les dévers sur une chaussée ?', '[{"id":"A","text":"Uniquement améliorer l''esthétique de la route","isCorrect":false},{"id":"B","text":"Augmenter la vitesse autorisée des véhicules","isCorrect":false},{"id":"C","text":"Réduire la largeur utile de la chaussée","isCorrect":false},{"id":"D","text":"Faciliter l''évacuation des eaux de ruissellement (et améliorer la tenue des véhicules en courbe)","isCorrect":true}]'::jsonb, 'D', 'Le dévers (pente transversale) évacue l''eau de pluie vers les côtés de la chaussée et, en courbe, contribue à compenser la force centrifuge subie par les véhicules.', 27);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q28', 'concours-sujet-1', 'Une largeur de voie de circulation courante retenue en dimensionnement routier est de l''ordre de 3,50 m ; pour une route à deux voies, cela correspond à une largeur de chaussée de l''ordre de', '[{"id":"A","text":"7 mètres","isCorrect":true},{"id":"B","text":"6,5 mètres","isCorrect":false},{"id":"C","text":"8 mètres","isCorrect":false},{"id":"D","text":"10 mètres","isCorrect":false}]'::jsonb, 'A', 'Avec une largeur de voie usuelle d''environ 3,50 m, une chaussée à 2 voies (une par sens) totalise généralement une largeur de l''ordre de 7 m (valeur de référence à adapter selon la norme/le référentiel routier retenu localement).', 28);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q29', 'concours-sujet-1', 'Les dos d''âne (ralentisseurs) permettent de', '[{"id":"A","text":"Ralentir les véhicules (dispositif de modération de la vitesse)","isCorrect":true},{"id":"B","text":"Stopper complètement la circulation des véhicules","isCorrect":false},{"id":"C","text":"Protéger uniquement la chaussée de l''usure","isCorrect":false},{"id":"D","text":"Augmenter le nombre de véhicules pouvant circuler","isCorrect":false}]'::jsonb, 'A', 'Un dos d''âne est un dispositif de sécurité routière conçu pour contraindre les conducteurs à réduire leur vitesse, notamment en zone sensible (écoles, agglomérations).', 29);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s1-q30', 'concours-sujet-1', 'Un béton subit un retrait de 2%. Qu''appelle-t-on retrait ?', '[{"id":"A","text":"La diminution de la résistance du béton","isCorrect":false},{"id":"B","text":"L''augmentation du volume du béton","isCorrect":false},{"id":"C","text":"La diminution du volume du béton suite à l''évaporation de l''eau (et aux réactions internes)","isCorrect":true},{"id":"D","text":"Le gonflement du béton en présence d''humidité","isCorrect":false}]'::jsonb, 'C', 'Le retrait est une contraction (diminution de volume/longueur) du béton, principalement liée au départ d''eau (séchage) et aux réactions d''hydratation, distincte d''une perte de résistance.', 30);
insert into public.qcm_subjects (id, title, description, "order") values ('concours-sujet-2', 'Sujet 2 — Concours d''entrée BTP', '30 questions', 3);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q1', 'concours-sujet-2', 'Dans la relation f_bu = 0,85.f_c28 / (θ.γb), avec une durée d''application de la combinaison d''action considérée t = 40 min,', '[{"id":"A","text":"θ = 1,15","isCorrect":false},{"id":"B","text":"θ = 0,9","isCorrect":false},{"id":"C","text":"θ = 1","isCorrect":false},{"id":"D","text":"θ = 0,85","isCorrect":true}]'::jsonb, 'D', 'BAEL91 (A.4.3,41) : θ=1 si t>24h ; θ=0,9 si 1h<t≤24h ; θ=0,85 si t<1h. Ici t=40 min, donc θ=0,85.', 1);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q2', 'concours-sujet-2', 'Le coefficient de fissuration η pour une armature Haute Adhérence de diamètre φ=10mm est', '[{"id":"A","text":"η = 1,6","isCorrect":true},{"id":"B","text":"η = 1,3","isCorrect":false},{"id":"C","text":"η = 1","isCorrect":false},{"id":"D","text":"η = 2","isCorrect":false}]'::jsonb, 'A', 'BAEL91 (A.4.5,3) : η=1 pour les ronds lisses (RL) ; η=1,6 pour les armatures Haute Adhérence (HA).', 2);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q3', 'concours-sujet-2', 'Le retrait du béton Δl/l en climat humide vaut, à défaut de mesures (BAEL91) :', '[{"id":"A","text":"4 × 10⁻⁴","isCorrect":false},{"id":"B","text":"1,5 × 10⁻⁴","isCorrect":false},{"id":"C","text":"2 × 10⁻⁴","isCorrect":true},{"id":"D","text":"3 × 10⁻⁴","isCorrect":false}]'::jsonb, 'C', 'BAEL91 : retrait forfaitaire = 1,5×10⁻⁴ (très humide), 2×10⁻⁴ (humide), 3×10⁻⁴ (tempéré sec), 4×10⁻⁴ (chaud et sec), 5×10⁻⁴ (très sec/désertique). Climat humide → 2×10⁻⁴.', 3);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q4', 'concours-sujet-2', 'Le raccourcissement de la fibre de béton la plus comprimée εbc=3,5×10⁻³ se trouve', '[{"id":"A","text":"Pivot A","isCorrect":false},{"id":"B","text":"Aucune","isCorrect":false},{"id":"C","text":"Pivot B","isCorrect":true},{"id":"D","text":"Pivot C","isCorrect":false}]'::jsonb, 'C', 'BAEL91 (A.4.3,3), règle des 3 pivots : Pivot A → allongement acier 10‰ ; Pivot B → raccourcissement béton 3,5‰ ; Pivot C → section entièrement comprimée. Le raccourcissement unitaire de la fibre de béton la plus comprimée atteint 3,5 pour mille (3,5×10⁻³).', 4);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q5', 'concours-sujet-2', 'En fissuration préjudiciable, la contrainte limite de traction des aciers est :', '[{"id":"A","text":"σs = fe/γs sans autre condition","isCorrect":false},{"id":"B","text":"σs ≤ min[0,5fe ; 90√(η.ftj)]","isCorrect":false},{"id":"C","text":"σs ≤ min{(2/3)fe ; max[0,5fe ; 110√(η.ftj)]}","isCorrect":true},{"id":"D","text":"σs ≤ 0,6fe","isCorrect":false}]'::jsonb, 'C', 'BAEL91 (A.4.5,3) : peu préjudiciable → pas de limite spécifique (σs=fe/γs) ; préjudiciable → min{2/3fe ; max[0,5fe;110√(η.ftj)]} ; très préjudiciable → min[0,5fe ; 90√(η.ftj)].', 5);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q6', 'concours-sujet-2', 'À l''ELU, la contrainte de dimensionnement (calcul) de l''acier est', '[{"id":"A","text":"σs = 0,6.fc28","isCorrect":false},{"id":"B","text":"σs = 0,8.fe","isCorrect":false},{"id":"C","text":"σs = fe/γs","isCorrect":true},{"id":"D","text":"σs = 0,85.fc28/(θ.γb)","isCorrect":false}]'::jsonb, 'C', 'À l''ELU, dans le domaine des pivots A et B (palier plastique), la contrainte de calcul de l''acier vaut fe/γs (γs=1,15 en combinaison fondamentale).', 6);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q7', 'concours-sujet-2', 'Dans la relation f_t28 = 0,6 + 0,06.f_c28, l''unité considérée est le', '[{"id":"A","text":"MPa","isCorrect":true},{"id":"B","text":"Pa","isCorrect":false},{"id":"C","text":"bar","isCorrect":false},{"id":"D","text":"N/mm","isCorrect":false}]'::jsonb, 'A', 'La résistance caractéristique à la traction f_t28, comme f_c28, est exprimée en MPa dans le BAEL91.', 7);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q8', 'concours-sujet-2', 'Le coefficient γb pour les combinaisons accidentelles vaut', '[{"id":"A","text":"1","isCorrect":false},{"id":"B","text":"1,5","isCorrect":false},{"id":"C","text":"1,35","isCorrect":false},{"id":"D","text":"1,15","isCorrect":true}]'::jsonb, 'D', 'BAEL91 : γb = 1,5 pour les combinaisons fondamentales, γb = 1,15 pour les combinaisons accidentelles.', 8);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q9', 'concours-sujet-2', 'Un béton a une résistance en compression f_c28 = 22 MPa. Quelle est sa résistance en traction f_t28 (formule f_t28 = 0,6+0,06.f_c28) ?', '[{"id":"A","text":"1.92 MPa","isCorrect":true},{"id":"B","text":"1.32 MPa","isCorrect":false},{"id":"C","text":"13.8 MPa","isCorrect":false},{"id":"D","text":"2.42 MPa","isCorrect":false}]'::jsonb, 'A', 'f_t28 = 0,6 + 0,06 × 22 = 1.92 MPa.', 9);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q10', 'concours-sujet-2', 'On applique sur une éprouvette de béton de diamètre d=20 cm un effort de compression de 2000 N. Quelle est la valeur de la contrainte de compression (σ=F/S, S=π.d²/4) ?', '[{"id":"A","text":"63 662 Pa","isCorrect":true},{"id":"B","text":"73 211 Pa","isCorrect":false},{"id":"C","text":"44 563 Pa","isCorrect":false},{"id":"D","text":"55 386 Pa","isCorrect":false}]'::jsonb, 'A', 'S = π × (0,20)²/4 = 0.031416 m². σ = F/S = 2000/0.031416 = 63 662 Pa (arrondi).', 10);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q11', 'concours-sujet-2', 'Soit une poutre isostatique AB, reposant sur des appuis simples en A et B distants de L, supportant une charge concentrée P située à la distance a de l''appui A et b de l''appui B (a+b=L). L''expression de RB est :', '[{"id":"A","text":"R_B = P.a/L","isCorrect":true},{"id":"B","text":"R_B = P.b²/L","isCorrect":false},{"id":"C","text":"R_B = P.b/L","isCorrect":false},{"id":"D","text":"R_B = P(1-b/L)","isCorrect":false}]'::jsonb, 'A', 'Équilibre des moments : ΣM/A=0 → R_B × L = P × a → R_B=P.a/L. De même R_A=P.b/L (R_A+R_B=P).', 11);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q12', 'concours-sujet-2', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour un appui simple de poutre ?', '[{"id":"A","text":"4","isCorrect":false},{"id":"B","text":"3","isCorrect":false},{"id":"C","text":"1","isCorrect":true},{"id":"D","text":"2","isCorrect":false}]'::jsonb, 'C', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 12);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q13', 'concours-sujet-2', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour une articulation de poutre ?', '[{"id":"A","text":"4","isCorrect":false},{"id":"B","text":"3","isCorrect":false},{"id":"C","text":"2","isCorrect":true},{"id":"D","text":"1","isCorrect":false}]'::jsonb, 'C', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 13);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q14', 'concours-sujet-2', 'Les blocs creux (éléments de remplissage) des planchers à corps creux sont appelés', '[{"id":"A","text":"Poutrelles","isCorrect":false},{"id":"B","text":"Nervures","isCorrect":false},{"id":"C","text":"Hourdis (ou entrevous)","isCorrect":true},{"id":"D","text":"Agglomérés","isCorrect":false}]'::jsonb, 'C', 'Les éléments de remplissage/coffrage perdu d''un plancher à corps creux sont appelés hourdis, ou entrevous.', 14);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q15', 'concours-sujet-2', 'La dalle de béton coulée sur les hourdis d''un plancher à corps creux est appelée', '[{"id":"A","text":"Dalle de compression (ou table de compression)","isCorrect":true},{"id":"B","text":"Radier","isCorrect":false},{"id":"C","text":"Semelle filante","isCorrect":false},{"id":"D","text":"Dallage","isCorrect":false}]'::jsonb, 'A', 'La fine dalle armée (souvent 4 à 5 cm) coulée au-dessus des hourdis/nervures est la dalle (ou table) de compression.', 15);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q16', 'concours-sujet-2', 'La semelle de fondation située sous un mur (fondation continue) est appelée', '[{"id":"A","text":"Semelle sur pieux","isCorrect":false},{"id":"B","text":"Semelle isolée","isCorrect":false},{"id":"C","text":"Radier","isCorrect":false},{"id":"D","text":"Semelle filante","isCorrect":true}]'::jsonb, 'D', 'Une semelle continue sous un mur porteur est une semelle filante, par opposition à une semelle isolée sous un poteau.', 16);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q17', 'concours-sujet-2', 'Une dalle rectangulaire appuyée sur ses quatre côtés, avec lx/ly > 0,4 (lx = plus petite portée), porte suivant', '[{"id":"A","text":"Deux sens","isCorrect":true},{"id":"B","text":"Un sens","isCorrect":false},{"id":"C","text":"Aucun sens (dalle non porteuse)","isCorrect":false},{"id":"D","text":"Quatre sens","isCorrect":false}]'::jsonb, 'A', 'Règle courante (BAEL/annexe E) : si lx/ly > 0,4, la dalle porte dans les deux sens (flexion bidirectionnelle) ; en dessous, on la calcule comme portant dans un seul sens.', 17);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q18', 'concours-sujet-2', 'Une dalle située au niveau d''un étage (et non au rez-de-chaussée sur terre-plein) est appelée', '[{"id":"A","text":"Dallage","isCorrect":false},{"id":"B","text":"Plancher","isCorrect":true},{"id":"C","text":"Dalle sur vide sanitaire","isCorrect":false},{"id":"D","text":"Radier","isCorrect":false}]'::jsonb, 'B', 'Par convention, on réserve le terme « plancher » à une dalle d''étage (porteuse, en élévation), et « dallage »/« dalle sur terre-plein » à une dalle basse posée sur le sol.', 18);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q19', 'concours-sujet-2', 'L''altitude relative d''un point est', '[{"id":"A","text":"La position (en hauteur) du point par rapport à un point de référence fixe, choisi arbitrairement pour le chantier","isCorrect":true},{"id":"B","text":"La position du point par rapport au géoïde","isCorrect":false},{"id":"C","text":"La position du point par rapport au niveau de la mer","isCorrect":false},{"id":"D","text":"Une notion qui n''existe pas en topographie","isCorrect":false}]'::jsonb, 'A', 'Contrairement à l''altitude absolue (repérée au niveau de la mer/géoïde, IGN par exemple), l''altitude relative se mesure par rapport à un repère local arbitraire (souvent une borne ou un point fixe du chantier).', 19);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q20', 'concours-sujet-2', 'La visée avant, en nivellement, est', '[{"id":"A","text":"La visée faite sur le point dont on cherche à déterminer l''altitude (point inconnu)","isCorrect":true},{"id":"B","text":"La visée faite sur le premier point observé","isCorrect":false},{"id":"C","text":"La visée faite sur le point d''altitude connue","isCorrect":false},{"id":"D","text":"La visée faite dans le sens du parcours uniquement","isCorrect":false}]'::jsonb, 'A', 'Par convention : la visée arrière se fait sur un point d''altitude CONNUE (ou de référence), la visée avant sur le point dont on veut DÉTERMINER l''altitude.', 20);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q21', 'concours-sujet-2', 'La visée entre deux points A et B a donné les résultats suivants : visée arrière 1850 mm ; visée avant 2400 mm. Quelle est la valeur de la dénivelée entre les deux points ?', '[{"id":"A","text":"-4250 mm","isCorrect":false},{"id":"B","text":"4250 mm","isCorrect":false},{"id":"C","text":"550 mm","isCorrect":false},{"id":"D","text":"-550 mm","isCorrect":true}]'::jsonb, 'D', 'Dénivelée = Visée arrière − Visée avant = 1850 − 2400 = -550 mm.', 21);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q22', 'concours-sujet-2', 'La mesure directe des distances peut se faire :', '[{"id":"A","text":"À l''aide du cercle optique","isCorrect":false},{"id":"B","text":"À l''aide d''un théodolite","isCorrect":false},{"id":"C","text":"À l''aide d''une mire seule","isCorrect":false},{"id":"D","text":"Au ruban (ou au décamètre/chaîne d''arpenteur)","isCorrect":true}]'::jsonb, 'D', 'Une mesure DIRECTE consiste à appliquer physiquement un instrument gradué (ruban, décamètre) le long de la distance à mesurer. Le théodolite et la mire, eux, servent à des mesures INDIRECTES (angles, nivellement optique).', 22);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q23', 'concours-sujet-2', 'À quoi sert l''armature dans le béton armé ?', '[{"id":"A","text":"Empêcher le béton de rompre au flambement","isCorrect":false},{"id":"B","text":"Reprendre les efforts de traction du béton","isCorrect":true},{"id":"C","text":"Reprendre les efforts de compression du béton","isCorrect":false},{"id":"D","text":"Augmenter la résistance du béton en compression","isCorrect":false}]'::jsonb, 'B', 'Le béton résiste bien en compression mais très mal en traction : l''acier, qui résiste bien en traction, est associé au béton pour reprendre ces efforts (principe fondateur du béton armé).', 23);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q24', 'concours-sujet-2', 'Le système qui sépare la collecte des eaux usées/vannes et celle des eaux pluviales, dans deux réseaux distincts, est appelé', '[{"id":"A","text":"Le système mixte","isCorrect":false},{"id":"B","text":"Le système combiné","isCorrect":false},{"id":"C","text":"Le système unitaire","isCorrect":false},{"id":"D","text":"Le système séparatif","isCorrect":true}]'::jsonb, 'D', 'Le système séparatif utilise 2 réseaux distincts (eaux usées/vannes d''un côté, eaux pluviales de l''autre) ; le système unitaire les collecte ensemble dans un seul réseau.', 24);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q25', 'concours-sujet-2', 'Le traitement des eaux usées permet avant tout de', '[{"id":"A","text":"Polluer volontairement les cultures en aval","isCorrect":false},{"id":"B","text":"N''a aucune utilité réelle","isCorrect":false},{"id":"C","text":"Uniquement embellir le paysage","isCorrect":false},{"id":"D","text":"Protéger l''environnement (et la santé publique) en évitant le rejet de pollution dans le milieu naturel","isCorrect":true}]'::jsonb, 'D', 'Le traitement des eaux usées vise à réduire la charge polluante avant rejet dans le milieu naturel, protégeant ainsi l''environnement et la santé publique.', 25);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q26', 'concours-sujet-2', 'À quoi sert la vibration du béton lors de sa mise en œuvre ?', '[{"id":"A","text":"Augmenter la résistance du béton au feu","isCorrect":false},{"id":"B","text":"Augmenter la résistance mécanique finale du béton au-delà de sa formulation","isCorrect":false},{"id":"C","text":"Accélérer la prise du ciment","isCorrect":false},{"id":"D","text":"Empêcher la ségrégation des granulats et chasser les bulles d''air (nids de cailloux)","isCorrect":true}]'::jsonb, 'D', 'La vibration remplit correctement le coffrage, chasse l''air emprisonné et évite la ségrégation (séparation gravier/mortier), améliorant la compacité réelle du béton en place.', 26);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q27', 'concours-sujet-2', 'À quoi servent les dévers sur une chaussée ?', '[{"id":"A","text":"Uniquement améliorer l''esthétique de la route","isCorrect":false},{"id":"B","text":"Augmenter la vitesse autorisée des véhicules","isCorrect":false},{"id":"C","text":"Réduire la largeur utile de la chaussée","isCorrect":false},{"id":"D","text":"Faciliter l''évacuation des eaux de ruissellement (et améliorer la tenue des véhicules en courbe)","isCorrect":true}]'::jsonb, 'D', 'Le dévers (pente transversale) évacue l''eau de pluie vers les côtés de la chaussée et, en courbe, contribue à compenser la force centrifuge subie par les véhicules.', 27);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q28', 'concours-sujet-2', 'Une largeur de voie de circulation courante retenue en dimensionnement routier est de l''ordre de 3,50 m ; pour une route à deux voies, cela correspond à une largeur de chaussée de l''ordre de', '[{"id":"A","text":"7 mètres","isCorrect":true},{"id":"B","text":"6,5 mètres","isCorrect":false},{"id":"C","text":"8 mètres","isCorrect":false},{"id":"D","text":"10 mètres","isCorrect":false}]'::jsonb, 'A', 'Avec une largeur de voie usuelle d''environ 3,50 m, une chaussée à 2 voies (une par sens) totalise généralement une largeur de l''ordre de 7 m (valeur de référence à adapter selon la norme/le référentiel routier retenu localement).', 28);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q29', 'concours-sujet-2', 'Les dos d''âne (ralentisseurs) permettent de', '[{"id":"A","text":"Ralentir les véhicules (dispositif de modération de la vitesse)","isCorrect":true},{"id":"B","text":"Stopper complètement la circulation des véhicules","isCorrect":false},{"id":"C","text":"Protéger uniquement la chaussée de l''usure","isCorrect":false},{"id":"D","text":"Augmenter le nombre de véhicules pouvant circuler","isCorrect":false}]'::jsonb, 'A', 'Un dos d''âne est un dispositif de sécurité routière conçu pour contraindre les conducteurs à réduire leur vitesse, notamment en zone sensible (écoles, agglomérations).', 29);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s2-q30', 'concours-sujet-2', 'Un béton subit un retrait de 2%. Qu''appelle-t-on retrait ?', '[{"id":"A","text":"La diminution de la résistance du béton","isCorrect":false},{"id":"B","text":"L''augmentation du volume du béton","isCorrect":false},{"id":"C","text":"La diminution du volume du béton suite à l''évaporation de l''eau (et aux réactions internes)","isCorrect":true},{"id":"D","text":"Le gonflement du béton en présence d''humidité","isCorrect":false}]'::jsonb, 'C', 'Le retrait est une contraction (diminution de volume/longueur) du béton, principalement liée au départ d''eau (séchage) et aux réactions d''hydratation, distincte d''une perte de résistance.', 30);
insert into public.qcm_subjects (id, title, description, "order") values ('concours-sujet-3', 'Sujet 3 — Concours d''entrée BTP', '30 questions', 4);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q1', 'concours-sujet-3', 'Dans la relation f_bu = 0,85.f_c28 / (θ.γb), avec une durée d''application de la combinaison d''action considérée t = 50 min,', '[{"id":"A","text":"θ = 0,85","isCorrect":false},{"id":"B","text":"θ = 1","isCorrect":false},{"id":"C","text":"θ = 0,9","isCorrect":true},{"id":"D","text":"θ = 1,15","isCorrect":false}]'::jsonb, 'C', 'BAEL91 (A.4.3,41) : θ=1 si t>24h ; θ=0,9 si 1h<t≤24h ; θ=0,85 si t<1h. Ici t=50 min, donc θ=0,9.', 1);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q2', 'concours-sujet-3', 'Le coefficient de fissuration η pour une armature Haute Adhérence de diamètre φ=14mm est', '[{"id":"A","text":"η = 1,3","isCorrect":false},{"id":"B","text":"η = 1,6","isCorrect":true},{"id":"C","text":"η = 1","isCorrect":false},{"id":"D","text":"η = 2","isCorrect":false}]'::jsonb, 'B', 'BAEL91 (A.4.5,3) : η=1 pour les ronds lisses (RL) ; η=1,6 pour les armatures Haute Adhérence (HA).', 2);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q3', 'concours-sujet-3', 'Le retrait du béton Δl/l en climat tempéré sec vaut, à défaut de mesures (BAEL91) :', '[{"id":"A","text":"2 × 10⁻⁴","isCorrect":false},{"id":"B","text":"4 × 10⁻⁴","isCorrect":false},{"id":"C","text":"3 × 10⁻⁴","isCorrect":true},{"id":"D","text":"1,5 × 10⁻⁴","isCorrect":false}]'::jsonb, 'C', 'BAEL91 : retrait forfaitaire = 1,5×10⁻⁴ (très humide), 2×10⁻⁴ (humide), 3×10⁻⁴ (tempéré sec), 4×10⁻⁴ (chaud et sec), 5×10⁻⁴ (très sec/désertique).', 3);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q4', 'concours-sujet-3', 'La section entièrement comprimée (compression simple ou composée, faible excentricité) correspond au', '[{"id":"A","text":"Aucune","isCorrect":false},{"id":"B","text":"Pivot C","isCorrect":true},{"id":"C","text":"Pivot A","isCorrect":false},{"id":"D","text":"Pivot B","isCorrect":false}]'::jsonb, 'B', 'BAEL91 (A.4.3,3), règle des 3 pivots : Pivot A → allongement acier 10‰ ; Pivot B → raccourcissement béton 3,5‰ ; Pivot C → section entièrement comprimée.', 4);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q5', 'concours-sujet-3', 'En fissuration très préjudiciable, la contrainte limite de traction des aciers est :', '[{"id":"A","text":"σs ≤ min{(2/3)fe ; max[0,5fe;110√(η.ftj)]}","isCorrect":false},{"id":"B","text":"σs = fe/γs sans autre condition","isCorrect":false},{"id":"C","text":"σs ≤ 0,8fe","isCorrect":false},{"id":"D","text":"σs ≤ min[0,5fe ; 90√(η.ftj)]","isCorrect":true}]'::jsonb, 'D', 'BAEL91 (A.4.5,3) : peu préjudiciable → pas de limite spécifique (σs=fe/γs) ; préjudiciable → min{2/3fe ; max[0,5fe;110√(η.ftj)]} ; très préjudiciable → min[0,5fe ; 90√(η.ftj)].', 5);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q6', 'concours-sujet-3', 'À l''ELU, la contrainte de dimensionnement (calcul) de l''acier est', '[{"id":"A","text":"σs = 0,8.fe","isCorrect":false},{"id":"B","text":"σs = fe/γs","isCorrect":true},{"id":"C","text":"σs = 0,85.fc28/(θ.γb)","isCorrect":false},{"id":"D","text":"σs = 0,6.fc28","isCorrect":false}]'::jsonb, 'B', 'À l''ELU, dans le domaine des pivots A et B (palier plastique), la contrainte de calcul de l''acier vaut fe/γs (γs=1,15 en combinaison fondamentale).', 6);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q7', 'concours-sujet-3', 'Dans la relation f_bu = 0,85.f_c28/(θ.γb), l''unité considérée pour f_bu est le', '[{"id":"A","text":"bar","isCorrect":false},{"id":"B","text":"MPa (mégapascal)","isCorrect":true},{"id":"C","text":"kg/cm²","isCorrect":false},{"id":"D","text":"Pa (pascal)","isCorrect":false}]'::jsonb, 'B', 'f_bu (contrainte de calcul du béton à l''ELU) et f_c28 s''expriment en MPa dans les formules du BAEL91.', 7);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q8', 'concours-sujet-3', 'Le coefficient γb pour les combinaisons fondamentales vaut', '[{"id":"A","text":"1,5","isCorrect":true},{"id":"B","text":"1,15","isCorrect":false},{"id":"C","text":"1,35","isCorrect":false},{"id":"D","text":"1","isCorrect":false}]'::jsonb, 'A', 'BAEL91 : γb = 1,5 pour les combinaisons fondamentales, γb = 1,15 pour les combinaisons accidentelles.', 8);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q9', 'concours-sujet-3', 'Un béton a une résistance en compression f_c28 = 25 MPa. Quelle est sa résistance en traction f_t28 (formule f_t28 = 0,6+0,06.f_c28) ?', '[{"id":"A","text":"15.6 MPa","isCorrect":false},{"id":"B","text":"2.1 MPa","isCorrect":true},{"id":"C","text":"2.6 MPa","isCorrect":false},{"id":"D","text":"1.5 MPa","isCorrect":false}]'::jsonb, 'B', 'f_t28 = 0,6 + 0,06 × 25 = 2.1 MPa.', 9);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q10', 'concours-sujet-3', 'On applique sur une éprouvette de béton de diamètre d=11 cm un effort de compression de 1200 N. Quelle est la valeur de la contrainte de compression (σ=F/S, S=π.d²/4) ?', '[{"id":"A","text":"109 856 Pa","isCorrect":false},{"id":"B","text":"126 272 Pa","isCorrect":true},{"id":"C","text":"88 390 Pa","isCorrect":false},{"id":"D","text":"145 212 Pa","isCorrect":false}]'::jsonb, 'B', 'S = π × (0,11)²/4 = 0.009503 m². σ = F/S = 1200/0.009503 = 126 272 Pa (arrondi).', 10);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q11', 'concours-sujet-3', 'Soit une poutre isostatique AB, reposant sur des appuis simples en A et B distants de L, supportant une charge concentrée P située à la distance a de l''appui A et b de l''appui B (a+b=L). L''expression de RA est :', '[{"id":"A","text":"R_A = P.a²/L","isCorrect":false},{"id":"B","text":"R_A = P(1-a/L)","isCorrect":false},{"id":"C","text":"R_A = P.b/L","isCorrect":true},{"id":"D","text":"R_A = P.a/L","isCorrect":false}]'::jsonb, 'C', 'Équilibre des moments : ΣM/B=0 → R_A × L = P × b → R_A=P.b/L. De même R_B=P.a/L (R_A+R_B=P).', 11);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q12', 'concours-sujet-3', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour un appui simple de poutre ?', '[{"id":"A","text":"3","isCorrect":false},{"id":"B","text":"4","isCorrect":false},{"id":"C","text":"1","isCorrect":true},{"id":"D","text":"2","isCorrect":false}]'::jsonb, 'C', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 12);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q13', 'concours-sujet-3', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour une articulation de poutre ?', '[{"id":"A","text":"1","isCorrect":false},{"id":"B","text":"2","isCorrect":true},{"id":"C","text":"4","isCorrect":false},{"id":"D","text":"3","isCorrect":false}]'::jsonb, 'B', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 13);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q14', 'concours-sujet-3', 'Les blocs creux (éléments de remplissage) des planchers à corps creux sont appelés', '[{"id":"A","text":"Nervures","isCorrect":false},{"id":"B","text":"Poutrelles","isCorrect":false},{"id":"C","text":"Agglomérés","isCorrect":false},{"id":"D","text":"Hourdis (ou entrevous)","isCorrect":true}]'::jsonb, 'D', 'Les éléments de remplissage/coffrage perdu d''un plancher à corps creux sont appelés hourdis, ou entrevous.', 14);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q15', 'concours-sujet-3', 'La dalle de béton coulée sur les hourdis d''un plancher à corps creux est appelée', '[{"id":"A","text":"Semelle filante","isCorrect":false},{"id":"B","text":"Dallage","isCorrect":false},{"id":"C","text":"Dalle de compression (ou table de compression)","isCorrect":true},{"id":"D","text":"Radier","isCorrect":false}]'::jsonb, 'C', 'La fine dalle armée (souvent 4 à 5 cm) coulée au-dessus des hourdis/nervures est la dalle (ou table) de compression.', 15);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q16', 'concours-sujet-3', 'La semelle de fondation située sous un mur (fondation continue) est appelée', '[{"id":"A","text":"Semelle filante","isCorrect":true},{"id":"B","text":"Semelle isolée","isCorrect":false},{"id":"C","text":"Semelle sur pieux","isCorrect":false},{"id":"D","text":"Radier","isCorrect":false}]'::jsonb, 'A', 'Une semelle continue sous un mur porteur est une semelle filante, par opposition à une semelle isolée sous un poteau.', 16);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q17', 'concours-sujet-3', 'Une dalle rectangulaire appuyée sur ses quatre côtés, avec lx/ly > 0,4 (lx = plus petite portée), porte suivant', '[{"id":"A","text":"Un sens","isCorrect":false},{"id":"B","text":"Aucun sens (dalle non porteuse)","isCorrect":false},{"id":"C","text":"Deux sens","isCorrect":true},{"id":"D","text":"Quatre sens","isCorrect":false}]'::jsonb, 'C', 'Règle courante (BAEL/annexe E) : si lx/ly > 0,4, la dalle porte dans les deux sens (flexion bidirectionnelle) ; en dessous, on la calcule comme portant dans un seul sens.', 17);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q18', 'concours-sujet-3', 'Une dalle située au niveau d''un étage (et non au rez-de-chaussée sur terre-plein) est appelée', '[{"id":"A","text":"Dalle sur vide sanitaire","isCorrect":false},{"id":"B","text":"Radier","isCorrect":false},{"id":"C","text":"Dallage","isCorrect":false},{"id":"D","text":"Plancher","isCorrect":true}]'::jsonb, 'D', 'Par convention, on réserve le terme « plancher » à une dalle d''étage (porteuse, en élévation), et « dallage »/« dalle sur terre-plein » à une dalle basse posée sur le sol.', 18);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q19', 'concours-sujet-3', 'L''altitude relative d''un point est', '[{"id":"A","text":"La position du point par rapport au niveau de la mer","isCorrect":false},{"id":"B","text":"La position (en hauteur) du point par rapport à un point de référence fixe, choisi arbitrairement pour le chantier","isCorrect":true},{"id":"C","text":"Une notion qui n''existe pas en topographie","isCorrect":false},{"id":"D","text":"La position du point par rapport au géoïde","isCorrect":false}]'::jsonb, 'B', 'Contrairement à l''altitude absolue (repérée au niveau de la mer/géoïde, IGN par exemple), l''altitude relative se mesure par rapport à un repère local arbitraire (souvent une borne ou un point fixe du chantier).', 19);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q20', 'concours-sujet-3', 'La visée avant, en nivellement, est', '[{"id":"A","text":"La visée faite sur le point d''altitude connue","isCorrect":false},{"id":"B","text":"La visée faite sur le point dont on cherche à déterminer l''altitude (point inconnu)","isCorrect":true},{"id":"C","text":"La visée faite sur le premier point observé","isCorrect":false},{"id":"D","text":"La visée faite dans le sens du parcours uniquement","isCorrect":false}]'::jsonb, 'B', 'Par convention : la visée arrière se fait sur un point d''altitude CONNUE (ou de référence), la visée avant sur le point dont on veut DÉTERMINER l''altitude.', 20);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q21', 'concours-sujet-3', 'La visée entre deux points A et B a donné les résultats suivants : visée arrière 3120 mm ; visée avant 2900 mm. Quelle est la valeur de la dénivelée entre les deux points ?', '[{"id":"A","text":"220 mm","isCorrect":true},{"id":"B","text":"-220 mm","isCorrect":false},{"id":"C","text":"6020 mm","isCorrect":false},{"id":"D","text":"-6020 mm","isCorrect":false}]'::jsonb, 'A', 'Dénivelée = Visée arrière − Visée avant = 3120 − 2900 = 220 mm.', 21);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q22', 'concours-sujet-3', 'La mesure directe des distances peut se faire :', '[{"id":"A","text":"À l''aide du cercle optique","isCorrect":false},{"id":"B","text":"À l''aide d''une mire seule","isCorrect":false},{"id":"C","text":"À l''aide d''un théodolite","isCorrect":false},{"id":"D","text":"Au ruban (ou au décamètre/chaîne d''arpenteur)","isCorrect":true}]'::jsonb, 'D', 'Une mesure DIRECTE consiste à appliquer physiquement un instrument gradué (ruban, décamètre) le long de la distance à mesurer. Le théodolite et la mire, eux, servent à des mesures INDIRECTES (angles, nivellement optique).', 22);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q23', 'concours-sujet-3', 'À quoi sert l''armature dans le béton armé ?', '[{"id":"A","text":"Augmenter la résistance du béton en compression","isCorrect":false},{"id":"B","text":"Reprendre les efforts de traction du béton","isCorrect":true},{"id":"C","text":"Empêcher le béton de rompre au flambement","isCorrect":false},{"id":"D","text":"Reprendre les efforts de compression du béton","isCorrect":false}]'::jsonb, 'B', 'Le béton résiste bien en compression mais très mal en traction : l''acier, qui résiste bien en traction, est associé au béton pour reprendre ces efforts (principe fondateur du béton armé).', 23);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q24', 'concours-sujet-3', 'Le système qui sépare la collecte des eaux usées/vannes et celle des eaux pluviales, dans deux réseaux distincts, est appelé', '[{"id":"A","text":"Le système mixte","isCorrect":false},{"id":"B","text":"Le système unitaire","isCorrect":false},{"id":"C","text":"Le système séparatif","isCorrect":true},{"id":"D","text":"Le système combiné","isCorrect":false}]'::jsonb, 'C', 'Le système séparatif utilise 2 réseaux distincts (eaux usées/vannes d''un côté, eaux pluviales de l''autre) ; le système unitaire les collecte ensemble dans un seul réseau.', 24);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q25', 'concours-sujet-3', 'Le traitement des eaux usées permet avant tout de', '[{"id":"A","text":"Uniquement embellir le paysage","isCorrect":false},{"id":"B","text":"Polluer volontairement les cultures en aval","isCorrect":false},{"id":"C","text":"Protéger l''environnement (et la santé publique) en évitant le rejet de pollution dans le milieu naturel","isCorrect":true},{"id":"D","text":"N''a aucune utilité réelle","isCorrect":false}]'::jsonb, 'C', 'Le traitement des eaux usées vise à réduire la charge polluante avant rejet dans le milieu naturel, protégeant ainsi l''environnement et la santé publique.', 25);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q26', 'concours-sujet-3', 'À quoi sert la vibration du béton lors de sa mise en œuvre ?', '[{"id":"A","text":"Augmenter la résistance du béton au feu","isCorrect":false},{"id":"B","text":"Empêcher la ségrégation des granulats et chasser les bulles d''air (nids de cailloux)","isCorrect":true},{"id":"C","text":"Accélérer la prise du ciment","isCorrect":false},{"id":"D","text":"Augmenter la résistance mécanique finale du béton au-delà de sa formulation","isCorrect":false}]'::jsonb, 'B', 'La vibration remplit correctement le coffrage, chasse l''air emprisonné et évite la ségrégation (séparation gravier/mortier), améliorant la compacité réelle du béton en place.', 26);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q27', 'concours-sujet-3', 'À quoi servent les dévers sur une chaussée ?', '[{"id":"A","text":"Réduire la largeur utile de la chaussée","isCorrect":false},{"id":"B","text":"Uniquement améliorer l''esthétique de la route","isCorrect":false},{"id":"C","text":"Faciliter l''évacuation des eaux de ruissellement (et améliorer la tenue des véhicules en courbe)","isCorrect":true},{"id":"D","text":"Augmenter la vitesse autorisée des véhicules","isCorrect":false}]'::jsonb, 'C', 'Le dévers (pente transversale) évacue l''eau de pluie vers les côtés de la chaussée et, en courbe, contribue à compenser la force centrifuge subie par les véhicules.', 27);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q28', 'concours-sujet-3', 'Une largeur de voie de circulation courante retenue en dimensionnement routier est de l''ordre de 3,50 m ; pour une route à deux voies, cela correspond à une largeur de chaussée de l''ordre de', '[{"id":"A","text":"8 mètres","isCorrect":false},{"id":"B","text":"10 mètres","isCorrect":false},{"id":"C","text":"6,5 mètres","isCorrect":false},{"id":"D","text":"7 mètres","isCorrect":true}]'::jsonb, 'D', 'Avec une largeur de voie usuelle d''environ 3,50 m, une chaussée à 2 voies (une par sens) totalise généralement une largeur de l''ordre de 7 m (valeur de référence à adapter selon la norme/le référentiel routier retenu localement).', 28);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q29', 'concours-sujet-3', 'Les dos d''âne (ralentisseurs) permettent de', '[{"id":"A","text":"Ralentir les véhicules (dispositif de modération de la vitesse)","isCorrect":true},{"id":"B","text":"Protéger uniquement la chaussée de l''usure","isCorrect":false},{"id":"C","text":"Augmenter le nombre de véhicules pouvant circuler","isCorrect":false},{"id":"D","text":"Stopper complètement la circulation des véhicules","isCorrect":false}]'::jsonb, 'A', 'Un dos d''âne est un dispositif de sécurité routière conçu pour contraindre les conducteurs à réduire leur vitesse, notamment en zone sensible (écoles, agglomérations).', 29);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s3-q30', 'concours-sujet-3', 'Un béton subit un retrait de 2%. Qu''appelle-t-on retrait ?', '[{"id":"A","text":"La diminution de la résistance du béton","isCorrect":false},{"id":"B","text":"Le gonflement du béton en présence d''humidité","isCorrect":false},{"id":"C","text":"La diminution du volume du béton suite à l''évaporation de l''eau (et aux réactions internes)","isCorrect":true},{"id":"D","text":"L''augmentation du volume du béton","isCorrect":false}]'::jsonb, 'C', 'Le retrait est une contraction (diminution de volume/longueur) du béton, principalement liée au départ d''eau (séchage) et aux réactions d''hydratation, distincte d''une perte de résistance.', 30);
insert into public.qcm_subjects (id, title, description, "order") values ('concours-sujet-4', 'Sujet 4 — Concours d''entrée BTP', '30 questions', 5);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q1', 'concours-sujet-4', 'Dans la relation f_bu = 0,85.f_c28 / (θ.γb), avec une durée d''application de la combinaison d''action considérée t = 2 h,', '[{"id":"A","text":"θ = 0,85","isCorrect":false},{"id":"B","text":"θ = 1","isCorrect":true},{"id":"C","text":"θ = 1,15","isCorrect":false},{"id":"D","text":"θ = 0,9","isCorrect":false}]'::jsonb, 'B', 'BAEL91 (A.4.3,41) : θ=1 si t>24h ; θ=0,9 si 1h<t≤24h ; θ=0,85 si t<1h. Ici t=2h, donc θ=0,9.', 1);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q2', 'concours-sujet-4', 'Le coefficient de fissuration η pour une armature Haute Adhérence de diamètre φ=16mm est', '[{"id":"A","text":"η = 1,3","isCorrect":false},{"id":"B","text":"η = 1,6","isCorrect":true},{"id":"C","text":"η = 2","isCorrect":false},{"id":"D","text":"η = 1","isCorrect":false}]'::jsonb, 'B', 'BAEL91 (A.4.5,3) : η=1 pour les ronds lisses (RL) ; η=1,6 pour les armatures Haute Adhérence (HA).', 2);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q3', 'concours-sujet-4', 'Le retrait du béton Δl/l en climat chaud et sec vaut, à défaut de mesures (BAEL91) :', '[{"id":"A","text":"2 × 10⁻⁴","isCorrect":false},{"id":"B","text":"3 × 10⁻⁴","isCorrect":false},{"id":"C","text":"4 × 10⁻⁴","isCorrect":true},{"id":"D","text":"1,5 × 10⁻⁴","isCorrect":false}]'::jsonb, 'C', 'BAEL91 : retrait forfaitaire = 1,5×10⁻⁴ (très humide), 2×10⁻⁴ (humide), 3×10⁻⁴ (tempéré sec), 4×10⁻⁴ (chaud et sec), 5×10⁻⁴ (très sec/désertique).', 3);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q4', 'concours-sujet-4', 'L''allongement de l''armature la plus tendue εs=10×10⁻³ (pivot correspondant) se trouve', '[{"id":"A","text":"Pivot C","isCorrect":false},{"id":"B","text":"Pivot A","isCorrect":true},{"id":"C","text":"Aucune","isCorrect":false},{"id":"D","text":"Pivot B","isCorrect":false}]'::jsonb, 'B', 'BAEL91 (A.4.3,3), règle des 3 pivots : Pivot A → allongement acier 10‰ ; Pivot B → raccourcissement béton 3,5‰ ; Pivot C → section entièrement comprimée.', 4);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q5', 'concours-sujet-4', 'En fissuration peu préjudiciable, la contrainte limite de traction des aciers est :', '[{"id":"A","text":"σs = fe/γs (aucune limitation supplémentaire liée à la fissuration)","isCorrect":true},{"id":"B","text":"σs ≤ min(0,5fe ; 90√(η.ftj))","isCorrect":false},{"id":"C","text":"σs ≤ (2/3)fe","isCorrect":false},{"id":"D","text":"σs ≤ min(0,5fe ; 110√(η.ftj))","isCorrect":false}]'::jsonb, 'A', 'BAEL91 (A.4.5,3) : peu préjudiciable → pas de limite spécifique (σs=fe/γs) ; préjudiciable → min{2/3fe ; max[0,5fe;110√(η.ftj)]} ; très préjudiciable → min[0,5fe ; 90√(η.ftj)].', 5);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q6', 'concours-sujet-4', 'À l''ELU, la contrainte de dimensionnement (calcul) de l''acier est', '[{"id":"A","text":"σs = 0,85.fc28/(θ.γb)","isCorrect":false},{"id":"B","text":"σs = 0,8.fe","isCorrect":false},{"id":"C","text":"σs = fe/γs","isCorrect":true},{"id":"D","text":"σs = 0,6.fc28","isCorrect":false}]'::jsonb, 'C', 'À l''ELU, dans le domaine des pivots A et B (palier plastique), la contrainte de calcul de l''acier vaut fe/γs (γs=1,15 en combinaison fondamentale).', 6);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q7', 'concours-sujet-4', 'Dans la relation f_t28 = 0,6 + 0,06.f_c28, l''unité considérée est le', '[{"id":"A","text":"MPa","isCorrect":true},{"id":"B","text":"bar","isCorrect":false},{"id":"C","text":"Pa","isCorrect":false},{"id":"D","text":"N/mm","isCorrect":false}]'::jsonb, 'A', 'La résistance caractéristique à la traction f_t28, comme f_c28, est exprimée en MPa dans le BAEL91.', 7);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q8', 'concours-sujet-4', 'Le coefficient γb pour les combinaisons accidentelles vaut', '[{"id":"A","text":"1,35","isCorrect":false},{"id":"B","text":"1,15","isCorrect":true},{"id":"C","text":"1","isCorrect":false},{"id":"D","text":"1,5","isCorrect":false}]'::jsonb, 'B', 'BAEL91 : γb = 1,5 pour les combinaisons fondamentales, γb = 1,15 pour les combinaisons accidentelles.', 8);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q9', 'concours-sujet-4', 'Un béton a une résistance en compression f_c28 = 27 MPa. Quelle est sa résistance en traction f_t28 (formule f_t28 = 0,6+0,06.f_c28) ?', '[{"id":"A","text":"16.8 MPa","isCorrect":false},{"id":"B","text":"2.72 MPa","isCorrect":false},{"id":"C","text":"1.62 MPa","isCorrect":false},{"id":"D","text":"2.22 MPa","isCorrect":true}]'::jsonb, 'D', 'f_t28 = 0,6 + 0,06 × 27 = 2.22 MPa.', 9);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q10', 'concours-sujet-4', 'On applique sur une éprouvette de béton de diamètre d=14 cm un effort de compression de 1800 N. Quelle est la valeur de la contrainte de compression (σ=F/S, S=π.d²/4) ?', '[{"id":"A","text":"101 729 Pa","isCorrect":false},{"id":"B","text":"134 470 Pa","isCorrect":false},{"id":"C","text":"81 851 Pa","isCorrect":false},{"id":"D","text":"116 930 Pa","isCorrect":true}]'::jsonb, 'D', 'S = π × (0,14)²/4 = 0.015394 m². σ = F/S = 1800/0.015394 = 116 930 Pa (arrondi).', 10);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q11', 'concours-sujet-4', 'Soit une poutre isostatique AB, reposant sur des appuis simples en A et B distants de L, supportant une charge concentrée P située à la distance a de l''appui A et b de l''appui B (a+b=L). L''expression de RB est :', '[{"id":"A","text":"R_B = P.b²/L","isCorrect":false},{"id":"B","text":"R_B = P.a/L","isCorrect":true},{"id":"C","text":"R_B = P(1-b/L)","isCorrect":false},{"id":"D","text":"R_B = P.b/L","isCorrect":false}]'::jsonb, 'B', 'Équilibre des moments : ΣM/A=0 → R_B × L = P × a → R_B=P.a/L. De même R_A=P.b/L (R_A+R_B=P).', 11);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q12', 'concours-sujet-4', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour un appui simple de poutre ?', '[{"id":"A","text":"4","isCorrect":false},{"id":"B","text":"3","isCorrect":false},{"id":"C","text":"2","isCorrect":false},{"id":"D","text":"1","isCorrect":true}]'::jsonb, 'D', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 12);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q13', 'concours-sujet-4', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour une articulation de poutre ?', '[{"id":"A","text":"1","isCorrect":false},{"id":"B","text":"4","isCorrect":false},{"id":"C","text":"3","isCorrect":false},{"id":"D","text":"2","isCorrect":true}]'::jsonb, 'D', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 13);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q14', 'concours-sujet-4', 'Les blocs creux (éléments de remplissage) des planchers à corps creux sont appelés', '[{"id":"A","text":"Poutrelles","isCorrect":false},{"id":"B","text":"Nervures","isCorrect":false},{"id":"C","text":"Hourdis (ou entrevous)","isCorrect":true},{"id":"D","text":"Agglomérés","isCorrect":false}]'::jsonb, 'C', 'Les éléments de remplissage/coffrage perdu d''un plancher à corps creux sont appelés hourdis, ou entrevous.', 14);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q15', 'concours-sujet-4', 'La dalle de béton coulée sur les hourdis d''un plancher à corps creux est appelée', '[{"id":"A","text":"Radier","isCorrect":false},{"id":"B","text":"Dallage","isCorrect":false},{"id":"C","text":"Semelle filante","isCorrect":false},{"id":"D","text":"Dalle de compression (ou table de compression)","isCorrect":true}]'::jsonb, 'D', 'La fine dalle armée (souvent 4 à 5 cm) coulée au-dessus des hourdis/nervures est la dalle (ou table) de compression.', 15);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q16', 'concours-sujet-4', 'La semelle de fondation située sous un mur (fondation continue) est appelée', '[{"id":"A","text":"Semelle sur pieux","isCorrect":false},{"id":"B","text":"Semelle isolée","isCorrect":false},{"id":"C","text":"Radier","isCorrect":false},{"id":"D","text":"Semelle filante","isCorrect":true}]'::jsonb, 'D', 'Une semelle continue sous un mur porteur est une semelle filante, par opposition à une semelle isolée sous un poteau.', 16);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q17', 'concours-sujet-4', 'Une dalle rectangulaire appuyée sur ses quatre côtés, avec lx/ly > 0,4 (lx = plus petite portée), porte suivant', '[{"id":"A","text":"Un sens","isCorrect":false},{"id":"B","text":"Deux sens","isCorrect":true},{"id":"C","text":"Aucun sens (dalle non porteuse)","isCorrect":false},{"id":"D","text":"Quatre sens","isCorrect":false}]'::jsonb, 'B', 'Règle courante (BAEL/annexe E) : si lx/ly > 0,4, la dalle porte dans les deux sens (flexion bidirectionnelle) ; en dessous, on la calcule comme portant dans un seul sens.', 17);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q18', 'concours-sujet-4', 'Une dalle située au niveau d''un étage (et non au rez-de-chaussée sur terre-plein) est appelée', '[{"id":"A","text":"Plancher","isCorrect":true},{"id":"B","text":"Dallage","isCorrect":false},{"id":"C","text":"Radier","isCorrect":false},{"id":"D","text":"Dalle sur vide sanitaire","isCorrect":false}]'::jsonb, 'A', 'Par convention, on réserve le terme « plancher » à une dalle d''étage (porteuse, en élévation), et « dallage »/« dalle sur terre-plein » à une dalle basse posée sur le sol.', 18);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q19', 'concours-sujet-4', 'L''altitude relative d''un point est', '[{"id":"A","text":"La position (en hauteur) du point par rapport à un point de référence fixe, choisi arbitrairement pour le chantier","isCorrect":true},{"id":"B","text":"Une notion qui n''existe pas en topographie","isCorrect":false},{"id":"C","text":"La position du point par rapport au niveau de la mer","isCorrect":false},{"id":"D","text":"La position du point par rapport au géoïde","isCorrect":false}]'::jsonb, 'A', 'Contrairement à l''altitude absolue (repérée au niveau de la mer/géoïde, IGN par exemple), l''altitude relative se mesure par rapport à un repère local arbitraire (souvent une borne ou un point fixe du chantier).', 19);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q20', 'concours-sujet-4', 'La visée avant, en nivellement, est', '[{"id":"A","text":"La visée faite sur le premier point observé","isCorrect":false},{"id":"B","text":"La visée faite sur le point dont on cherche à déterminer l''altitude (point inconnu)","isCorrect":true},{"id":"C","text":"La visée faite dans le sens du parcours uniquement","isCorrect":false},{"id":"D","text":"La visée faite sur le point d''altitude connue","isCorrect":false}]'::jsonb, 'B', 'Par convention : la visée arrière se fait sur un point d''altitude CONNUE (ou de référence), la visée avant sur le point dont on veut DÉTERMINER l''altitude.', 20);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q21', 'concours-sujet-4', 'La visée entre deux points A et B a donné les résultats suivants : visée arrière 2005 mm ; visée avant 2860 mm. Quelle est la valeur de la dénivelée entre les deux points ?', '[{"id":"A","text":"4865 mm","isCorrect":false},{"id":"B","text":"855 mm","isCorrect":false},{"id":"C","text":"-855 mm","isCorrect":true},{"id":"D","text":"-4865 mm","isCorrect":false}]'::jsonb, 'C', 'Dénivelée = Visée arrière − Visée avant = 2005 − 2860 = -855 mm.', 21);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q22', 'concours-sujet-4', 'La mesure directe des distances peut se faire :', '[{"id":"A","text":"À l''aide d''un théodolite","isCorrect":false},{"id":"B","text":"Au ruban (ou au décamètre/chaîne d''arpenteur)","isCorrect":true},{"id":"C","text":"À l''aide du cercle optique","isCorrect":false},{"id":"D","text":"À l''aide d''une mire seule","isCorrect":false}]'::jsonb, 'B', 'Une mesure DIRECTE consiste à appliquer physiquement un instrument gradué (ruban, décamètre) le long de la distance à mesurer. Le théodolite et la mire, eux, servent à des mesures INDIRECTES (angles, nivellement optique).', 22);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q23', 'concours-sujet-4', 'À quoi sert l''armature dans le béton armé ?', '[{"id":"A","text":"Empêcher le béton de rompre au flambement","isCorrect":false},{"id":"B","text":"Reprendre les efforts de traction du béton","isCorrect":true},{"id":"C","text":"Reprendre les efforts de compression du béton","isCorrect":false},{"id":"D","text":"Augmenter la résistance du béton en compression","isCorrect":false}]'::jsonb, 'B', 'Le béton résiste bien en compression mais très mal en traction : l''acier, qui résiste bien en traction, est associé au béton pour reprendre ces efforts (principe fondateur du béton armé).', 23);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q24', 'concours-sujet-4', 'Le système qui sépare la collecte des eaux usées/vannes et celle des eaux pluviales, dans deux réseaux distincts, est appelé', '[{"id":"A","text":"Le système séparatif","isCorrect":true},{"id":"B","text":"Le système combiné","isCorrect":false},{"id":"C","text":"Le système mixte","isCorrect":false},{"id":"D","text":"Le système unitaire","isCorrect":false}]'::jsonb, 'A', 'Le système séparatif utilise 2 réseaux distincts (eaux usées/vannes d''un côté, eaux pluviales de l''autre) ; le système unitaire les collecte ensemble dans un seul réseau.', 24);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q25', 'concours-sujet-4', 'Le traitement des eaux usées permet avant tout de', '[{"id":"A","text":"N''a aucune utilité réelle","isCorrect":false},{"id":"B","text":"Polluer volontairement les cultures en aval","isCorrect":false},{"id":"C","text":"Uniquement embellir le paysage","isCorrect":false},{"id":"D","text":"Protéger l''environnement (et la santé publique) en évitant le rejet de pollution dans le milieu naturel","isCorrect":true}]'::jsonb, 'D', 'Le traitement des eaux usées vise à réduire la charge polluante avant rejet dans le milieu naturel, protégeant ainsi l''environnement et la santé publique.', 25);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q26', 'concours-sujet-4', 'À quoi sert la vibration du béton lors de sa mise en œuvre ?', '[{"id":"A","text":"Augmenter la résistance du béton au feu","isCorrect":false},{"id":"B","text":"Empêcher la ségrégation des granulats et chasser les bulles d''air (nids de cailloux)","isCorrect":true},{"id":"C","text":"Augmenter la résistance mécanique finale du béton au-delà de sa formulation","isCorrect":false},{"id":"D","text":"Accélérer la prise du ciment","isCorrect":false}]'::jsonb, 'B', 'La vibration remplit correctement le coffrage, chasse l''air emprisonné et évite la ségrégation (séparation gravier/mortier), améliorant la compacité réelle du béton en place.', 26);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q27', 'concours-sujet-4', 'À quoi servent les dévers sur une chaussée ?', '[{"id":"A","text":"Augmenter la vitesse autorisée des véhicules","isCorrect":false},{"id":"B","text":"Uniquement améliorer l''esthétique de la route","isCorrect":false},{"id":"C","text":"Faciliter l''évacuation des eaux de ruissellement (et améliorer la tenue des véhicules en courbe)","isCorrect":true},{"id":"D","text":"Réduire la largeur utile de la chaussée","isCorrect":false}]'::jsonb, 'C', 'Le dévers (pente transversale) évacue l''eau de pluie vers les côtés de la chaussée et, en courbe, contribue à compenser la force centrifuge subie par les véhicules.', 27);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q28', 'concours-sujet-4', 'Une largeur de voie de circulation courante retenue en dimensionnement routier est de l''ordre de 3,50 m ; pour une route à deux voies, cela correspond à une largeur de chaussée de l''ordre de', '[{"id":"A","text":"8 mètres","isCorrect":false},{"id":"B","text":"7 mètres","isCorrect":true},{"id":"C","text":"10 mètres","isCorrect":false},{"id":"D","text":"6,5 mètres","isCorrect":false}]'::jsonb, 'B', 'Avec une largeur de voie usuelle d''environ 3,50 m, une chaussée à 2 voies (une par sens) totalise généralement une largeur de l''ordre de 7 m (valeur de référence à adapter selon la norme/le référentiel routier retenu localement).', 28);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q29', 'concours-sujet-4', 'Les dos d''âne (ralentisseurs) permettent de', '[{"id":"A","text":"Augmenter le nombre de véhicules pouvant circuler","isCorrect":false},{"id":"B","text":"Protéger uniquement la chaussée de l''usure","isCorrect":false},{"id":"C","text":"Ralentir les véhicules (dispositif de modération de la vitesse)","isCorrect":true},{"id":"D","text":"Stopper complètement la circulation des véhicules","isCorrect":false}]'::jsonb, 'C', 'Un dos d''âne est un dispositif de sécurité routière conçu pour contraindre les conducteurs à réduire leur vitesse, notamment en zone sensible (écoles, agglomérations).', 29);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s4-q30', 'concours-sujet-4', 'Un béton subit un retrait de 2%. Qu''appelle-t-on retrait ?', '[{"id":"A","text":"La diminution du volume du béton suite à l''évaporation de l''eau (et aux réactions internes)","isCorrect":true},{"id":"B","text":"L''augmentation du volume du béton","isCorrect":false},{"id":"C","text":"La diminution de la résistance du béton","isCorrect":false},{"id":"D","text":"Le gonflement du béton en présence d''humidité","isCorrect":false}]'::jsonb, 'A', 'Le retrait est une contraction (diminution de volume/longueur) du béton, principalement liée au départ d''eau (séchage) et aux réactions d''hydratation, distincte d''une perte de résistance.', 30);
insert into public.qcm_subjects (id, title, description, "order") values ('concours-sujet-5', 'Sujet 5 — Concours d''entrée BTP', '30 questions', 6);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q1', 'concours-sujet-5', 'Dans la relation f_bu = 0,85.f_c28 / (θ.γb), avec une durée d''application de la combinaison d''action considérée t = 6 h,', '[{"id":"A","text":"θ = 0,9","isCorrect":true},{"id":"B","text":"θ = 1","isCorrect":false},{"id":"C","text":"θ = 1,15","isCorrect":false},{"id":"D","text":"θ = 0,85","isCorrect":false}]'::jsonb, 'A', 'BAEL91 (A.4.3,41) : θ=1 si t>24h ; θ=0,9 si 1h<t≤24h ; θ=0,85 si t<1h. Ici t=6h, donc θ=0,9.', 1);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q2', 'concours-sujet-5', 'Le coefficient de fissuration η pour une armature Haute Adhérence de diamètre φ=8mm est', '[{"id":"A","text":"η = 2","isCorrect":false},{"id":"B","text":"η = 1","isCorrect":false},{"id":"C","text":"η = 1,3","isCorrect":false},{"id":"D","text":"η = 1,6","isCorrect":true}]'::jsonb, 'D', 'BAEL91 (A.4.5,3) : η=1 pour les ronds lisses (RL) ; η=1,6 pour les armatures Haute Adhérence (HA).', 2);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q3', 'concours-sujet-5', 'Le retrait du béton Δl/l en climat très sec ou désertique vaut, à défaut de mesures (BAEL91) :', '[{"id":"A","text":"3 × 10⁻⁴","isCorrect":false},{"id":"B","text":"2 × 10⁻⁴","isCorrect":false},{"id":"C","text":"1,5 × 10⁻⁴","isCorrect":false},{"id":"D","text":"5 × 10⁻⁴","isCorrect":true}]'::jsonb, 'D', 'BAEL91 : retrait forfaitaire = 1,5×10⁻⁴ (très humide), 2×10⁻⁴ (humide), 3×10⁻⁴ (tempéré sec), 4×10⁻⁴ (chaud et sec), 5×10⁻⁴ (très sec/désertique).', 3);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q4', 'concours-sujet-5', 'Le raccourcissement de la fibre de béton la plus comprimée εbc=3,5×10⁻³ se trouve', '[{"id":"A","text":"Pivot A","isCorrect":false},{"id":"B","text":"Pivot B","isCorrect":true},{"id":"C","text":"Pivot C","isCorrect":false},{"id":"D","text":"Aucune","isCorrect":false}]'::jsonb, 'B', 'BAEL91 (A.4.3,3), règle des 3 pivots : Pivot A → allongement acier 10‰ ; Pivot B → raccourcissement béton 3,5‰ ; Pivot C → section entièrement comprimée.', 4);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q5', 'concours-sujet-5', 'En fissuration préjudiciable, la contrainte limite de traction des aciers est :', '[{"id":"A","text":"σs ≤ min{(2/3)fe ; max[0,5fe;110√(η.ftj)]}","isCorrect":true},{"id":"B","text":"σs ≤ min[0,5fe ; 90√(η.ftj)]","isCorrect":false},{"id":"C","text":"σs = fe/γs sans autre condition","isCorrect":false},{"id":"D","text":"σs ≤ 0,6fe","isCorrect":false}]'::jsonb, 'A', 'BAEL91 (A.4.5,3) : peu préjudiciable → pas de limite spécifique (σs=fe/γs) ; préjudiciable → min{2/3fe ; max[0,5fe;110√(η.ftj)]} ; très préjudiciable → min[0,5fe ; 90√(η.ftj)].', 5);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q6', 'concours-sujet-5', 'À l''ELU, la contrainte de dimensionnement (calcul) de l''acier est', '[{"id":"A","text":"σs = 0,6.fc28","isCorrect":false},{"id":"B","text":"σs = 0,85.fc28/(θ.γb)","isCorrect":false},{"id":"C","text":"σs = 0,8.fe","isCorrect":false},{"id":"D","text":"σs = fe/γs","isCorrect":true}]'::jsonb, 'D', 'À l''ELU, dans le domaine des pivots A et B (palier plastique), la contrainte de calcul de l''acier vaut fe/γs (γs=1,15 en combinaison fondamentale).', 6);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q7', 'concours-sujet-5', 'Dans la relation f_bu = 0,85.f_c28/(θ.γb), l''unité considérée pour f_bu est le', '[{"id":"A","text":"Pa (pascal)","isCorrect":false},{"id":"B","text":"bar","isCorrect":false},{"id":"C","text":"kg/cm²","isCorrect":false},{"id":"D","text":"MPa (mégapascal)","isCorrect":true}]'::jsonb, 'D', 'f_bu (contrainte de calcul du béton à l''ELU) et f_c28 s''expriment en MPa dans les formules du BAEL91.', 7);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q8', 'concours-sujet-5', 'Le coefficient γb pour les combinaisons fondamentales vaut', '[{"id":"A","text":"1,15","isCorrect":false},{"id":"B","text":"1,35","isCorrect":false},{"id":"C","text":"1,5","isCorrect":true},{"id":"D","text":"1","isCorrect":false}]'::jsonb, 'C', 'BAEL91 : γb = 1,5 pour les combinaisons fondamentales, γb = 1,15 pour les combinaisons accidentelles.', 8);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q9', 'concours-sujet-5', 'Un béton a une résistance en compression f_c28 = 28 MPa. Quelle est sa résistance en traction f_t28 (formule f_t28 = 0,6+0,06.f_c28) ?', '[{"id":"A","text":"2.78 MPa","isCorrect":false},{"id":"B","text":"1.68 MPa","isCorrect":false},{"id":"C","text":"2.28 MPa","isCorrect":true},{"id":"D","text":"17.4 MPa","isCorrect":false}]'::jsonb, 'C', 'f_t28 = 0,6 + 0,06 × 28 = 2.28 MPa.', 9);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q10', 'concours-sujet-5', 'On applique sur une éprouvette de béton de diamètre d=16 cm un effort de compression de 1800 N. Quelle est la valeur de la contrainte de compression (σ=F/S, S=π.d²/4) ?', '[{"id":"A","text":"62 667 Pa","isCorrect":false},{"id":"B","text":"89 525 Pa","isCorrect":true},{"id":"C","text":"77 886 Pa","isCorrect":false},{"id":"D","text":"102 953 Pa","isCorrect":false}]'::jsonb, 'B', 'S = π × (0,16)²/4 = 0.020106 m². σ = F/S = 1800/0.020106 = 89 525 Pa (arrondi).', 10);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q11', 'concours-sujet-5', 'Soit une poutre isostatique AB, reposant sur des appuis simples en A et B distants de L, supportant une charge concentrée P située à la distance a de l''appui A et b de l''appui B (a+b=L). L''expression de RA est :', '[{"id":"A","text":"R_A = P.b/L","isCorrect":true},{"id":"B","text":"R_A = P.a/L","isCorrect":false},{"id":"C","text":"R_A = P.a²/L","isCorrect":false},{"id":"D","text":"R_A = P(1-a/L)","isCorrect":false}]'::jsonb, 'A', 'Équilibre des moments : ΣM/B=0 → R_A × L = P × b → R_A=P.b/L. De même R_B=P.a/L (R_A+R_B=P).', 11);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q12', 'concours-sujet-5', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour un appui simple de poutre ?', '[{"id":"A","text":"3","isCorrect":false},{"id":"B","text":"4","isCorrect":false},{"id":"C","text":"2","isCorrect":false},{"id":"D","text":"1","isCorrect":true}]'::jsonb, 'D', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 12);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q13', 'concours-sujet-5', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour une articulation de poutre ?', '[{"id":"A","text":"3","isCorrect":false},{"id":"B","text":"2","isCorrect":true},{"id":"C","text":"4","isCorrect":false},{"id":"D","text":"1","isCorrect":false}]'::jsonb, 'B', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 13);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q14', 'concours-sujet-5', 'Les blocs creux (éléments de remplissage) des planchers à corps creux sont appelés', '[{"id":"A","text":"Agglomérés","isCorrect":false},{"id":"B","text":"Nervures","isCorrect":false},{"id":"C","text":"Hourdis (ou entrevous)","isCorrect":true},{"id":"D","text":"Poutrelles","isCorrect":false}]'::jsonb, 'C', 'Les éléments de remplissage/coffrage perdu d''un plancher à corps creux sont appelés hourdis, ou entrevous.', 14);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q15', 'concours-sujet-5', 'La dalle de béton coulée sur les hourdis d''un plancher à corps creux est appelée', '[{"id":"A","text":"Dallage","isCorrect":false},{"id":"B","text":"Semelle filante","isCorrect":false},{"id":"C","text":"Dalle de compression (ou table de compression)","isCorrect":true},{"id":"D","text":"Radier","isCorrect":false}]'::jsonb, 'C', 'La fine dalle armée (souvent 4 à 5 cm) coulée au-dessus des hourdis/nervures est la dalle (ou table) de compression.', 15);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q16', 'concours-sujet-5', 'La semelle de fondation située sous un mur (fondation continue) est appelée', '[{"id":"A","text":"Semelle sur pieux","isCorrect":false},{"id":"B","text":"Radier","isCorrect":false},{"id":"C","text":"Semelle isolée","isCorrect":false},{"id":"D","text":"Semelle filante","isCorrect":true}]'::jsonb, 'D', 'Une semelle continue sous un mur porteur est une semelle filante, par opposition à une semelle isolée sous un poteau.', 16);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q17', 'concours-sujet-5', 'Une dalle rectangulaire appuyée sur ses quatre côtés, avec lx/ly > 0,4 (lx = plus petite portée), porte suivant', '[{"id":"A","text":"Quatre sens","isCorrect":false},{"id":"B","text":"Un sens","isCorrect":false},{"id":"C","text":"Deux sens","isCorrect":true},{"id":"D","text":"Aucun sens (dalle non porteuse)","isCorrect":false}]'::jsonb, 'C', 'Règle courante (BAEL/annexe E) : si lx/ly > 0,4, la dalle porte dans les deux sens (flexion bidirectionnelle) ; en dessous, on la calcule comme portant dans un seul sens.', 17);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q18', 'concours-sujet-5', 'Une dalle située au niveau d''un étage (et non au rez-de-chaussée sur terre-plein) est appelée', '[{"id":"A","text":"Dalle sur vide sanitaire","isCorrect":false},{"id":"B","text":"Plancher","isCorrect":true},{"id":"C","text":"Radier","isCorrect":false},{"id":"D","text":"Dallage","isCorrect":false}]'::jsonb, 'B', 'Par convention, on réserve le terme « plancher » à une dalle d''étage (porteuse, en élévation), et « dallage »/« dalle sur terre-plein » à une dalle basse posée sur le sol.', 18);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q19', 'concours-sujet-5', 'L''altitude relative d''un point est', '[{"id":"A","text":"La position du point par rapport au géoïde","isCorrect":false},{"id":"B","text":"Une notion qui n''existe pas en topographie","isCorrect":false},{"id":"C","text":"La position du point par rapport au niveau de la mer","isCorrect":false},{"id":"D","text":"La position (en hauteur) du point par rapport à un point de référence fixe, choisi arbitrairement pour le chantier","isCorrect":true}]'::jsonb, 'D', 'Contrairement à l''altitude absolue (repérée au niveau de la mer/géoïde, IGN par exemple), l''altitude relative se mesure par rapport à un repère local arbitraire (souvent une borne ou un point fixe du chantier).', 19);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q20', 'concours-sujet-5', 'La visée avant, en nivellement, est', '[{"id":"A","text":"La visée faite sur le premier point observé","isCorrect":false},{"id":"B","text":"La visée faite sur le point d''altitude connue","isCorrect":false},{"id":"C","text":"La visée faite dans le sens du parcours uniquement","isCorrect":false},{"id":"D","text":"La visée faite sur le point dont on cherche à déterminer l''altitude (point inconnu)","isCorrect":true}]'::jsonb, 'D', 'Par convention : la visée arrière se fait sur un point d''altitude CONNUE (ou de référence), la visée avant sur le point dont on veut DÉTERMINER l''altitude.', 20);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q21', 'concours-sujet-5', 'La visée entre deux points A et B a donné les résultats suivants : visée arrière 1500 mm ; visée avant 2100 mm. Quelle est la valeur de la dénivelée entre les deux points ?', '[{"id":"A","text":"600 mm","isCorrect":false},{"id":"B","text":"3600 mm","isCorrect":false},{"id":"C","text":"-3600 mm","isCorrect":false},{"id":"D","text":"-600 mm","isCorrect":true}]'::jsonb, 'D', 'Dénivelée = Visée arrière − Visée avant = 1500 − 2100 = -600 mm.', 21);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q22', 'concours-sujet-5', 'La mesure directe des distances peut se faire :', '[{"id":"A","text":"Au ruban (ou au décamètre/chaîne d''arpenteur)","isCorrect":true},{"id":"B","text":"À l''aide du cercle optique","isCorrect":false},{"id":"C","text":"À l''aide d''une mire seule","isCorrect":false},{"id":"D","text":"À l''aide d''un théodolite","isCorrect":false}]'::jsonb, 'A', 'Une mesure DIRECTE consiste à appliquer physiquement un instrument gradué (ruban, décamètre) le long de la distance à mesurer. Le théodolite et la mire, eux, servent à des mesures INDIRECTES (angles, nivellement optique).', 22);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q23', 'concours-sujet-5', 'À quoi sert l''armature dans le béton armé ?', '[{"id":"A","text":"Reprendre les efforts de traction du béton","isCorrect":true},{"id":"B","text":"Empêcher le béton de rompre au flambement","isCorrect":false},{"id":"C","text":"Reprendre les efforts de compression du béton","isCorrect":false},{"id":"D","text":"Augmenter la résistance du béton en compression","isCorrect":false}]'::jsonb, 'A', 'Le béton résiste bien en compression mais très mal en traction : l''acier, qui résiste bien en traction, est associé au béton pour reprendre ces efforts (principe fondateur du béton armé).', 23);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q24', 'concours-sujet-5', 'Le système qui sépare la collecte des eaux usées/vannes et celle des eaux pluviales, dans deux réseaux distincts, est appelé', '[{"id":"A","text":"Le système séparatif","isCorrect":true},{"id":"B","text":"Le système mixte","isCorrect":false},{"id":"C","text":"Le système combiné","isCorrect":false},{"id":"D","text":"Le système unitaire","isCorrect":false}]'::jsonb, 'A', 'Le système séparatif utilise 2 réseaux distincts (eaux usées/vannes d''un côté, eaux pluviales de l''autre) ; le système unitaire les collecte ensemble dans un seul réseau.', 24);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q25', 'concours-sujet-5', 'Le traitement des eaux usées permet avant tout de', '[{"id":"A","text":"N''a aucune utilité réelle","isCorrect":false},{"id":"B","text":"Uniquement embellir le paysage","isCorrect":false},{"id":"C","text":"Polluer volontairement les cultures en aval","isCorrect":false},{"id":"D","text":"Protéger l''environnement (et la santé publique) en évitant le rejet de pollution dans le milieu naturel","isCorrect":true}]'::jsonb, 'D', 'Le traitement des eaux usées vise à réduire la charge polluante avant rejet dans le milieu naturel, protégeant ainsi l''environnement et la santé publique.', 25);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q26', 'concours-sujet-5', 'À quoi sert la vibration du béton lors de sa mise en œuvre ?', '[{"id":"A","text":"Accélérer la prise du ciment","isCorrect":false},{"id":"B","text":"Augmenter la résistance du béton au feu","isCorrect":false},{"id":"C","text":"Augmenter la résistance mécanique finale du béton au-delà de sa formulation","isCorrect":false},{"id":"D","text":"Empêcher la ségrégation des granulats et chasser les bulles d''air (nids de cailloux)","isCorrect":true}]'::jsonb, 'D', 'La vibration remplit correctement le coffrage, chasse l''air emprisonné et évite la ségrégation (séparation gravier/mortier), améliorant la compacité réelle du béton en place.', 26);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q27', 'concours-sujet-5', 'À quoi servent les dévers sur une chaussée ?', '[{"id":"A","text":"Uniquement améliorer l''esthétique de la route","isCorrect":false},{"id":"B","text":"Augmenter la vitesse autorisée des véhicules","isCorrect":false},{"id":"C","text":"Faciliter l''évacuation des eaux de ruissellement (et améliorer la tenue des véhicules en courbe)","isCorrect":true},{"id":"D","text":"Réduire la largeur utile de la chaussée","isCorrect":false}]'::jsonb, 'C', 'Le dévers (pente transversale) évacue l''eau de pluie vers les côtés de la chaussée et, en courbe, contribue à compenser la force centrifuge subie par les véhicules.', 27);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q28', 'concours-sujet-5', 'Une largeur de voie de circulation courante retenue en dimensionnement routier est de l''ordre de 3,50 m ; pour une route à deux voies, cela correspond à une largeur de chaussée de l''ordre de', '[{"id":"A","text":"6,5 mètres","isCorrect":false},{"id":"B","text":"10 mètres","isCorrect":false},{"id":"C","text":"8 mètres","isCorrect":false},{"id":"D","text":"7 mètres","isCorrect":true}]'::jsonb, 'D', 'Avec une largeur de voie usuelle d''environ 3,50 m, une chaussée à 2 voies (une par sens) totalise généralement une largeur de l''ordre de 7 m (valeur de référence à adapter selon la norme/le référentiel routier retenu localement).', 28);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q29', 'concours-sujet-5', 'Les dos d''âne (ralentisseurs) permettent de', '[{"id":"A","text":"Ralentir les véhicules (dispositif de modération de la vitesse)","isCorrect":true},{"id":"B","text":"Stopper complètement la circulation des véhicules","isCorrect":false},{"id":"C","text":"Augmenter le nombre de véhicules pouvant circuler","isCorrect":false},{"id":"D","text":"Protéger uniquement la chaussée de l''usure","isCorrect":false}]'::jsonb, 'A', 'Un dos d''âne est un dispositif de sécurité routière conçu pour contraindre les conducteurs à réduire leur vitesse, notamment en zone sensible (écoles, agglomérations).', 29);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s5-q30', 'concours-sujet-5', 'Un béton subit un retrait de 2%. Qu''appelle-t-on retrait ?', '[{"id":"A","text":"La diminution de la résistance du béton","isCorrect":false},{"id":"B","text":"La diminution du volume du béton suite à l''évaporation de l''eau (et aux réactions internes)","isCorrect":true},{"id":"C","text":"Le gonflement du béton en présence d''humidité","isCorrect":false},{"id":"D","text":"L''augmentation du volume du béton","isCorrect":false}]'::jsonb, 'B', 'Le retrait est une contraction (diminution de volume/longueur) du béton, principalement liée au départ d''eau (séchage) et aux réactions d''hydratation, distincte d''une perte de résistance.', 30);
insert into public.qcm_subjects (id, title, description, "order") values ('concours-sujet-6', 'Sujet 6 — Concours d''entrée BTP', '30 questions', 7);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q1', 'concours-sujet-6', 'Dans la relation f_bu = 0,85.f_c28 / (θ.γb), avec une durée d''application de la combinaison d''action considérée t = 12 h,', '[{"id":"A","text":"θ = 1","isCorrect":false},{"id":"B","text":"θ = 0,9","isCorrect":true},{"id":"C","text":"θ = 1,15","isCorrect":false},{"id":"D","text":"θ = 0,85","isCorrect":false}]'::jsonb, 'B', 'BAEL91 (A.4.3,41) : θ=1 si t>24h ; θ=0,9 si 1h<t≤24h ; θ=0,85 si t<1h. Ici t=12h, donc θ=0,9.', 1);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q2', 'concours-sujet-6', 'Le coefficient de fissuration η pour un rond lisse est', '[{"id":"A","text":"η = 1","isCorrect":true},{"id":"B","text":"η = 1,3","isCorrect":false},{"id":"C","text":"η = 1,5","isCorrect":false},{"id":"D","text":"η = 1,6","isCorrect":false}]'::jsonb, 'A', 'BAEL91 (A.4.5,3) : η=1 pour les ronds lisses (RL) ; η=1,6 pour les armatures Haute Adhérence (HA).', 2);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q3', 'concours-sujet-6', 'Le retrait du béton Δl/l en climat très humide vaut, à défaut de mesures (BAEL91) :', '[{"id":"A","text":"2 × 10⁻⁴","isCorrect":false},{"id":"B","text":"3 × 10⁻⁴","isCorrect":false},{"id":"C","text":"4 × 10⁻⁴","isCorrect":false},{"id":"D","text":"1,5 × 10⁻⁴","isCorrect":true}]'::jsonb, 'D', 'BAEL91 : retrait forfaitaire = 1,5×10⁻⁴ (très humide), 2×10⁻⁴ (humide), 3×10⁻⁴ (tempéré sec), 4×10⁻⁴ (chaud et sec), 5×10⁻⁴ (très sec/désertique).', 3);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q4', 'concours-sujet-6', 'La section entièrement comprimée (compression simple ou composée, faible excentricité) correspond au', '[{"id":"A","text":"Aucune","isCorrect":false},{"id":"B","text":"Pivot A","isCorrect":false},{"id":"C","text":"Pivot B","isCorrect":false},{"id":"D","text":"Pivot C","isCorrect":true}]'::jsonb, 'D', 'BAEL91 (A.4.3,3), règle des 3 pivots : Pivot A → allongement acier 10‰ ; Pivot B → raccourcissement béton 3,5‰ ; Pivot C → section entièrement comprimée.', 4);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q5', 'concours-sujet-6', 'En fissuration très préjudiciable, la contrainte limite de traction des aciers est :', '[{"id":"A","text":"σs = fe/γs sans autre condition","isCorrect":false},{"id":"B","text":"σs ≤ min{(2/3)fe ; max[0,5fe;110√(η.ftj)]}","isCorrect":false},{"id":"C","text":"σs ≤ min[0,5fe ; 90√(η.ftj)]","isCorrect":true},{"id":"D","text":"σs ≤ 0,8fe","isCorrect":false}]'::jsonb, 'C', 'BAEL91 (A.4.5,3) : peu préjudiciable → pas de limite spécifique (σs=fe/γs) ; préjudiciable → min{2/3fe ; max[0,5fe;110√(η.ftj)]} ; très préjudiciable → min[0,5fe ; 90√(η.ftj)].', 5);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q6', 'concours-sujet-6', 'À l''ELU, la contrainte de dimensionnement (calcul) de l''acier est', '[{"id":"A","text":"σs = 0,8.fe","isCorrect":false},{"id":"B","text":"σs = 0,6.fc28","isCorrect":false},{"id":"C","text":"σs = 0,85.fc28/(θ.γb)","isCorrect":false},{"id":"D","text":"σs = fe/γs","isCorrect":true}]'::jsonb, 'D', 'À l''ELU, dans le domaine des pivots A et B (palier plastique), la contrainte de calcul de l''acier vaut fe/γs (γs=1,15 en combinaison fondamentale).', 6);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q7', 'concours-sujet-6', 'Dans la relation f_t28 = 0,6 + 0,06.f_c28, l''unité considérée est le', '[{"id":"A","text":"bar","isCorrect":false},{"id":"B","text":"MPa","isCorrect":true},{"id":"C","text":"N/mm","isCorrect":false},{"id":"D","text":"Pa","isCorrect":false}]'::jsonb, 'B', 'La résistance caractéristique à la traction f_t28, comme f_c28, est exprimée en MPa dans le BAEL91.', 7);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q8', 'concours-sujet-6', 'Le coefficient γb pour les combinaisons accidentelles vaut', '[{"id":"A","text":"1,35","isCorrect":false},{"id":"B","text":"1,5","isCorrect":false},{"id":"C","text":"1,15","isCorrect":true},{"id":"D","text":"1","isCorrect":false}]'::jsonb, 'C', 'BAEL91 : γb = 1,5 pour les combinaisons fondamentales, γb = 1,15 pour les combinaisons accidentelles.', 8);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q9', 'concours-sujet-6', 'Un béton a une résistance en compression f_c28 = 30 MPa. Quelle est sa résistance en traction f_t28 (formule f_t28 = 0,6+0,06.f_c28) ?', '[{"id":"A","text":"18.6 MPa","isCorrect":false},{"id":"B","text":"2.9 MPa","isCorrect":false},{"id":"C","text":"2.4 MPa","isCorrect":true},{"id":"D","text":"1.8 MPa","isCorrect":false}]'::jsonb, 'C', 'f_t28 = 0,6 + 0,06 × 30 = 2.4 MPa.', 9);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q10', 'concours-sujet-6', 'On applique sur une éprouvette de béton de diamètre d=10 cm un effort de compression de 900 N. Quelle est la valeur de la contrainte de compression (σ=F/S, S=π.d²/4) ?', '[{"id":"A","text":"131 780 Pa","isCorrect":false},{"id":"B","text":"99 695 Pa","isCorrect":false},{"id":"C","text":"114 592 Pa","isCorrect":true},{"id":"D","text":"80 214 Pa","isCorrect":false}]'::jsonb, 'C', 'S = π × (0,10)²/4 = 0.007854 m². σ = F/S = 900/0.007854 = 114 592 Pa (arrondi).', 10);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q11', 'concours-sujet-6', 'Soit une poutre isostatique AB, reposant sur des appuis simples en A et B distants de L, supportant une charge concentrée P située à la distance a de l''appui A et b de l''appui B (a+b=L). L''expression de RB est :', '[{"id":"A","text":"R_B = P.a/L","isCorrect":true},{"id":"B","text":"R_B = P(1-b/L)","isCorrect":false},{"id":"C","text":"R_B = P.b/L","isCorrect":false},{"id":"D","text":"R_B = P.b²/L","isCorrect":false}]'::jsonb, 'A', 'Équilibre des moments : ΣM/A=0 → R_B × L = P × a → R_B=P.a/L. De même R_A=P.b/L (R_A+R_B=P).', 11);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q12', 'concours-sujet-6', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour un appui simple de poutre ?', '[{"id":"A","text":"3","isCorrect":false},{"id":"B","text":"4","isCorrect":false},{"id":"C","text":"1","isCorrect":true},{"id":"D","text":"2","isCorrect":false}]'::jsonb, 'C', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 12);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q13', 'concours-sujet-6', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour une articulation de poutre ?', '[{"id":"A","text":"3","isCorrect":false},{"id":"B","text":"2","isCorrect":true},{"id":"C","text":"4","isCorrect":false},{"id":"D","text":"1","isCorrect":false}]'::jsonb, 'B', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 13);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q14', 'concours-sujet-6', 'Les blocs creux (éléments de remplissage) des planchers à corps creux sont appelés', '[{"id":"A","text":"Nervures","isCorrect":false},{"id":"B","text":"Poutrelles","isCorrect":false},{"id":"C","text":"Agglomérés","isCorrect":false},{"id":"D","text":"Hourdis (ou entrevous)","isCorrect":true}]'::jsonb, 'D', 'Les éléments de remplissage/coffrage perdu d''un plancher à corps creux sont appelés hourdis, ou entrevous.', 14);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q15', 'concours-sujet-6', 'La dalle de béton coulée sur les hourdis d''un plancher à corps creux est appelée', '[{"id":"A","text":"Semelle filante","isCorrect":false},{"id":"B","text":"Radier","isCorrect":false},{"id":"C","text":"Dallage","isCorrect":false},{"id":"D","text":"Dalle de compression (ou table de compression)","isCorrect":true}]'::jsonb, 'D', 'La fine dalle armée (souvent 4 à 5 cm) coulée au-dessus des hourdis/nervures est la dalle (ou table) de compression.', 15);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q16', 'concours-sujet-6', 'La semelle de fondation située sous un mur (fondation continue) est appelée', '[{"id":"A","text":"Radier","isCorrect":false},{"id":"B","text":"Semelle sur pieux","isCorrect":false},{"id":"C","text":"Semelle filante","isCorrect":true},{"id":"D","text":"Semelle isolée","isCorrect":false}]'::jsonb, 'C', 'Une semelle continue sous un mur porteur est une semelle filante, par opposition à une semelle isolée sous un poteau.', 16);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q17', 'concours-sujet-6', 'Une dalle rectangulaire appuyée sur ses quatre côtés, avec lx/ly > 0,4 (lx = plus petite portée), porte suivant', '[{"id":"A","text":"Quatre sens","isCorrect":false},{"id":"B","text":"Aucun sens (dalle non porteuse)","isCorrect":false},{"id":"C","text":"Un sens","isCorrect":false},{"id":"D","text":"Deux sens","isCorrect":true}]'::jsonb, 'D', 'Règle courante (BAEL/annexe E) : si lx/ly > 0,4, la dalle porte dans les deux sens (flexion bidirectionnelle) ; en dessous, on la calcule comme portant dans un seul sens.', 17);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q18', 'concours-sujet-6', 'Une dalle située au niveau d''un étage (et non au rez-de-chaussée sur terre-plein) est appelée', '[{"id":"A","text":"Dalle sur vide sanitaire","isCorrect":false},{"id":"B","text":"Plancher","isCorrect":true},{"id":"C","text":"Dallage","isCorrect":false},{"id":"D","text":"Radier","isCorrect":false}]'::jsonb, 'B', 'Par convention, on réserve le terme « plancher » à une dalle d''étage (porteuse, en élévation), et « dallage »/« dalle sur terre-plein » à une dalle basse posée sur le sol.', 18);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q19', 'concours-sujet-6', 'L''altitude relative d''un point est', '[{"id":"A","text":"La position du point par rapport au niveau de la mer","isCorrect":false},{"id":"B","text":"La position du point par rapport au géoïde","isCorrect":false},{"id":"C","text":"La position (en hauteur) du point par rapport à un point de référence fixe, choisi arbitrairement pour le chantier","isCorrect":true},{"id":"D","text":"Une notion qui n''existe pas en topographie","isCorrect":false}]'::jsonb, 'C', 'Contrairement à l''altitude absolue (repérée au niveau de la mer/géoïde, IGN par exemple), l''altitude relative se mesure par rapport à un repère local arbitraire (souvent une borne ou un point fixe du chantier).', 19);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q20', 'concours-sujet-6', 'La visée avant, en nivellement, est', '[{"id":"A","text":"La visée faite sur le point d''altitude connue","isCorrect":false},{"id":"B","text":"La visée faite sur le point dont on cherche à déterminer l''altitude (point inconnu)","isCorrect":true},{"id":"C","text":"La visée faite dans le sens du parcours uniquement","isCorrect":false},{"id":"D","text":"La visée faite sur le premier point observé","isCorrect":false}]'::jsonb, 'B', 'Par convention : la visée arrière se fait sur un point d''altitude CONNUE (ou de référence), la visée avant sur le point dont on veut DÉTERMINER l''altitude.', 20);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q21', 'concours-sujet-6', 'La visée entre deux points A et B a donné les résultats suivants : visée arrière 2650 mm ; visée avant 1980 mm. Quelle est la valeur de la dénivelée entre les deux points ?', '[{"id":"A","text":"-670 mm","isCorrect":false},{"id":"B","text":"-4630 mm","isCorrect":false},{"id":"C","text":"4630 mm","isCorrect":false},{"id":"D","text":"670 mm","isCorrect":true}]'::jsonb, 'D', 'Dénivelée = Visée arrière − Visée avant = 2650 − 1980 = 670 mm.', 21);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q22', 'concours-sujet-6', 'La mesure directe des distances peut se faire :', '[{"id":"A","text":"Au ruban (ou au décamètre/chaîne d''arpenteur)","isCorrect":true},{"id":"B","text":"À l''aide d''un théodolite","isCorrect":false},{"id":"C","text":"À l''aide du cercle optique","isCorrect":false},{"id":"D","text":"À l''aide d''une mire seule","isCorrect":false}]'::jsonb, 'A', 'Une mesure DIRECTE consiste à appliquer physiquement un instrument gradué (ruban, décamètre) le long de la distance à mesurer. Le théodolite et la mire, eux, servent à des mesures INDIRECTES (angles, nivellement optique).', 22);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q23', 'concours-sujet-6', 'À quoi sert l''armature dans le béton armé ?', '[{"id":"A","text":"Empêcher le béton de rompre au flambement","isCorrect":false},{"id":"B","text":"Reprendre les efforts de traction du béton","isCorrect":true},{"id":"C","text":"Reprendre les efforts de compression du béton","isCorrect":false},{"id":"D","text":"Augmenter la résistance du béton en compression","isCorrect":false}]'::jsonb, 'B', 'Le béton résiste bien en compression mais très mal en traction : l''acier, qui résiste bien en traction, est associé au béton pour reprendre ces efforts (principe fondateur du béton armé).', 23);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q24', 'concours-sujet-6', 'Le système qui sépare la collecte des eaux usées/vannes et celle des eaux pluviales, dans deux réseaux distincts, est appelé', '[{"id":"A","text":"Le système combiné","isCorrect":false},{"id":"B","text":"Le système unitaire","isCorrect":false},{"id":"C","text":"Le système mixte","isCorrect":false},{"id":"D","text":"Le système séparatif","isCorrect":true}]'::jsonb, 'D', 'Le système séparatif utilise 2 réseaux distincts (eaux usées/vannes d''un côté, eaux pluviales de l''autre) ; le système unitaire les collecte ensemble dans un seul réseau.', 24);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q25', 'concours-sujet-6', 'Le traitement des eaux usées permet avant tout de', '[{"id":"A","text":"Uniquement embellir le paysage","isCorrect":false},{"id":"B","text":"Protéger l''environnement (et la santé publique) en évitant le rejet de pollution dans le milieu naturel","isCorrect":true},{"id":"C","text":"N''a aucune utilité réelle","isCorrect":false},{"id":"D","text":"Polluer volontairement les cultures en aval","isCorrect":false}]'::jsonb, 'B', 'Le traitement des eaux usées vise à réduire la charge polluante avant rejet dans le milieu naturel, protégeant ainsi l''environnement et la santé publique.', 25);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q26', 'concours-sujet-6', 'À quoi sert la vibration du béton lors de sa mise en œuvre ?', '[{"id":"A","text":"Augmenter la résistance mécanique finale du béton au-delà de sa formulation","isCorrect":false},{"id":"B","text":"Augmenter la résistance du béton au feu","isCorrect":false},{"id":"C","text":"Empêcher la ségrégation des granulats et chasser les bulles d''air (nids de cailloux)","isCorrect":true},{"id":"D","text":"Accélérer la prise du ciment","isCorrect":false}]'::jsonb, 'C', 'La vibration remplit correctement le coffrage, chasse l''air emprisonné et évite la ségrégation (séparation gravier/mortier), améliorant la compacité réelle du béton en place.', 26);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q27', 'concours-sujet-6', 'À quoi servent les dévers sur une chaussée ?', '[{"id":"A","text":"Uniquement améliorer l''esthétique de la route","isCorrect":false},{"id":"B","text":"Augmenter la vitesse autorisée des véhicules","isCorrect":false},{"id":"C","text":"Réduire la largeur utile de la chaussée","isCorrect":false},{"id":"D","text":"Faciliter l''évacuation des eaux de ruissellement (et améliorer la tenue des véhicules en courbe)","isCorrect":true}]'::jsonb, 'D', 'Le dévers (pente transversale) évacue l''eau de pluie vers les côtés de la chaussée et, en courbe, contribue à compenser la force centrifuge subie par les véhicules.', 27);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q28', 'concours-sujet-6', 'Une largeur de voie de circulation courante retenue en dimensionnement routier est de l''ordre de 3,50 m ; pour une route à deux voies, cela correspond à une largeur de chaussée de l''ordre de', '[{"id":"A","text":"6,5 mètres","isCorrect":false},{"id":"B","text":"8 mètres","isCorrect":false},{"id":"C","text":"10 mètres","isCorrect":false},{"id":"D","text":"7 mètres","isCorrect":true}]'::jsonb, 'D', 'Avec une largeur de voie usuelle d''environ 3,50 m, une chaussée à 2 voies (une par sens) totalise généralement une largeur de l''ordre de 7 m (valeur de référence à adapter selon la norme/le référentiel routier retenu localement).', 28);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q29', 'concours-sujet-6', 'Les dos d''âne (ralentisseurs) permettent de', '[{"id":"A","text":"Stopper complètement la circulation des véhicules","isCorrect":false},{"id":"B","text":"Protéger uniquement la chaussée de l''usure","isCorrect":false},{"id":"C","text":"Augmenter le nombre de véhicules pouvant circuler","isCorrect":false},{"id":"D","text":"Ralentir les véhicules (dispositif de modération de la vitesse)","isCorrect":true}]'::jsonb, 'D', 'Un dos d''âne est un dispositif de sécurité routière conçu pour contraindre les conducteurs à réduire leur vitesse, notamment en zone sensible (écoles, agglomérations).', 29);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s6-q30', 'concours-sujet-6', 'Un béton subit un retrait de 2%. Qu''appelle-t-on retrait ?', '[{"id":"A","text":"La diminution du volume du béton suite à l''évaporation de l''eau (et aux réactions internes)","isCorrect":true},{"id":"B","text":"L''augmentation du volume du béton","isCorrect":false},{"id":"C","text":"Le gonflement du béton en présence d''humidité","isCorrect":false},{"id":"D","text":"La diminution de la résistance du béton","isCorrect":false}]'::jsonb, 'A', 'Le retrait est une contraction (diminution de volume/longueur) du béton, principalement liée au départ d''eau (séchage) et aux réactions d''hydratation, distincte d''une perte de résistance.', 30);
insert into public.qcm_subjects (id, title, description, "order") values ('concours-sujet-7', 'Sujet 7 — Concours d''entrée BTP', '30 questions', 8);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q1', 'concours-sujet-7', 'Dans la relation f_bu = 0,85.f_c28 / (θ.γb), avec une durée d''application de la combinaison d''action considérée t = 20 h,', '[{"id":"A","text":"θ = 1","isCorrect":false},{"id":"B","text":"θ = 1,15","isCorrect":false},{"id":"C","text":"θ = 0,85","isCorrect":false},{"id":"D","text":"θ = 0,9","isCorrect":true}]'::jsonb, 'D', 'BAEL91 (A.4.3,41) : θ=1 si t>24h ; θ=0,9 si 1h<t≤24h ; θ=0,85 si t<1h. Ici t=20h, donc θ=0,9.', 1);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q2', 'concours-sujet-7', 'Le coefficient de fissuration η pour une armature Haute Adhérence de diamètre φ=20mm est', '[{"id":"A","text":"η = 1","isCorrect":false},{"id":"B","text":"η = 2","isCorrect":false},{"id":"C","text":"η = 1,3","isCorrect":false},{"id":"D","text":"η = 1,6","isCorrect":true}]'::jsonb, 'D', 'BAEL91 (A.4.5,3) : η=1 pour les ronds lisses (RL) ; η=1,6 pour les armatures Haute Adhérence (HA).', 2);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q3', 'concours-sujet-7', 'Le retrait du béton Δl/l en climat humide vaut, à défaut de mesures (BAEL91) :', '[{"id":"A","text":"3 × 10⁻⁴","isCorrect":false},{"id":"B","text":"2 × 10⁻⁴","isCorrect":true},{"id":"C","text":"1,5 × 10⁻⁴","isCorrect":false},{"id":"D","text":"4 × 10⁻⁴","isCorrect":false}]'::jsonb, 'B', 'BAEL91 : retrait forfaitaire = 1,5×10⁻⁴ (très humide), 2×10⁻⁴ (humide), 3×10⁻⁴ (tempéré sec), 4×10⁻⁴ (chaud et sec), 5×10⁻⁴ (très sec/désertique).', 3);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q4', 'concours-sujet-7', 'L''allongement de l''armature la plus tendue εs=10×10⁻³ (pivot correspondant) se trouve', '[{"id":"A","text":"Pivot B","isCorrect":false},{"id":"B","text":"Aucune","isCorrect":false},{"id":"C","text":"Pivot A","isCorrect":true},{"id":"D","text":"Pivot C","isCorrect":false}]'::jsonb, 'C', 'BAEL91 (A.4.3,3), règle des 3 pivots : Pivot A → allongement acier 10‰ ; Pivot B → raccourcissement béton 3,5‰ ; Pivot C → section entièrement comprimée.', 4);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q5', 'concours-sujet-7', 'En fissuration peu préjudiciable, la contrainte limite de traction des aciers est :', '[{"id":"A","text":"σs = fe/γs (aucune limitation supplémentaire liée à la fissuration)","isCorrect":true},{"id":"B","text":"σs ≤ min(0,5fe ; 90√(η.ftj))","isCorrect":false},{"id":"C","text":"σs ≤ min(0,5fe ; 110√(η.ftj))","isCorrect":false},{"id":"D","text":"σs ≤ (2/3)fe","isCorrect":false}]'::jsonb, 'A', 'BAEL91 (A.4.5,3) : peu préjudiciable → pas de limite spécifique (σs=fe/γs) ; préjudiciable → min{2/3fe ; max[0,5fe;110√(η.ftj)]} ; très préjudiciable → min[0,5fe ; 90√(η.ftj)].', 5);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q6', 'concours-sujet-7', 'À l''ELU, la contrainte de dimensionnement (calcul) de l''acier est', '[{"id":"A","text":"σs = 0,85.fc28/(θ.γb)","isCorrect":false},{"id":"B","text":"σs = fe/γs","isCorrect":true},{"id":"C","text":"σs = 0,6.fc28","isCorrect":false},{"id":"D","text":"σs = 0,8.fe","isCorrect":false}]'::jsonb, 'B', 'À l''ELU, dans le domaine des pivots A et B (palier plastique), la contrainte de calcul de l''acier vaut fe/γs (γs=1,15 en combinaison fondamentale).', 6);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q7', 'concours-sujet-7', 'Dans la relation f_bu = 0,85.f_c28/(θ.γb), l''unité considérée pour f_bu est le', '[{"id":"A","text":"MPa (mégapascal)","isCorrect":true},{"id":"B","text":"bar","isCorrect":false},{"id":"C","text":"Pa (pascal)","isCorrect":false},{"id":"D","text":"kg/cm²","isCorrect":false}]'::jsonb, 'A', 'f_bu (contrainte de calcul du béton à l''ELU) et f_c28 s''expriment en MPa dans les formules du BAEL91.', 7);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q8', 'concours-sujet-7', 'Le coefficient γb pour les combinaisons fondamentales vaut', '[{"id":"A","text":"1,15","isCorrect":false},{"id":"B","text":"1,35","isCorrect":false},{"id":"C","text":"1","isCorrect":false},{"id":"D","text":"1,5","isCorrect":true}]'::jsonb, 'D', 'BAEL91 : γb = 1,5 pour les combinaisons fondamentales, γb = 1,15 pour les combinaisons accidentelles.', 8);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q9', 'concours-sujet-7', 'Un béton a une résistance en compression f_c28 = 32 MPa. Quelle est sa résistance en traction f_t28 (formule f_t28 = 0,6+0,06.f_c28) ?', '[{"id":"A","text":"1.92 MPa","isCorrect":false},{"id":"B","text":"3.02 MPa","isCorrect":false},{"id":"C","text":"19.8 MPa","isCorrect":false},{"id":"D","text":"2.52 MPa","isCorrect":true}]'::jsonb, 'D', 'f_t28 = 0,6 + 0,06 × 32 = 2.52 MPa.', 9);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q10', 'concours-sujet-7', 'On applique sur une éprouvette de béton de diamètre d=20 cm un effort de compression de 2500 N. Quelle est la valeur de la contrainte de compression (σ=F/S, S=π.d²/4) ?', '[{"id":"A","text":"79 577 Pa","isCorrect":true},{"id":"B","text":"55 704 Pa","isCorrect":false},{"id":"C","text":"69 232 Pa","isCorrect":false},{"id":"D","text":"91 514 Pa","isCorrect":false}]'::jsonb, 'A', 'S = π × (0,20)²/4 = 0.031416 m². σ = F/S = 2500/0.031416 = 79 577 Pa (arrondi).', 10);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q11', 'concours-sujet-7', 'Soit une poutre isostatique AB, reposant sur des appuis simples en A et B distants de L, supportant une charge concentrée P située à la distance a de l''appui A et b de l''appui B (a+b=L). L''expression de RA est :', '[{"id":"A","text":"R_A = P.a²/L","isCorrect":false},{"id":"B","text":"R_A = P(1-a/L)","isCorrect":false},{"id":"C","text":"R_A = P.b/L","isCorrect":true},{"id":"D","text":"R_A = P.a/L","isCorrect":false}]'::jsonb, 'C', 'Équilibre des moments : ΣM/B=0 → R_A × L = P × b → R_A=P.b/L. De même R_B=P.a/L (R_A+R_B=P).', 11);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q12', 'concours-sujet-7', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour un appui simple de poutre ?', '[{"id":"A","text":"4","isCorrect":false},{"id":"B","text":"3","isCorrect":false},{"id":"C","text":"2","isCorrect":false},{"id":"D","text":"1","isCorrect":true}]'::jsonb, 'D', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 12);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q13', 'concours-sujet-7', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour une articulation de poutre ?', '[{"id":"A","text":"1","isCorrect":false},{"id":"B","text":"4","isCorrect":false},{"id":"C","text":"3","isCorrect":false},{"id":"D","text":"2","isCorrect":true}]'::jsonb, 'D', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 13);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q14', 'concours-sujet-7', 'Les blocs creux (éléments de remplissage) des planchers à corps creux sont appelés', '[{"id":"A","text":"Hourdis (ou entrevous)","isCorrect":true},{"id":"B","text":"Poutrelles","isCorrect":false},{"id":"C","text":"Agglomérés","isCorrect":false},{"id":"D","text":"Nervures","isCorrect":false}]'::jsonb, 'A', 'Les éléments de remplissage/coffrage perdu d''un plancher à corps creux sont appelés hourdis, ou entrevous.', 14);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q15', 'concours-sujet-7', 'La dalle de béton coulée sur les hourdis d''un plancher à corps creux est appelée', '[{"id":"A","text":"Dalle de compression (ou table de compression)","isCorrect":true},{"id":"B","text":"Radier","isCorrect":false},{"id":"C","text":"Dallage","isCorrect":false},{"id":"D","text":"Semelle filante","isCorrect":false}]'::jsonb, 'A', 'La fine dalle armée (souvent 4 à 5 cm) coulée au-dessus des hourdis/nervures est la dalle (ou table) de compression.', 15);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q16', 'concours-sujet-7', 'La semelle de fondation située sous un mur (fondation continue) est appelée', '[{"id":"A","text":"Semelle isolée","isCorrect":false},{"id":"B","text":"Radier","isCorrect":false},{"id":"C","text":"Semelle sur pieux","isCorrect":false},{"id":"D","text":"Semelle filante","isCorrect":true}]'::jsonb, 'D', 'Une semelle continue sous un mur porteur est une semelle filante, par opposition à une semelle isolée sous un poteau.', 16);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q17', 'concours-sujet-7', 'Une dalle rectangulaire appuyée sur ses quatre côtés, avec lx/ly > 0,4 (lx = plus petite portée), porte suivant', '[{"id":"A","text":"Aucun sens (dalle non porteuse)","isCorrect":false},{"id":"B","text":"Un sens","isCorrect":false},{"id":"C","text":"Deux sens","isCorrect":true},{"id":"D","text":"Quatre sens","isCorrect":false}]'::jsonb, 'C', 'Règle courante (BAEL/annexe E) : si lx/ly > 0,4, la dalle porte dans les deux sens (flexion bidirectionnelle) ; en dessous, on la calcule comme portant dans un seul sens.', 17);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q18', 'concours-sujet-7', 'Une dalle située au niveau d''un étage (et non au rez-de-chaussée sur terre-plein) est appelée', '[{"id":"A","text":"Dallage","isCorrect":false},{"id":"B","text":"Dalle sur vide sanitaire","isCorrect":false},{"id":"C","text":"Radier","isCorrect":false},{"id":"D","text":"Plancher","isCorrect":true}]'::jsonb, 'D', 'Par convention, on réserve le terme « plancher » à une dalle d''étage (porteuse, en élévation), et « dallage »/« dalle sur terre-plein » à une dalle basse posée sur le sol.', 18);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q19', 'concours-sujet-7', 'L''altitude relative d''un point est', '[{"id":"A","text":"Une notion qui n''existe pas en topographie","isCorrect":false},{"id":"B","text":"La position du point par rapport au géoïde","isCorrect":false},{"id":"C","text":"La position du point par rapport au niveau de la mer","isCorrect":false},{"id":"D","text":"La position (en hauteur) du point par rapport à un point de référence fixe, choisi arbitrairement pour le chantier","isCorrect":true}]'::jsonb, 'D', 'Contrairement à l''altitude absolue (repérée au niveau de la mer/géoïde, IGN par exemple), l''altitude relative se mesure par rapport à un repère local arbitraire (souvent une borne ou un point fixe du chantier).', 19);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q20', 'concours-sujet-7', 'La visée avant, en nivellement, est', '[{"id":"A","text":"La visée faite dans le sens du parcours uniquement","isCorrect":false},{"id":"B","text":"La visée faite sur le point dont on cherche à déterminer l''altitude (point inconnu)","isCorrect":true},{"id":"C","text":"La visée faite sur le point d''altitude connue","isCorrect":false},{"id":"D","text":"La visée faite sur le premier point observé","isCorrect":false}]'::jsonb, 'B', 'Par convention : la visée arrière se fait sur un point d''altitude CONNUE (ou de référence), la visée avant sur le point dont on veut DÉTERMINER l''altitude.', 20);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q21', 'concours-sujet-7', 'La visée entre deux points A et B a donné les résultats suivants : visée arrière 3300 mm ; visée avant 3700 mm. Quelle est la valeur de la dénivelée entre les deux points ?', '[{"id":"A","text":"-7000 mm","isCorrect":false},{"id":"B","text":"7000 mm","isCorrect":false},{"id":"C","text":"-400 mm","isCorrect":true},{"id":"D","text":"400 mm","isCorrect":false}]'::jsonb, 'C', 'Dénivelée = Visée arrière − Visée avant = 3300 − 3700 = -400 mm.', 21);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q22', 'concours-sujet-7', 'La mesure directe des distances peut se faire :', '[{"id":"A","text":"Au ruban (ou au décamètre/chaîne d''arpenteur)","isCorrect":true},{"id":"B","text":"À l''aide d''une mire seule","isCorrect":false},{"id":"C","text":"À l''aide d''un théodolite","isCorrect":false},{"id":"D","text":"À l''aide du cercle optique","isCorrect":false}]'::jsonb, 'A', 'Une mesure DIRECTE consiste à appliquer physiquement un instrument gradué (ruban, décamètre) le long de la distance à mesurer. Le théodolite et la mire, eux, servent à des mesures INDIRECTES (angles, nivellement optique).', 22);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q23', 'concours-sujet-7', 'À quoi sert l''armature dans le béton armé ?', '[{"id":"A","text":"Reprendre les efforts de compression du béton","isCorrect":false},{"id":"B","text":"Augmenter la résistance du béton en compression","isCorrect":false},{"id":"C","text":"Reprendre les efforts de traction du béton","isCorrect":true},{"id":"D","text":"Empêcher le béton de rompre au flambement","isCorrect":false}]'::jsonb, 'C', 'Le béton résiste bien en compression mais très mal en traction : l''acier, qui résiste bien en traction, est associé au béton pour reprendre ces efforts (principe fondateur du béton armé).', 23);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q24', 'concours-sujet-7', 'Le système qui sépare la collecte des eaux usées/vannes et celle des eaux pluviales, dans deux réseaux distincts, est appelé', '[{"id":"A","text":"Le système combiné","isCorrect":false},{"id":"B","text":"Le système unitaire","isCorrect":false},{"id":"C","text":"Le système mixte","isCorrect":false},{"id":"D","text":"Le système séparatif","isCorrect":true}]'::jsonb, 'D', 'Le système séparatif utilise 2 réseaux distincts (eaux usées/vannes d''un côté, eaux pluviales de l''autre) ; le système unitaire les collecte ensemble dans un seul réseau.', 24);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q25', 'concours-sujet-7', 'Le traitement des eaux usées permet avant tout de', '[{"id":"A","text":"Protéger l''environnement (et la santé publique) en évitant le rejet de pollution dans le milieu naturel","isCorrect":true},{"id":"B","text":"N''a aucune utilité réelle","isCorrect":false},{"id":"C","text":"Uniquement embellir le paysage","isCorrect":false},{"id":"D","text":"Polluer volontairement les cultures en aval","isCorrect":false}]'::jsonb, 'A', 'Le traitement des eaux usées vise à réduire la charge polluante avant rejet dans le milieu naturel, protégeant ainsi l''environnement et la santé publique.', 25);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q26', 'concours-sujet-7', 'À quoi sert la vibration du béton lors de sa mise en œuvre ?', '[{"id":"A","text":"Accélérer la prise du ciment","isCorrect":false},{"id":"B","text":"Augmenter la résistance du béton au feu","isCorrect":false},{"id":"C","text":"Empêcher la ségrégation des granulats et chasser les bulles d''air (nids de cailloux)","isCorrect":true},{"id":"D","text":"Augmenter la résistance mécanique finale du béton au-delà de sa formulation","isCorrect":false}]'::jsonb, 'C', 'La vibration remplit correctement le coffrage, chasse l''air emprisonné et évite la ségrégation (séparation gravier/mortier), améliorant la compacité réelle du béton en place.', 26);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q27', 'concours-sujet-7', 'À quoi servent les dévers sur une chaussée ?', '[{"id":"A","text":"Réduire la largeur utile de la chaussée","isCorrect":false},{"id":"B","text":"Uniquement améliorer l''esthétique de la route","isCorrect":false},{"id":"C","text":"Augmenter la vitesse autorisée des véhicules","isCorrect":false},{"id":"D","text":"Faciliter l''évacuation des eaux de ruissellement (et améliorer la tenue des véhicules en courbe)","isCorrect":true}]'::jsonb, 'D', 'Le dévers (pente transversale) évacue l''eau de pluie vers les côtés de la chaussée et, en courbe, contribue à compenser la force centrifuge subie par les véhicules.', 27);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q28', 'concours-sujet-7', 'Une largeur de voie de circulation courante retenue en dimensionnement routier est de l''ordre de 3,50 m ; pour une route à deux voies, cela correspond à une largeur de chaussée de l''ordre de', '[{"id":"A","text":"8 mètres","isCorrect":false},{"id":"B","text":"7 mètres","isCorrect":true},{"id":"C","text":"10 mètres","isCorrect":false},{"id":"D","text":"6,5 mètres","isCorrect":false}]'::jsonb, 'B', 'Avec une largeur de voie usuelle d''environ 3,50 m, une chaussée à 2 voies (une par sens) totalise généralement une largeur de l''ordre de 7 m (valeur de référence à adapter selon la norme/le référentiel routier retenu localement).', 28);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q29', 'concours-sujet-7', 'Les dos d''âne (ralentisseurs) permettent de', '[{"id":"A","text":"Ralentir les véhicules (dispositif de modération de la vitesse)","isCorrect":true},{"id":"B","text":"Augmenter le nombre de véhicules pouvant circuler","isCorrect":false},{"id":"C","text":"Stopper complètement la circulation des véhicules","isCorrect":false},{"id":"D","text":"Protéger uniquement la chaussée de l''usure","isCorrect":false}]'::jsonb, 'A', 'Un dos d''âne est un dispositif de sécurité routière conçu pour contraindre les conducteurs à réduire leur vitesse, notamment en zone sensible (écoles, agglomérations).', 29);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s7-q30', 'concours-sujet-7', 'Un béton subit un retrait de 2%. Qu''appelle-t-on retrait ?', '[{"id":"A","text":"Le gonflement du béton en présence d''humidité","isCorrect":false},{"id":"B","text":"La diminution de la résistance du béton","isCorrect":false},{"id":"C","text":"La diminution du volume du béton suite à l''évaporation de l''eau (et aux réactions internes)","isCorrect":true},{"id":"D","text":"L''augmentation du volume du béton","isCorrect":false}]'::jsonb, 'C', 'Le retrait est une contraction (diminution de volume/longueur) du béton, principalement liée au départ d''eau (séchage) et aux réactions d''hydratation, distincte d''une perte de résistance.', 30);
insert into public.qcm_subjects (id, title, description, "order") values ('concours-sujet-8', 'Sujet 8 — Concours d''entrée BTP', '30 questions', 9);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q1', 'concours-sujet-8', 'Dans la relation f_bu = 0,85.f_c28 / (θ.γb), avec une durée d''application de la combinaison d''action considérée t = 30 h,', '[{"id":"A","text":"θ = 1,15","isCorrect":false},{"id":"B","text":"θ = 0,9","isCorrect":false},{"id":"C","text":"θ = 0,85","isCorrect":false},{"id":"D","text":"θ = 1","isCorrect":true}]'::jsonb, 'D', 'BAEL91 (A.4.3,41) : θ=1 si t>24h ; θ=0,9 si 1h<t≤24h ; θ=0,85 si t<1h. Ici t=30h, donc θ=1.', 1);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q2', 'concours-sujet-8', 'Le coefficient de fissuration η pour un rond lisse est', '[{"id":"A","text":"η = 1,6","isCorrect":false},{"id":"B","text":"η = 1,3","isCorrect":false},{"id":"C","text":"η = 1","isCorrect":true},{"id":"D","text":"η = 1,5","isCorrect":false}]'::jsonb, 'C', 'BAEL91 (A.4.5,3) : η=1 pour les ronds lisses (RL) ; η=1,6 pour les armatures Haute Adhérence (HA).', 2);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q3', 'concours-sujet-8', 'Le retrait du béton Δl/l en climat tempéré sec vaut, à défaut de mesures (BAEL91) :', '[{"id":"A","text":"4 × 10⁻⁴","isCorrect":false},{"id":"B","text":"1,5 × 10⁻⁴","isCorrect":false},{"id":"C","text":"2 × 10⁻⁴","isCorrect":false},{"id":"D","text":"3 × 10⁻⁴","isCorrect":true}]'::jsonb, 'D', 'BAEL91 : retrait forfaitaire = 1,5×10⁻⁴ (très humide), 2×10⁻⁴ (humide), 3×10⁻⁴ (tempéré sec), 4×10⁻⁴ (chaud et sec), 5×10⁻⁴ (très sec/désertique).', 3);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q4', 'concours-sujet-8', 'Le raccourcissement de la fibre de béton la plus comprimée εbc=3,5×10⁻³ se trouve', '[{"id":"A","text":"Aucune","isCorrect":false},{"id":"B","text":"Pivot B","isCorrect":true},{"id":"C","text":"Pivot A","isCorrect":false},{"id":"D","text":"Pivot C","isCorrect":false}]'::jsonb, 'B', 'BAEL91 (A.4.3,3), règle des 3 pivots : Pivot A → allongement acier 10‰ ; Pivot B → raccourcissement béton 3,5‰ ; Pivot C → section entièrement comprimée.', 4);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q5', 'concours-sujet-8', 'En fissuration préjudiciable, la contrainte limite de traction des aciers est :', '[{"id":"A","text":"σs ≤ min[0,5fe ; 90√(η.ftj)]","isCorrect":false},{"id":"B","text":"σs ≤ min{(2/3)fe ; max[0,5fe;110√(η.ftj)]}","isCorrect":true},{"id":"C","text":"σs = fe/γs sans autre condition","isCorrect":false},{"id":"D","text":"σs ≤ 0,6fe","isCorrect":false}]'::jsonb, 'B', 'BAEL91 (A.4.5,3) : peu préjudiciable → pas de limite spécifique (σs=fe/γs) ; préjudiciable → min{2/3fe ; max[0,5fe;110√(η.ftj)]} ; très préjudiciable → min[0,5fe ; 90√(η.ftj)].', 5);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q6', 'concours-sujet-8', 'À l''ELU, la contrainte de dimensionnement (calcul) de l''acier est', '[{"id":"A","text":"σs = fe/γs","isCorrect":true},{"id":"B","text":"σs = 0,8.fe","isCorrect":false},{"id":"C","text":"σs = 0,6.fc28","isCorrect":false},{"id":"D","text":"σs = 0,85.fc28/(θ.γb)","isCorrect":false}]'::jsonb, 'A', 'À l''ELU, dans le domaine des pivots A et B (palier plastique), la contrainte de calcul de l''acier vaut fe/γs (γs=1,15 en combinaison fondamentale).', 6);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q7', 'concours-sujet-8', 'Dans la relation f_t28 = 0,6 + 0,06.f_c28, l''unité considérée est le', '[{"id":"A","text":"Pa","isCorrect":false},{"id":"B","text":"N/mm","isCorrect":false},{"id":"C","text":"bar","isCorrect":false},{"id":"D","text":"MPa","isCorrect":true}]'::jsonb, 'D', 'La résistance caractéristique à la traction f_t28, comme f_c28, est exprimée en MPa dans le BAEL91.', 7);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q8', 'concours-sujet-8', 'Le coefficient γb pour les combinaisons accidentelles vaut', '[{"id":"A","text":"1,35","isCorrect":false},{"id":"B","text":"1,5","isCorrect":false},{"id":"C","text":"1","isCorrect":false},{"id":"D","text":"1,15","isCorrect":true}]'::jsonb, 'D', 'BAEL91 : γb = 1,5 pour les combinaisons fondamentales, γb = 1,15 pour les combinaisons accidentelles.', 8);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q9', 'concours-sujet-8', 'Un béton a une résistance en compression f_c28 = 35 MPa. Quelle est sa résistance en traction f_t28 (formule f_t28 = 0,6+0,06.f_c28) ?', '[{"id":"A","text":"21.6 MPa","isCorrect":false},{"id":"B","text":"3.2 MPa","isCorrect":false},{"id":"C","text":"2.7 MPa","isCorrect":true},{"id":"D","text":"2.1 MPa","isCorrect":false}]'::jsonb, 'C', 'f_t28 = 0,6 + 0,06 × 35 = 2.7 MPa.', 9);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q10', 'concours-sujet-8', 'On applique sur une éprouvette de béton de diamètre d=11 cm un effort de compression de 1000 N. Quelle est la valeur de la contrainte de compression (σ=F/S, S=π.d²/4) ?', '[{"id":"A","text":"105 226 Pa","isCorrect":true},{"id":"B","text":"91 547 Pa","isCorrect":false},{"id":"C","text":"121 010 Pa","isCorrect":false},{"id":"D","text":"73 658 Pa","isCorrect":false}]'::jsonb, 'A', 'S = π × (0,11)²/4 = 0.009503 m². σ = F/S = 1000/0.009503 = 105 226 Pa (arrondi).', 10);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q11', 'concours-sujet-8', 'Soit une poutre isostatique AB, reposant sur des appuis simples en A et B distants de L, supportant une charge concentrée P située à la distance a de l''appui A et b de l''appui B (a+b=L). L''expression de RB est :', '[{"id":"A","text":"R_B = P.a/L","isCorrect":true},{"id":"B","text":"R_B = P.b²/L","isCorrect":false},{"id":"C","text":"R_B = P(1-b/L)","isCorrect":false},{"id":"D","text":"R_B = P.b/L","isCorrect":false}]'::jsonb, 'A', 'Équilibre des moments : ΣM/A=0 → R_B × L = P × a → R_B=P.a/L. De même R_A=P.b/L (R_A+R_B=P).', 11);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q12', 'concours-sujet-8', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour un appui simple de poutre ?', '[{"id":"A","text":"4","isCorrect":false},{"id":"B","text":"2","isCorrect":false},{"id":"C","text":"3","isCorrect":false},{"id":"D","text":"1","isCorrect":true}]'::jsonb, 'D', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 12);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q13', 'concours-sujet-8', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour une articulation de poutre ?', '[{"id":"A","text":"4","isCorrect":false},{"id":"B","text":"2","isCorrect":true},{"id":"C","text":"3","isCorrect":false},{"id":"D","text":"1","isCorrect":false}]'::jsonb, 'B', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 13);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q14', 'concours-sujet-8', 'Les blocs creux (éléments de remplissage) des planchers à corps creux sont appelés', '[{"id":"A","text":"Nervures","isCorrect":false},{"id":"B","text":"Agglomérés","isCorrect":false},{"id":"C","text":"Poutrelles","isCorrect":false},{"id":"D","text":"Hourdis (ou entrevous)","isCorrect":true}]'::jsonb, 'D', 'Les éléments de remplissage/coffrage perdu d''un plancher à corps creux sont appelés hourdis, ou entrevous.', 14);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q15', 'concours-sujet-8', 'La dalle de béton coulée sur les hourdis d''un plancher à corps creux est appelée', '[{"id":"A","text":"Dallage","isCorrect":false},{"id":"B","text":"Dalle de compression (ou table de compression)","isCorrect":true},{"id":"C","text":"Radier","isCorrect":false},{"id":"D","text":"Semelle filante","isCorrect":false}]'::jsonb, 'B', 'La fine dalle armée (souvent 4 à 5 cm) coulée au-dessus des hourdis/nervures est la dalle (ou table) de compression.', 15);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q16', 'concours-sujet-8', 'La semelle de fondation située sous un mur (fondation continue) est appelée', '[{"id":"A","text":"Radier","isCorrect":false},{"id":"B","text":"Semelle filante","isCorrect":true},{"id":"C","text":"Semelle isolée","isCorrect":false},{"id":"D","text":"Semelle sur pieux","isCorrect":false}]'::jsonb, 'B', 'Une semelle continue sous un mur porteur est une semelle filante, par opposition à une semelle isolée sous un poteau.', 16);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q17', 'concours-sujet-8', 'Une dalle rectangulaire appuyée sur ses quatre côtés, avec lx/ly > 0,4 (lx = plus petite portée), porte suivant', '[{"id":"A","text":"Quatre sens","isCorrect":false},{"id":"B","text":"Aucun sens (dalle non porteuse)","isCorrect":false},{"id":"C","text":"Deux sens","isCorrect":true},{"id":"D","text":"Un sens","isCorrect":false}]'::jsonb, 'C', 'Règle courante (BAEL/annexe E) : si lx/ly > 0,4, la dalle porte dans les deux sens (flexion bidirectionnelle) ; en dessous, on la calcule comme portant dans un seul sens.', 17);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q18', 'concours-sujet-8', 'Une dalle située au niveau d''un étage (et non au rez-de-chaussée sur terre-plein) est appelée', '[{"id":"A","text":"Plancher","isCorrect":true},{"id":"B","text":"Dalle sur vide sanitaire","isCorrect":false},{"id":"C","text":"Radier","isCorrect":false},{"id":"D","text":"Dallage","isCorrect":false}]'::jsonb, 'A', 'Par convention, on réserve le terme « plancher » à une dalle d''étage (porteuse, en élévation), et « dallage »/« dalle sur terre-plein » à une dalle basse posée sur le sol.', 18);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q19', 'concours-sujet-8', 'L''altitude relative d''un point est', '[{"id":"A","text":"La position (en hauteur) du point par rapport à un point de référence fixe, choisi arbitrairement pour le chantier","isCorrect":true},{"id":"B","text":"Une notion qui n''existe pas en topographie","isCorrect":false},{"id":"C","text":"La position du point par rapport au géoïde","isCorrect":false},{"id":"D","text":"La position du point par rapport au niveau de la mer","isCorrect":false}]'::jsonb, 'A', 'Contrairement à l''altitude absolue (repérée au niveau de la mer/géoïde, IGN par exemple), l''altitude relative se mesure par rapport à un repère local arbitraire (souvent une borne ou un point fixe du chantier).', 19);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q20', 'concours-sujet-8', 'La visée avant, en nivellement, est', '[{"id":"A","text":"La visée faite sur le point d''altitude connue","isCorrect":false},{"id":"B","text":"La visée faite sur le point dont on cherche à déterminer l''altitude (point inconnu)","isCorrect":true},{"id":"C","text":"La visée faite sur le premier point observé","isCorrect":false},{"id":"D","text":"La visée faite dans le sens du parcours uniquement","isCorrect":false}]'::jsonb, 'B', 'Par convention : la visée arrière se fait sur un point d''altitude CONNUE (ou de référence), la visée avant sur le point dont on veut DÉTERMINER l''altitude.', 20);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q21', 'concours-sujet-8', 'La visée entre deux points A et B a donné les résultats suivants : visée arrière 1200 mm ; visée avant 1850 mm. Quelle est la valeur de la dénivelée entre les deux points ?', '[{"id":"A","text":"-650 mm","isCorrect":true},{"id":"B","text":"-3050 mm","isCorrect":false},{"id":"C","text":"650 mm","isCorrect":false},{"id":"D","text":"3050 mm","isCorrect":false}]'::jsonb, 'A', 'Dénivelée = Visée arrière − Visée avant = 1200 − 1850 = -650 mm.', 21);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q22', 'concours-sujet-8', 'La mesure directe des distances peut se faire :', '[{"id":"A","text":"À l''aide du cercle optique","isCorrect":false},{"id":"B","text":"À l''aide d''un théodolite","isCorrect":false},{"id":"C","text":"À l''aide d''une mire seule","isCorrect":false},{"id":"D","text":"Au ruban (ou au décamètre/chaîne d''arpenteur)","isCorrect":true}]'::jsonb, 'D', 'Une mesure DIRECTE consiste à appliquer physiquement un instrument gradué (ruban, décamètre) le long de la distance à mesurer. Le théodolite et la mire, eux, servent à des mesures INDIRECTES (angles, nivellement optique).', 22);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q23', 'concours-sujet-8', 'À quoi sert l''armature dans le béton armé ?', '[{"id":"A","text":"Empêcher le béton de rompre au flambement","isCorrect":false},{"id":"B","text":"Augmenter la résistance du béton en compression","isCorrect":false},{"id":"C","text":"Reprendre les efforts de compression du béton","isCorrect":false},{"id":"D","text":"Reprendre les efforts de traction du béton","isCorrect":true}]'::jsonb, 'D', 'Le béton résiste bien en compression mais très mal en traction : l''acier, qui résiste bien en traction, est associé au béton pour reprendre ces efforts (principe fondateur du béton armé).', 23);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q24', 'concours-sujet-8', 'Le système qui sépare la collecte des eaux usées/vannes et celle des eaux pluviales, dans deux réseaux distincts, est appelé', '[{"id":"A","text":"Le système séparatif","isCorrect":true},{"id":"B","text":"Le système mixte","isCorrect":false},{"id":"C","text":"Le système combiné","isCorrect":false},{"id":"D","text":"Le système unitaire","isCorrect":false}]'::jsonb, 'A', 'Le système séparatif utilise 2 réseaux distincts (eaux usées/vannes d''un côté, eaux pluviales de l''autre) ; le système unitaire les collecte ensemble dans un seul réseau.', 24);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q25', 'concours-sujet-8', 'Le traitement des eaux usées permet avant tout de', '[{"id":"A","text":"N''a aucune utilité réelle","isCorrect":false},{"id":"B","text":"Protéger l''environnement (et la santé publique) en évitant le rejet de pollution dans le milieu naturel","isCorrect":true},{"id":"C","text":"Polluer volontairement les cultures en aval","isCorrect":false},{"id":"D","text":"Uniquement embellir le paysage","isCorrect":false}]'::jsonb, 'B', 'Le traitement des eaux usées vise à réduire la charge polluante avant rejet dans le milieu naturel, protégeant ainsi l''environnement et la santé publique.', 25);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q26', 'concours-sujet-8', 'À quoi sert la vibration du béton lors de sa mise en œuvre ?', '[{"id":"A","text":"Augmenter la résistance mécanique finale du béton au-delà de sa formulation","isCorrect":false},{"id":"B","text":"Augmenter la résistance du béton au feu","isCorrect":false},{"id":"C","text":"Empêcher la ségrégation des granulats et chasser les bulles d''air (nids de cailloux)","isCorrect":true},{"id":"D","text":"Accélérer la prise du ciment","isCorrect":false}]'::jsonb, 'C', 'La vibration remplit correctement le coffrage, chasse l''air emprisonné et évite la ségrégation (séparation gravier/mortier), améliorant la compacité réelle du béton en place.', 26);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q27', 'concours-sujet-8', 'À quoi servent les dévers sur une chaussée ?', '[{"id":"A","text":"Uniquement améliorer l''esthétique de la route","isCorrect":false},{"id":"B","text":"Faciliter l''évacuation des eaux de ruissellement (et améliorer la tenue des véhicules en courbe)","isCorrect":true},{"id":"C","text":"Réduire la largeur utile de la chaussée","isCorrect":false},{"id":"D","text":"Augmenter la vitesse autorisée des véhicules","isCorrect":false}]'::jsonb, 'B', 'Le dévers (pente transversale) évacue l''eau de pluie vers les côtés de la chaussée et, en courbe, contribue à compenser la force centrifuge subie par les véhicules.', 27);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q28', 'concours-sujet-8', 'Une largeur de voie de circulation courante retenue en dimensionnement routier est de l''ordre de 3,50 m ; pour une route à deux voies, cela correspond à une largeur de chaussée de l''ordre de', '[{"id":"A","text":"6,5 mètres","isCorrect":false},{"id":"B","text":"10 mètres","isCorrect":false},{"id":"C","text":"7 mètres","isCorrect":true},{"id":"D","text":"8 mètres","isCorrect":false}]'::jsonb, 'C', 'Avec une largeur de voie usuelle d''environ 3,50 m, une chaussée à 2 voies (une par sens) totalise généralement une largeur de l''ordre de 7 m (valeur de référence à adapter selon la norme/le référentiel routier retenu localement).', 28);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q29', 'concours-sujet-8', 'Les dos d''âne (ralentisseurs) permettent de', '[{"id":"A","text":"Stopper complètement la circulation des véhicules","isCorrect":false},{"id":"B","text":"Ralentir les véhicules (dispositif de modération de la vitesse)","isCorrect":true},{"id":"C","text":"Protéger uniquement la chaussée de l''usure","isCorrect":false},{"id":"D","text":"Augmenter le nombre de véhicules pouvant circuler","isCorrect":false}]'::jsonb, 'B', 'Un dos d''âne est un dispositif de sécurité routière conçu pour contraindre les conducteurs à réduire leur vitesse, notamment en zone sensible (écoles, agglomérations).', 29);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s8-q30', 'concours-sujet-8', 'Un béton subit un retrait de 2%. Qu''appelle-t-on retrait ?', '[{"id":"A","text":"Le gonflement du béton en présence d''humidité","isCorrect":false},{"id":"B","text":"La diminution de la résistance du béton","isCorrect":false},{"id":"C","text":"L''augmentation du volume du béton","isCorrect":false},{"id":"D","text":"La diminution du volume du béton suite à l''évaporation de l''eau (et aux réactions internes)","isCorrect":true}]'::jsonb, 'D', 'Le retrait est une contraction (diminution de volume/longueur) du béton, principalement liée au départ d''eau (séchage) et aux réactions d''hydratation, distincte d''une perte de résistance.', 30);
insert into public.qcm_subjects (id, title, description, "order") values ('concours-sujet-9', 'Sujet 9 — Concours d''entrée BTP', '30 questions', 10);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q1', 'concours-sujet-9', 'Dans la relation f_bu = 0,85.f_c28 / (θ.γb), avec une durée d''application de la combinaison d''action considérée t = 48 h,', '[{"id":"A","text":"θ = 0,9","isCorrect":false},{"id":"B","text":"θ = 1","isCorrect":true},{"id":"C","text":"θ = 0,85","isCorrect":false},{"id":"D","text":"θ = 1,15","isCorrect":false}]'::jsonb, 'B', 'BAEL91 (A.4.3,41) : θ=1 si t>24h ; θ=0,9 si 1h<t≤24h ; θ=0,85 si t<1h. Ici t=48h, donc θ=1.', 1);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q2', 'concours-sujet-9', 'Le coefficient de fissuration η pour une armature Haute Adhérence de diamètre φ=25mm est', '[{"id":"A","text":"η = 1,6","isCorrect":true},{"id":"B","text":"η = 1,3","isCorrect":false},{"id":"C","text":"η = 1","isCorrect":false},{"id":"D","text":"η = 2","isCorrect":false}]'::jsonb, 'A', 'BAEL91 (A.4.5,3) : η=1 pour les ronds lisses (RL) ; η=1,6 pour les armatures Haute Adhérence (HA).', 2);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q3', 'concours-sujet-9', 'Le retrait du béton Δl/l en climat chaud et sec vaut, à défaut de mesures (BAEL91) :', '[{"id":"A","text":"3 × 10⁻⁴","isCorrect":false},{"id":"B","text":"2 × 10⁻⁴","isCorrect":false},{"id":"C","text":"1,5 × 10⁻⁴","isCorrect":false},{"id":"D","text":"4 × 10⁻⁴","isCorrect":true}]'::jsonb, 'D', 'BAEL91 : retrait forfaitaire = 1,5×10⁻⁴ (très humide), 2×10⁻⁴ (humide), 3×10⁻⁴ (tempéré sec), 4×10⁻⁴ (chaud et sec), 5×10⁻⁴ (très sec/désertique).', 3);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q4', 'concours-sujet-9', 'La section entièrement comprimée (compression simple ou composée, faible excentricité) correspond au', '[{"id":"A","text":"Pivot A","isCorrect":false},{"id":"B","text":"Aucune","isCorrect":false},{"id":"C","text":"Pivot C","isCorrect":true},{"id":"D","text":"Pivot B","isCorrect":false}]'::jsonb, 'C', 'BAEL91 (A.4.3,3), règle des 3 pivots : Pivot A → allongement acier 10‰ ; Pivot B → raccourcissement béton 3,5‰ ; Pivot C → section entièrement comprimée.', 4);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q5', 'concours-sujet-9', 'En fissuration très préjudiciable, la contrainte limite de traction des aciers est :', '[{"id":"A","text":"σs ≤ min{(2/3)fe ; max[0,5fe;110√(η.ftj)]}","isCorrect":false},{"id":"B","text":"σs ≤ 0,8fe","isCorrect":false},{"id":"C","text":"σs = fe/γs sans autre condition","isCorrect":false},{"id":"D","text":"σs ≤ min[0,5fe ; 90√(η.ftj)]","isCorrect":true}]'::jsonb, 'D', 'BAEL91 (A.4.5,3) : peu préjudiciable → pas de limite spécifique (σs=fe/γs) ; préjudiciable → min{2/3fe ; max[0,5fe;110√(η.ftj)]} ; très préjudiciable → min[0,5fe ; 90√(η.ftj)].', 5);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q6', 'concours-sujet-9', 'À l''ELU, la contrainte de dimensionnement (calcul) de l''acier est', '[{"id":"A","text":"σs = fe/γs","isCorrect":true},{"id":"B","text":"σs = 0,85.fc28/(θ.γb)","isCorrect":false},{"id":"C","text":"σs = 0,6.fc28","isCorrect":false},{"id":"D","text":"σs = 0,8.fe","isCorrect":false}]'::jsonb, 'A', 'À l''ELU, dans le domaine des pivots A et B (palier plastique), la contrainte de calcul de l''acier vaut fe/γs (γs=1,15 en combinaison fondamentale).', 6);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q7', 'concours-sujet-9', 'Dans la relation f_bu = 0,85.f_c28/(θ.γb), l''unité considérée pour f_bu est le', '[{"id":"A","text":"Pa (pascal)","isCorrect":false},{"id":"B","text":"MPa (mégapascal)","isCorrect":true},{"id":"C","text":"bar","isCorrect":false},{"id":"D","text":"kg/cm²","isCorrect":false}]'::jsonb, 'B', 'f_bu (contrainte de calcul du béton à l''ELU) et f_c28 s''expriment en MPa dans les formules du BAEL91.', 7);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q8', 'concours-sujet-9', 'Le coefficient γb pour les combinaisons fondamentales vaut', '[{"id":"A","text":"1","isCorrect":false},{"id":"B","text":"1,35","isCorrect":false},{"id":"C","text":"1,5","isCorrect":true},{"id":"D","text":"1,15","isCorrect":false}]'::jsonb, 'C', 'BAEL91 : γb = 1,5 pour les combinaisons fondamentales, γb = 1,15 pour les combinaisons accidentelles.', 8);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q9', 'concours-sujet-9', 'Un béton a une résistance en compression f_c28 = 18 MPa. Quelle est sa résistance en traction f_t28 (formule f_t28 = 0,6+0,06.f_c28) ?', '[{"id":"A","text":"1.68 MPa","isCorrect":true},{"id":"B","text":"1.08 MPa","isCorrect":false},{"id":"C","text":"11.4 MPa","isCorrect":false},{"id":"D","text":"2.18 MPa","isCorrect":false}]'::jsonb, 'A', 'f_t28 = 0,6 + 0,06 × 18 = 1.68 MPa.', 9);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q10', 'concours-sujet-9', 'On applique sur une éprouvette de béton de diamètre d=14 cm un effort de compression de 1300 N. Quelle est la valeur de la contrainte de compression (σ=F/S, S=π.d²/4) ?', '[{"id":"A","text":"97 117 Pa","isCorrect":false},{"id":"B","text":"73 471 Pa","isCorrect":false},{"id":"C","text":"59 115 Pa","isCorrect":false},{"id":"D","text":"84 450 Pa","isCorrect":true}]'::jsonb, 'D', 'S = π × (0,14)²/4 = 0.015394 m². σ = F/S = 1300/0.015394 = 84 450 Pa (arrondi).', 10);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q11', 'concours-sujet-9', 'Soit une poutre isostatique AB, reposant sur des appuis simples en A et B distants de L, supportant une charge concentrée P située à la distance a de l''appui A et b de l''appui B (a+b=L). L''expression de RA est :', '[{"id":"A","text":"R_A = P.a²/L","isCorrect":false},{"id":"B","text":"R_A = P.b/L","isCorrect":true},{"id":"C","text":"R_A = P.a/L","isCorrect":false},{"id":"D","text":"R_A = P(1-a/L)","isCorrect":false}]'::jsonb, 'B', 'Équilibre des moments : ΣM/B=0 → R_A × L = P × b → R_A=P.b/L. De même R_B=P.a/L (R_A+R_B=P).', 11);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q12', 'concours-sujet-9', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour un appui simple de poutre ?', '[{"id":"A","text":"2","isCorrect":false},{"id":"B","text":"3","isCorrect":false},{"id":"C","text":"4","isCorrect":false},{"id":"D","text":"1","isCorrect":true}]'::jsonb, 'D', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 12);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q13', 'concours-sujet-9', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour une articulation de poutre ?', '[{"id":"A","text":"4","isCorrect":false},{"id":"B","text":"2","isCorrect":true},{"id":"C","text":"3","isCorrect":false},{"id":"D","text":"1","isCorrect":false}]'::jsonb, 'B', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 13);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q14', 'concours-sujet-9', 'Les blocs creux (éléments de remplissage) des planchers à corps creux sont appelés', '[{"id":"A","text":"Agglomérés","isCorrect":false},{"id":"B","text":"Poutrelles","isCorrect":false},{"id":"C","text":"Hourdis (ou entrevous)","isCorrect":true},{"id":"D","text":"Nervures","isCorrect":false}]'::jsonb, 'C', 'Les éléments de remplissage/coffrage perdu d''un plancher à corps creux sont appelés hourdis, ou entrevous.', 14);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q15', 'concours-sujet-9', 'La dalle de béton coulée sur les hourdis d''un plancher à corps creux est appelée', '[{"id":"A","text":"Dallage","isCorrect":false},{"id":"B","text":"Radier","isCorrect":false},{"id":"C","text":"Semelle filante","isCorrect":false},{"id":"D","text":"Dalle de compression (ou table de compression)","isCorrect":true}]'::jsonb, 'D', 'La fine dalle armée (souvent 4 à 5 cm) coulée au-dessus des hourdis/nervures est la dalle (ou table) de compression.', 15);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q16', 'concours-sujet-9', 'La semelle de fondation située sous un mur (fondation continue) est appelée', '[{"id":"A","text":"Radier","isCorrect":false},{"id":"B","text":"Semelle isolée","isCorrect":false},{"id":"C","text":"Semelle sur pieux","isCorrect":false},{"id":"D","text":"Semelle filante","isCorrect":true}]'::jsonb, 'D', 'Une semelle continue sous un mur porteur est une semelle filante, par opposition à une semelle isolée sous un poteau.', 16);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q17', 'concours-sujet-9', 'Une dalle rectangulaire appuyée sur ses quatre côtés, avec lx/ly > 0,4 (lx = plus petite portée), porte suivant', '[{"id":"A","text":"Deux sens","isCorrect":true},{"id":"B","text":"Aucun sens (dalle non porteuse)","isCorrect":false},{"id":"C","text":"Quatre sens","isCorrect":false},{"id":"D","text":"Un sens","isCorrect":false}]'::jsonb, 'A', 'Règle courante (BAEL/annexe E) : si lx/ly > 0,4, la dalle porte dans les deux sens (flexion bidirectionnelle) ; en dessous, on la calcule comme portant dans un seul sens.', 17);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q18', 'concours-sujet-9', 'Une dalle située au niveau d''un étage (et non au rez-de-chaussée sur terre-plein) est appelée', '[{"id":"A","text":"Radier","isCorrect":false},{"id":"B","text":"Plancher","isCorrect":true},{"id":"C","text":"Dalle sur vide sanitaire","isCorrect":false},{"id":"D","text":"Dallage","isCorrect":false}]'::jsonb, 'B', 'Par convention, on réserve le terme « plancher » à une dalle d''étage (porteuse, en élévation), et « dallage »/« dalle sur terre-plein » à une dalle basse posée sur le sol.', 18);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q19', 'concours-sujet-9', 'L''altitude relative d''un point est', '[{"id":"A","text":"La position du point par rapport au niveau de la mer","isCorrect":false},{"id":"B","text":"La position du point par rapport au géoïde","isCorrect":false},{"id":"C","text":"Une notion qui n''existe pas en topographie","isCorrect":false},{"id":"D","text":"La position (en hauteur) du point par rapport à un point de référence fixe, choisi arbitrairement pour le chantier","isCorrect":true}]'::jsonb, 'D', 'Contrairement à l''altitude absolue (repérée au niveau de la mer/géoïde, IGN par exemple), l''altitude relative se mesure par rapport à un repère local arbitraire (souvent une borne ou un point fixe du chantier).', 19);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q20', 'concours-sujet-9', 'La visée avant, en nivellement, est', '[{"id":"A","text":"La visée faite sur le point dont on cherche à déterminer l''altitude (point inconnu)","isCorrect":true},{"id":"B","text":"La visée faite sur le premier point observé","isCorrect":false},{"id":"C","text":"La visée faite dans le sens du parcours uniquement","isCorrect":false},{"id":"D","text":"La visée faite sur le point d''altitude connue","isCorrect":false}]'::jsonb, 'A', 'Par convention : la visée arrière se fait sur un point d''altitude CONNUE (ou de référence), la visée avant sur le point dont on veut DÉTERMINER l''altitude.', 20);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q21', 'concours-sujet-9', 'La visée entre deux points A et B a donné les résultats suivants : visée arrière 2400 mm ; visée avant 3130 mm. Quelle est la valeur de la dénivelée entre les deux points ?', '[{"id":"A","text":"-5530 mm","isCorrect":false},{"id":"B","text":"-730 mm","isCorrect":true},{"id":"C","text":"5530 mm","isCorrect":false},{"id":"D","text":"730 mm","isCorrect":false}]'::jsonb, 'B', 'Dénivelée = Visée arrière − Visée avant = 2400 − 3130 = -730 mm.', 21);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q22', 'concours-sujet-9', 'La mesure directe des distances peut se faire :', '[{"id":"A","text":"À l''aide d''une mire seule","isCorrect":false},{"id":"B","text":"À l''aide du cercle optique","isCorrect":false},{"id":"C","text":"À l''aide d''un théodolite","isCorrect":false},{"id":"D","text":"Au ruban (ou au décamètre/chaîne d''arpenteur)","isCorrect":true}]'::jsonb, 'D', 'Une mesure DIRECTE consiste à appliquer physiquement un instrument gradué (ruban, décamètre) le long de la distance à mesurer. Le théodolite et la mire, eux, servent à des mesures INDIRECTES (angles, nivellement optique).', 22);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q23', 'concours-sujet-9', 'À quoi sert l''armature dans le béton armé ?', '[{"id":"A","text":"Reprendre les efforts de traction du béton","isCorrect":true},{"id":"B","text":"Empêcher le béton de rompre au flambement","isCorrect":false},{"id":"C","text":"Augmenter la résistance du béton en compression","isCorrect":false},{"id":"D","text":"Reprendre les efforts de compression du béton","isCorrect":false}]'::jsonb, 'A', 'Le béton résiste bien en compression mais très mal en traction : l''acier, qui résiste bien en traction, est associé au béton pour reprendre ces efforts (principe fondateur du béton armé).', 23);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q24', 'concours-sujet-9', 'Le système qui sépare la collecte des eaux usées/vannes et celle des eaux pluviales, dans deux réseaux distincts, est appelé', '[{"id":"A","text":"Le système mixte","isCorrect":false},{"id":"B","text":"Le système séparatif","isCorrect":true},{"id":"C","text":"Le système combiné","isCorrect":false},{"id":"D","text":"Le système unitaire","isCorrect":false}]'::jsonb, 'B', 'Le système séparatif utilise 2 réseaux distincts (eaux usées/vannes d''un côté, eaux pluviales de l''autre) ; le système unitaire les collecte ensemble dans un seul réseau.', 24);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q25', 'concours-sujet-9', 'Le traitement des eaux usées permet avant tout de', '[{"id":"A","text":"N''a aucune utilité réelle","isCorrect":false},{"id":"B","text":"Uniquement embellir le paysage","isCorrect":false},{"id":"C","text":"Protéger l''environnement (et la santé publique) en évitant le rejet de pollution dans le milieu naturel","isCorrect":true},{"id":"D","text":"Polluer volontairement les cultures en aval","isCorrect":false}]'::jsonb, 'C', 'Le traitement des eaux usées vise à réduire la charge polluante avant rejet dans le milieu naturel, protégeant ainsi l''environnement et la santé publique.', 25);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q26', 'concours-sujet-9', 'À quoi sert la vibration du béton lors de sa mise en œuvre ?', '[{"id":"A","text":"Accélérer la prise du ciment","isCorrect":false},{"id":"B","text":"Augmenter la résistance mécanique finale du béton au-delà de sa formulation","isCorrect":false},{"id":"C","text":"Empêcher la ségrégation des granulats et chasser les bulles d''air (nids de cailloux)","isCorrect":true},{"id":"D","text":"Augmenter la résistance du béton au feu","isCorrect":false}]'::jsonb, 'C', 'La vibration remplit correctement le coffrage, chasse l''air emprisonné et évite la ségrégation (séparation gravier/mortier), améliorant la compacité réelle du béton en place.', 26);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q27', 'concours-sujet-9', 'À quoi servent les dévers sur une chaussée ?', '[{"id":"A","text":"Faciliter l''évacuation des eaux de ruissellement (et améliorer la tenue des véhicules en courbe)","isCorrect":true},{"id":"B","text":"Uniquement améliorer l''esthétique de la route","isCorrect":false},{"id":"C","text":"Réduire la largeur utile de la chaussée","isCorrect":false},{"id":"D","text":"Augmenter la vitesse autorisée des véhicules","isCorrect":false}]'::jsonb, 'A', 'Le dévers (pente transversale) évacue l''eau de pluie vers les côtés de la chaussée et, en courbe, contribue à compenser la force centrifuge subie par les véhicules.', 27);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q28', 'concours-sujet-9', 'Une largeur de voie de circulation courante retenue en dimensionnement routier est de l''ordre de 3,50 m ; pour une route à deux voies, cela correspond à une largeur de chaussée de l''ordre de', '[{"id":"A","text":"8 mètres","isCorrect":false},{"id":"B","text":"6,5 mètres","isCorrect":false},{"id":"C","text":"10 mètres","isCorrect":false},{"id":"D","text":"7 mètres","isCorrect":true}]'::jsonb, 'D', 'Avec une largeur de voie usuelle d''environ 3,50 m, une chaussée à 2 voies (une par sens) totalise généralement une largeur de l''ordre de 7 m (valeur de référence à adapter selon la norme/le référentiel routier retenu localement).', 28);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q29', 'concours-sujet-9', 'Les dos d''âne (ralentisseurs) permettent de', '[{"id":"A","text":"Augmenter le nombre de véhicules pouvant circuler","isCorrect":false},{"id":"B","text":"Ralentir les véhicules (dispositif de modération de la vitesse)","isCorrect":true},{"id":"C","text":"Stopper complètement la circulation des véhicules","isCorrect":false},{"id":"D","text":"Protéger uniquement la chaussée de l''usure","isCorrect":false}]'::jsonb, 'B', 'Un dos d''âne est un dispositif de sécurité routière conçu pour contraindre les conducteurs à réduire leur vitesse, notamment en zone sensible (écoles, agglomérations).', 29);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s9-q30', 'concours-sujet-9', 'Un béton subit un retrait de 2%. Qu''appelle-t-on retrait ?', '[{"id":"A","text":"L''augmentation du volume du béton","isCorrect":false},{"id":"B","text":"La diminution de la résistance du béton","isCorrect":false},{"id":"C","text":"La diminution du volume du béton suite à l''évaporation de l''eau (et aux réactions internes)","isCorrect":true},{"id":"D","text":"Le gonflement du béton en présence d''humidité","isCorrect":false}]'::jsonb, 'C', 'Le retrait est une contraction (diminution de volume/longueur) du béton, principalement liée au départ d''eau (séchage) et aux réactions d''hydratation, distincte d''une perte de résistance.', 30);
insert into public.qcm_subjects (id, title, description, "order") values ('concours-sujet-10', 'Sujet 10 — Concours d''entrée BTP', '30 questions', 11);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q1', 'concours-sujet-10', 'Dans la relation f_bu = 0,85.f_c28 / (θ.γb), avec une durée d''application de la combinaison d''action considérée t = 72 h,', '[{"id":"A","text":"θ = 1","isCorrect":true},{"id":"B","text":"θ = 0,9","isCorrect":false},{"id":"C","text":"θ = 0,85","isCorrect":false},{"id":"D","text":"θ = 1,15","isCorrect":false}]'::jsonb, 'A', 'BAEL91 (A.4.3,41) : θ=1 si t>24h ; θ=0,9 si 1h<t≤24h ; θ=0,85 si t<1h. Ici t=72h, donc θ=1.', 1);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q2', 'concours-sujet-10', 'Le coefficient de fissuration η pour une armature Haute Adhérence de diamètre φ=6mm est', '[{"id":"A","text":"η = 1,3","isCorrect":false},{"id":"B","text":"η = 2","isCorrect":false},{"id":"C","text":"η = 1,6","isCorrect":true},{"id":"D","text":"η = 1","isCorrect":false}]'::jsonb, 'C', 'BAEL91 (A.4.5,3) : η=1 pour les ronds lisses (RL) ; η=1,6 pour les armatures Haute Adhérence (HA).', 2);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q3', 'concours-sujet-10', 'Le retrait du béton Δl/l en climat très sec ou désertique vaut, à défaut de mesures (BAEL91) :', '[{"id":"A","text":"2 × 10⁻⁴","isCorrect":false},{"id":"B","text":"1,5 × 10⁻⁴","isCorrect":false},{"id":"C","text":"3 × 10⁻⁴","isCorrect":false},{"id":"D","text":"5 × 10⁻⁴","isCorrect":true}]'::jsonb, 'D', 'BAEL91 : retrait forfaitaire = 1,5×10⁻⁴ (très humide), 2×10⁻⁴ (humide), 3×10⁻⁴ (tempéré sec), 4×10⁻⁴ (chaud et sec), 5×10⁻⁴ (très sec/désertique).', 3);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q4', 'concours-sujet-10', 'L''allongement de l''armature la plus tendue εs=10×10⁻³ (pivot correspondant) se trouve', '[{"id":"A","text":"Pivot C","isCorrect":false},{"id":"B","text":"Pivot A","isCorrect":true},{"id":"C","text":"Aucune","isCorrect":false},{"id":"D","text":"Pivot B","isCorrect":false}]'::jsonb, 'B', 'BAEL91 (A.4.3,3), règle des 3 pivots : Pivot A → allongement acier 10‰ ; Pivot B → raccourcissement béton 3,5‰ ; Pivot C → section entièrement comprimée.', 4);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q5', 'concours-sujet-10', 'En fissuration peu préjudiciable, la contrainte limite de traction des aciers est :', '[{"id":"A","text":"σs ≤ min(0,5fe ; 110√(η.ftj))","isCorrect":false},{"id":"B","text":"σs = fe/γs (aucune limitation supplémentaire liée à la fissuration)","isCorrect":true},{"id":"C","text":"σs ≤ min(0,5fe ; 90√(η.ftj))","isCorrect":false},{"id":"D","text":"σs ≤ (2/3)fe","isCorrect":false}]'::jsonb, 'B', 'BAEL91 (A.4.5,3) : peu préjudiciable → pas de limite spécifique (σs=fe/γs) ; préjudiciable → min{2/3fe ; max[0,5fe;110√(η.ftj)]} ; très préjudiciable → min[0,5fe ; 90√(η.ftj)].', 5);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q6', 'concours-sujet-10', 'À l''ELU, la contrainte de dimensionnement (calcul) de l''acier est', '[{"id":"A","text":"σs = 0,8.fe","isCorrect":false},{"id":"B","text":"σs = fe/γs","isCorrect":true},{"id":"C","text":"σs = 0,6.fc28","isCorrect":false},{"id":"D","text":"σs = 0,85.fc28/(θ.γb)","isCorrect":false}]'::jsonb, 'B', 'À l''ELU, dans le domaine des pivots A et B (palier plastique), la contrainte de calcul de l''acier vaut fe/γs (γs=1,15 en combinaison fondamentale).', 6);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q7', 'concours-sujet-10', 'Dans la relation f_t28 = 0,6 + 0,06.f_c28, l''unité considérée est le', '[{"id":"A","text":"bar","isCorrect":false},{"id":"B","text":"MPa","isCorrect":true},{"id":"C","text":"Pa","isCorrect":false},{"id":"D","text":"N/mm","isCorrect":false}]'::jsonb, 'B', 'La résistance caractéristique à la traction f_t28, comme f_c28, est exprimée en MPa dans le BAEL91.', 7);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q8', 'concours-sujet-10', 'Le coefficient γb pour les combinaisons accidentelles vaut', '[{"id":"A","text":"1,15","isCorrect":true},{"id":"B","text":"1","isCorrect":false},{"id":"C","text":"1,35","isCorrect":false},{"id":"D","text":"1,5","isCorrect":false}]'::jsonb, 'A', 'BAEL91 : γb = 1,5 pour les combinaisons fondamentales, γb = 1,15 pour les combinaisons accidentelles.', 8);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q9', 'concours-sujet-10', 'Un béton a une résistance en compression f_c28 = 24 MPa. Quelle est sa résistance en traction f_t28 (formule f_t28 = 0,6+0,06.f_c28) ?', '[{"id":"A","text":"1.44 MPa","isCorrect":false},{"id":"B","text":"2.54 MPa","isCorrect":false},{"id":"C","text":"15.0 MPa","isCorrect":false},{"id":"D","text":"2.04 MPa","isCorrect":true}]'::jsonb, 'D', 'f_t28 = 0,6 + 0,06 × 24 = 2.04 MPa.', 9);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q10', 'concours-sujet-10', 'On applique sur une éprouvette de béton de diamètre d=16 cm un effort de compression de 2200 N. Quelle est la valeur de la contrainte de compression (σ=F/S, S=π.d²/4) ?', '[{"id":"A","text":"95 195 Pa","isCorrect":false},{"id":"B","text":"125 832 Pa","isCorrect":false},{"id":"C","text":"109 419 Pa","isCorrect":true},{"id":"D","text":"76 593 Pa","isCorrect":false}]'::jsonb, 'C', 'S = π × (0,16)²/4 = 0.020106 m². σ = F/S = 2200/0.020106 = 109 419 Pa (arrondi).', 10);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q11', 'concours-sujet-10', 'Soit une poutre isostatique AB, reposant sur des appuis simples en A et B distants de L, supportant une charge concentrée P située à la distance a de l''appui A et b de l''appui B (a+b=L). L''expression de RB est :', '[{"id":"A","text":"R_B = P.b/L","isCorrect":false},{"id":"B","text":"R_B = P(1-b/L)","isCorrect":false},{"id":"C","text":"R_B = P.b²/L","isCorrect":false},{"id":"D","text":"R_B = P.a/L","isCorrect":true}]'::jsonb, 'D', 'Équilibre des moments : ΣM/A=0 → R_B × L = P × a → R_B=P.a/L. De même R_A=P.b/L (R_A+R_B=P).', 11);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q12', 'concours-sujet-10', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour un appui simple de poutre ?', '[{"id":"A","text":"2","isCorrect":false},{"id":"B","text":"3","isCorrect":false},{"id":"C","text":"1","isCorrect":true},{"id":"D","text":"4","isCorrect":false}]'::jsonb, 'C', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 12);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q13', 'concours-sujet-10', 'Quel est le nombre d''inconnue(s) de réaction d''appui pour une articulation de poutre ?', '[{"id":"A","text":"2","isCorrect":true},{"id":"B","text":"3","isCorrect":false},{"id":"C","text":"4","isCorrect":false},{"id":"D","text":"1","isCorrect":false}]'::jsonb, 'A', 'En RDM plane : appui simple → 1 inconnue (réaction normale) ; articulation → 2 inconnues (2 composantes de réaction) ; encastrement → 3 inconnues (2 réactions + 1 moment).', 13);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q14', 'concours-sujet-10', 'Les blocs creux (éléments de remplissage) des planchers à corps creux sont appelés', '[{"id":"A","text":"Agglomérés","isCorrect":false},{"id":"B","text":"Hourdis (ou entrevous)","isCorrect":true},{"id":"C","text":"Nervures","isCorrect":false},{"id":"D","text":"Poutrelles","isCorrect":false}]'::jsonb, 'B', 'Les éléments de remplissage/coffrage perdu d''un plancher à corps creux sont appelés hourdis, ou entrevous.', 14);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q15', 'concours-sujet-10', 'La dalle de béton coulée sur les hourdis d''un plancher à corps creux est appelée', '[{"id":"A","text":"Radier","isCorrect":false},{"id":"B","text":"Dallage","isCorrect":false},{"id":"C","text":"Semelle filante","isCorrect":false},{"id":"D","text":"Dalle de compression (ou table de compression)","isCorrect":true}]'::jsonb, 'D', 'La fine dalle armée (souvent 4 à 5 cm) coulée au-dessus des hourdis/nervures est la dalle (ou table) de compression.', 15);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q16', 'concours-sujet-10', 'La semelle de fondation située sous un mur (fondation continue) est appelée', '[{"id":"A","text":"Semelle sur pieux","isCorrect":false},{"id":"B","text":"Radier","isCorrect":false},{"id":"C","text":"Semelle filante","isCorrect":true},{"id":"D","text":"Semelle isolée","isCorrect":false}]'::jsonb, 'C', 'Une semelle continue sous un mur porteur est une semelle filante, par opposition à une semelle isolée sous un poteau.', 16);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q17', 'concours-sujet-10', 'Une dalle rectangulaire appuyée sur ses quatre côtés, avec lx/ly > 0,4 (lx = plus petite portée), porte suivant', '[{"id":"A","text":"Aucun sens (dalle non porteuse)","isCorrect":false},{"id":"B","text":"Quatre sens","isCorrect":false},{"id":"C","text":"Un sens","isCorrect":false},{"id":"D","text":"Deux sens","isCorrect":true}]'::jsonb, 'D', 'Règle courante (BAEL/annexe E) : si lx/ly > 0,4, la dalle porte dans les deux sens (flexion bidirectionnelle) ; en dessous, on la calcule comme portant dans un seul sens.', 17);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q18', 'concours-sujet-10', 'Une dalle située au niveau d''un étage (et non au rez-de-chaussée sur terre-plein) est appelée', '[{"id":"A","text":"Plancher","isCorrect":true},{"id":"B","text":"Dallage","isCorrect":false},{"id":"C","text":"Radier","isCorrect":false},{"id":"D","text":"Dalle sur vide sanitaire","isCorrect":false}]'::jsonb, 'A', 'Par convention, on réserve le terme « plancher » à une dalle d''étage (porteuse, en élévation), et « dallage »/« dalle sur terre-plein » à une dalle basse posée sur le sol.', 18);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q19', 'concours-sujet-10', 'L''altitude relative d''un point est', '[{"id":"A","text":"Une notion qui n''existe pas en topographie","isCorrect":false},{"id":"B","text":"La position du point par rapport au niveau de la mer","isCorrect":false},{"id":"C","text":"La position (en hauteur) du point par rapport à un point de référence fixe, choisi arbitrairement pour le chantier","isCorrect":true},{"id":"D","text":"La position du point par rapport au géoïde","isCorrect":false}]'::jsonb, 'C', 'Contrairement à l''altitude absolue (repérée au niveau de la mer/géoïde, IGN par exemple), l''altitude relative se mesure par rapport à un repère local arbitraire (souvent une borne ou un point fixe du chantier).', 19);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q20', 'concours-sujet-10', 'La visée avant, en nivellement, est', '[{"id":"A","text":"La visée faite sur le premier point observé","isCorrect":false},{"id":"B","text":"La visée faite dans le sens du parcours uniquement","isCorrect":false},{"id":"C","text":"La visée faite sur le point d''altitude connue","isCorrect":false},{"id":"D","text":"La visée faite sur le point dont on cherche à déterminer l''altitude (point inconnu)","isCorrect":true}]'::jsonb, 'D', 'Par convention : la visée arrière se fait sur un point d''altitude CONNUE (ou de référence), la visée avant sur le point dont on veut DÉTERMINER l''altitude.', 20);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q21', 'concours-sujet-10', 'La visée entre deux points A et B a donné les résultats suivants : visée arrière 1975 mm ; visée avant 2705 mm. Quelle est la valeur de la dénivelée entre les deux points ?', '[{"id":"A","text":"-4680 mm","isCorrect":false},{"id":"B","text":"-730 mm","isCorrect":true},{"id":"C","text":"730 mm","isCorrect":false},{"id":"D","text":"4680 mm","isCorrect":false}]'::jsonb, 'B', 'Dénivelée = Visée arrière − Visée avant = 1975 − 2705 = -730 mm.', 21);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q22', 'concours-sujet-10', 'La mesure directe des distances peut se faire :', '[{"id":"A","text":"Au ruban (ou au décamètre/chaîne d''arpenteur)","isCorrect":true},{"id":"B","text":"À l''aide d''un théodolite","isCorrect":false},{"id":"C","text":"À l''aide d''une mire seule","isCorrect":false},{"id":"D","text":"À l''aide du cercle optique","isCorrect":false}]'::jsonb, 'A', 'Une mesure DIRECTE consiste à appliquer physiquement un instrument gradué (ruban, décamètre) le long de la distance à mesurer. Le théodolite et la mire, eux, servent à des mesures INDIRECTES (angles, nivellement optique).', 22);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q23', 'concours-sujet-10', 'À quoi sert l''armature dans le béton armé ?', '[{"id":"A","text":"Reprendre les efforts de compression du béton","isCorrect":false},{"id":"B","text":"Reprendre les efforts de traction du béton","isCorrect":true},{"id":"C","text":"Augmenter la résistance du béton en compression","isCorrect":false},{"id":"D","text":"Empêcher le béton de rompre au flambement","isCorrect":false}]'::jsonb, 'B', 'Le béton résiste bien en compression mais très mal en traction : l''acier, qui résiste bien en traction, est associé au béton pour reprendre ces efforts (principe fondateur du béton armé).', 23);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q24', 'concours-sujet-10', 'Le système qui sépare la collecte des eaux usées/vannes et celle des eaux pluviales, dans deux réseaux distincts, est appelé', '[{"id":"A","text":"Le système combiné","isCorrect":false},{"id":"B","text":"Le système unitaire","isCorrect":false},{"id":"C","text":"Le système mixte","isCorrect":false},{"id":"D","text":"Le système séparatif","isCorrect":true}]'::jsonb, 'D', 'Le système séparatif utilise 2 réseaux distincts (eaux usées/vannes d''un côté, eaux pluviales de l''autre) ; le système unitaire les collecte ensemble dans un seul réseau.', 24);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q25', 'concours-sujet-10', 'Le traitement des eaux usées permet avant tout de', '[{"id":"A","text":"Protéger l''environnement (et la santé publique) en évitant le rejet de pollution dans le milieu naturel","isCorrect":true},{"id":"B","text":"N''a aucune utilité réelle","isCorrect":false},{"id":"C","text":"Uniquement embellir le paysage","isCorrect":false},{"id":"D","text":"Polluer volontairement les cultures en aval","isCorrect":false}]'::jsonb, 'A', 'Le traitement des eaux usées vise à réduire la charge polluante avant rejet dans le milieu naturel, protégeant ainsi l''environnement et la santé publique.', 25);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q26', 'concours-sujet-10', 'À quoi sert la vibration du béton lors de sa mise en œuvre ?', '[{"id":"A","text":"Empêcher la ségrégation des granulats et chasser les bulles d''air (nids de cailloux)","isCorrect":true},{"id":"B","text":"Augmenter la résistance du béton au feu","isCorrect":false},{"id":"C","text":"Augmenter la résistance mécanique finale du béton au-delà de sa formulation","isCorrect":false},{"id":"D","text":"Accélérer la prise du ciment","isCorrect":false}]'::jsonb, 'A', 'La vibration remplit correctement le coffrage, chasse l''air emprisonné et évite la ségrégation (séparation gravier/mortier), améliorant la compacité réelle du béton en place.', 26);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q27', 'concours-sujet-10', 'À quoi servent les dévers sur une chaussée ?', '[{"id":"A","text":"Uniquement améliorer l''esthétique de la route","isCorrect":false},{"id":"B","text":"Augmenter la vitesse autorisée des véhicules","isCorrect":false},{"id":"C","text":"Faciliter l''évacuation des eaux de ruissellement (et améliorer la tenue des véhicules en courbe)","isCorrect":true},{"id":"D","text":"Réduire la largeur utile de la chaussée","isCorrect":false}]'::jsonb, 'C', 'Le dévers (pente transversale) évacue l''eau de pluie vers les côtés de la chaussée et, en courbe, contribue à compenser la force centrifuge subie par les véhicules.', 27);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q28', 'concours-sujet-10', 'Une largeur de voie de circulation courante retenue en dimensionnement routier est de l''ordre de 3,50 m ; pour une route à deux voies, cela correspond à une largeur de chaussée de l''ordre de', '[{"id":"A","text":"7 mètres","isCorrect":true},{"id":"B","text":"6,5 mètres","isCorrect":false},{"id":"C","text":"8 mètres","isCorrect":false},{"id":"D","text":"10 mètres","isCorrect":false}]'::jsonb, 'A', 'Avec une largeur de voie usuelle d''environ 3,50 m, une chaussée à 2 voies (une par sens) totalise généralement une largeur de l''ordre de 7 m (valeur de référence à adapter selon la norme/le référentiel routier retenu localement).', 28);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q29', 'concours-sujet-10', 'Les dos d''âne (ralentisseurs) permettent de', '[{"id":"A","text":"Augmenter le nombre de véhicules pouvant circuler","isCorrect":false},{"id":"B","text":"Protéger uniquement la chaussée de l''usure","isCorrect":false},{"id":"C","text":"Stopper complètement la circulation des véhicules","isCorrect":false},{"id":"D","text":"Ralentir les véhicules (dispositif de modération de la vitesse)","isCorrect":true}]'::jsonb, 'D', 'Un dos d''âne est un dispositif de sécurité routière conçu pour contraindre les conducteurs à réduire leur vitesse, notamment en zone sensible (écoles, agglomérations).', 29);
insert into public.qcm_questions (id, subject_id, question_text, options, correct_answer, explanation, "order") values ('s10-q30', 'concours-sujet-10', 'Un béton subit un retrait de 2%. Qu''appelle-t-on retrait ?', '[{"id":"A","text":"La diminution de la résistance du béton","isCorrect":false},{"id":"B","text":"L''augmentation du volume du béton","isCorrect":false},{"id":"C","text":"La diminution du volume du béton suite à l''évaporation de l''eau (et aux réactions internes)","isCorrect":true},{"id":"D","text":"Le gonflement du béton en présence d''humidité","isCorrect":false}]'::jsonb, 'C', 'Le retrait est une contraction (diminution de volume/longueur) du béton, principalement liée au départ d''eau (séchage) et aux réactions d''hydratation, distincte d''une perte de résistance.', 30);
